            name_guess=row["name_guess"],
            kind=row["kind"],
            git_remote=row["git_remote"],
            git_branch=row["git_branch"],
            git_commit=row["git_commit"],
            markers=json.loads(row["markers"] or "[]"),
            readme_excerpt=row["readme_excerpt"],
            command_guess=row["command_guess"],
