@dataclass
class RunProfile:
    """`run_profiles` 一列（D5 Run Profile v1，docs/DECISIONS.md）。某個
    (project_id, name) 底下不可變的一個 revision——身分一經建立永不改變，
    update/archive 一律新增一列（同 `ProjectVersion` 不可變精神）。「目前
    狀態」是該 (project_id, name) revision 最大的那一列：`status="approved"`
    表示可選用，`"archived"` 表示已下架但歷史仍可查。"""

    id: str
    project_id: str
    project_name: str
    name: str
    revision: int
    status: str
    command: Optional[str] = None
    setup_cmd: Optional[str] = None
    require_tag: Optional[str] = None
    supersedes_id: Optional[str] = None
    approval_id: Optional[int] = None
    created_by_actor_id: Optional[str] = None
    created_at: str = ""

    @staticmethod
    def from_row(row: sqlite3.Row) -> "RunProfile":
        return RunProfile(
            id=row["id"],
            project_id=row["project_id"],
            project_name=row["project_name"],
            name=row["name"],
            revision=row["revision"],
            status=row["status"],
            command=row["command"],
            setup_cmd=row["setup_cmd"],
            require_tag=row["require_tag"],
            supersedes_id=row["supersedes_id"],
            approval_id=row["approval_id"],
            created_by_actor_id=row["created_by_actor_id"],
            created_at=row["created_at"],
        )


@dataclass
class DispatchPolicy:
    """`dispatch_policies` 一列（Goal 2 Slice 3）。同 `RunProfile` 的不可變
    revision 精神——身分一經建立永不改變，update/archive 一律新增一列。
    「目前狀態」是該 (project_id, name) revision 最大的那一列。**本切片這個
    物件沒有任何運行時效果**，scheduler 完全不讀它。

    跟 `RunProfile` 的差異：這張表刻意不存 `supersedes_id`——哪一列取代
    哪一列完全由 (project_id, name, revision) 的排序決定，呼叫端要找「上一個
    revision」用 `list_dispatch_policy_revisions()` 依 revision 排序取得。"""

    id: str
    project_id: str
    project_name: str
    name: str
    revision: int
    status: str
    allowed_servers: list[str] = field(default_factory=list)
    require_tag: Optional[str] = None
    run_profile_id: Optional[str] = None
    dataset_required: bool = False
    max_concurrent_placements: int = 1
    valid_until: Optional[str] = None
    approval_id: Optional[int] = None
    created_by_actor_id: Optional[str] = None
    created_at: str = ""

    @staticmethod
    def from_row(row: sqlite3.Row) -> "DispatchPolicy":
        return DispatchPolicy(
            id=row["id"],
            project_id=row["project_id"],
            project_name=row["project_name"],
            name=row["name"],
            revision=row["revision"],
            status=row["status"],
            allowed_servers=json.loads(row["allowed_servers"]),
            require_tag=row["require_tag"],
            run_profile_id=row["run_profile_id"],
            dataset_required=bool(row["dataset_required"]),
            max_concurrent_placements=row["max_concurrent_placements"],
            valid_until=row["valid_until"],
            approval_id=row["approval_id"],
            created_by_actor_id=row["created_by_actor_id"],
            created_at=row["created_at"],
        )


@dataclass
class ServerObservation:
    """`server_observations` 一列（Goal 2 Slice 1，
    docs/GOAL_2_AUTOMATED_DISPATCH_PLAN.md）：monitor 每次探測的快照，純粹是
    歷史證據，不參與排程決策。`gpu_mem_used_mb`/`gpu_mem_total_mb` 是該次探測
    所有 GPU 的加總（沒讀到任何 GPU 時是 None，不是 0，避免跟「有 GPU 但用量
    是 0」混淆）。"""

    id: int
    server_name: str
    observed_at: str
    online: bool
    probe_ok: bool
    gpu_count: Optional[int] = None
    gpu_util_max: Optional[float] = None
    gpu_mem_used_mb: Optional[float] = None
    gpu_mem_total_mb: Optional[float] = None
    load1: Optional[float] = None
    mem_total_bytes: Optional[int] = None
    mem_available_bytes: Optional[int] = None
    disk_avail_bytes: Optional[int] = None

    @staticmethod
    def from_row(row: sqlite3.Row) -> "ServerObservation":
        return ServerObservation(
            id=row["id"],
            server_name=row["server_name"],
            observed_at=row["observed_at"],
            online=bool(row["online"]),
            probe_ok=bool(row["probe_ok"]),
            gpu_count=row["gpu_count"],
            gpu_util_max=row["gpu_util_max"],
            gpu_mem_used_mb=row["gpu_mem_used_mb"],
            gpu_mem_total_mb=row["gpu_mem_total_mb"],
            load1=row["load1"],
            mem_total_bytes=row["mem_total_bytes"],
            mem_available_bytes=row["mem_available_bytes"],
            disk_avail_bytes=row["disk_avail_bytes"],
        )


@dataclass
class ServerBootstrapReport:
    """`server_bootstrap_reports` 一列（Goal 3 Phase B）：一次 bootstrap
    執行的完整結果。`components`/`report` 存 JSON 文字（讀取時解析），
    `passed` 是 fail-closed 的總結論——解析不到報告或任何缺項都是 False。"""

    id: int
    host: str
    username: str
    port: int
    components: list[str]
    script_version: str
    script_sha256: str
    passed: bool
    report: dict
    approval_id: Optional[int]
    created_at: str

    @staticmethod
    def from_row(row: sqlite3.Row) -> "ServerBootstrapReport":
        try:
            components = json.loads(row["components"])
        except (json.JSONDecodeError, TypeError):
            components = []
        try:
            report = json.loads(row["report"])
        except (json.JSONDecodeError, TypeError):
            report = {}
        return ServerBootstrapReport(
            id=row["id"],
            host=row["host"],
            username=row["username"],
            port=row["port"],
            components=components if isinstance(components, list) else [],
            script_version=row["script_version"],
            script_sha256=row["script_sha256"],
            passed=bool(row["passed"]),
            report=report if isinstance(report, dict) else {},
            approval_id=row["approval_id"],
            created_at=row["created_at"],
        )


@dataclass
class Node:
    """`nodes` 一列（Goal 3 C2，INV-NODE-1）：一台工作機上的 Node Agent 身分。

    `secret_hash` 是憑證的 SHA-256；raw token 只在核發當下回傳一次，永不
    落庫。`status` 為 `enrolled`｜`retired`｜`revoked`。例行退役只允許
    drain 完成且 active=0；緊急撤銷則可立即執行。兩者都不刪列。
    """

    id: str
    server_name: str
    secret_hash: str
    status: str
    agent_version: Optional[str]
    last_heartbeat_at: Optional[str]
    created_at: str
    revoked_at: Optional[str] = None
    approval_id: Optional[int] = None
    previous_secret_hash: Optional[str] = None
    previous_secret_expires_at: Optional[str] = None
    primary_credential_id: Optional[str] = None
    pending_credential_id: Optional[str] = None
    pending_secret_hash: Optional[str] = None
    pending_activation_nonce_hash: Optional[str] = None
    pending_expires_at: Optional[str] = None
    pending_grace_sec: Optional[int] = None
    pending_created_at: Optional[str] = None
    pending_approval_id: Optional[int] = None
    last_activation_credential_id: Optional[str] = None
    last_activation_nonce_hash: Optional[str] = None
    last_activation_expires_at: Optional[str] = None
    last_activated_at: Optional[str] = None
    draining_at: Optional[str] = None
    retired_at: Optional[str] = None

    @property
    def is_active(self) -> bool:
        return self.status == "enrolled" and self.revoked_at is None

    @property
    def is_draining(self) -> bool:
        """Draining nodes keep their identity and finish their work; they are
        simply not offered anything new."""
        return self.draining_at is not None

    @staticmethod
    def from_row(row: sqlite3.Row) -> "Node":
        return Node(
            id=row["id"],
            server_name=row["server_name"],
            secret_hash=row["secret_hash"],
            status=row["status"],
            previous_secret_hash=(
                row["previous_secret_hash"]
                if "previous_secret_hash" in row.keys()
                else None
            ),
            previous_secret_expires_at=(
                row["previous_secret_expires_at"]
                if "previous_secret_expires_at" in row.keys()
                else None
            ),
            primary_credential_id=(
                row["primary_credential_id"]
                if "primary_credential_id" in row.keys()
                else None
            ),
            pending_credential_id=(
                row["pending_credential_id"]
                if "pending_credential_id" in row.keys()
                else None
            ),
            pending_secret_hash=(
                row["pending_secret_hash"]
                if "pending_secret_hash" in row.keys()
                else None
            ),
            pending_activation_nonce_hash=(
                row["pending_activation_nonce_hash"]
                if "pending_activation_nonce_hash" in row.keys()
                else None
            ),
            pending_expires_at=(
                row["pending_expires_at"]
                if "pending_expires_at" in row.keys()
                else None
            ),
            pending_grace_sec=(
                row["pending_grace_sec"]
                if "pending_grace_sec" in row.keys()
                else None
            ),
            pending_created_at=(
                row["pending_created_at"]
                if "pending_created_at" in row.keys()
                else None
            ),
            pending_approval_id=(
                row["pending_approval_id"]
                if "pending_approval_id" in row.keys()
                else None
            ),
            last_activation_credential_id=(
                row["last_activation_credential_id"]
                if "last_activation_credential_id" in row.keys()
                else None
            ),
            last_activation_nonce_hash=(
                row["last_activation_nonce_hash"]
                if "last_activation_nonce_hash" in row.keys()
                else None
            ),
            last_activation_expires_at=(
                row["last_activation_expires_at"]
                if "last_activation_expires_at" in row.keys()
                else None
            ),
            last_activated_at=(
                row["last_activated_at"]
                if "last_activated_at" in row.keys()
                else None
            ),
            draining_at=(
                row["draining_at"] if "draining_at" in row.keys() else None
            ),
            retired_at=(
                row["retired_at"] if "retired_at" in row.keys() else None
            ),
            agent_version=row["agent_version"],
            last_heartbeat_at=row["last_heartbeat_at"],
            created_at=row["created_at"],
            revoked_at=row["revoked_at"],
            approval_id=row["approval_id"],
        )


@dataclass
class NodeAttemptRow:
    """`node_attempts` 一列（Goal 3 C2，INV-NODE-2/3/5）。

    這是 attempt 的**持久真相**（INV-STATE-1）——lease 歸屬、是否 ack 過、
    終態，重啟後全靠這張表收斂，不靠任何 in-memory 狀態。
    """

    id: str
    job_id: int
    node_id: str
    status: str
    command_sha256: str
    lease_expires_at: str
    created_at: str
    acked_at: Optional[str] = None
    last_heartbeat_at: Optional[str] = None
    terminal_at: Optional[str] = None
    exit_code: Optional[int] = None
    log_tail: Optional[str] = None
    #: Goal 3 C3 stop-request：非 NULL＝已核准的停止請求已記下，等 agent
    #: 取回。**不代表已經停了**——終態仍以 agent 回報為準（INV-NODE-4）。
    stop_requested_at: Optional[str] = None
    stop_acked_at: Optional[str] = None
    #: DG-EXEC-ATTEMPT-v1 optional generic ownership link.  Legacy protocol
    #: attempts honestly remain NULL.
    execution_attempt_id: Optional[str] = None

    @staticmethod
    def from_row(row: sqlite3.Row) -> "NodeAttemptRow":
        return NodeAttemptRow(
            id=row["id"],
            job_id=row["job_id"],
            node_id=row["node_id"],
            status=row["status"],
            command_sha256=row["command_sha256"],
            lease_expires_at=row["lease_expires_at"],
            created_at=row["created_at"],
            acked_at=row["acked_at"],
            last_heartbeat_at=row["last_heartbeat_at"],
            terminal_at=row["terminal_at"],
            exit_code=row["exit_code"],
            log_tail=row["log_tail"],
            stop_requested_at=row["stop_requested_at"],
            stop_acked_at=row["stop_acked_at"],
            execution_attempt_id=row["execution_attempt_id"],
        )


