    # ---- server_observations（Goal 2 Slice 1，容量觀測持久化）-----------

    def insert_server_observation(
        self,
        *,
        server_name: str,
        online: bool,
        probe_ok: bool,
        gpu_count: Optional[int] = None,
        gpu_util_max: Optional[float] = None,
        gpu_mem_used_mb: Optional[float] = None,
        gpu_mem_total_mb: Optional[float] = None,
        load1: Optional[float] = None,
        mem_total_bytes: Optional[int] = None,
        mem_available_bytes: Optional[int] = None,
        disk_avail_bytes: Optional[int] = None,
    ) -> ServerObservation:
        """插入一筆探測快照。`observed_at` 一律用伺服器現在時間（`now_iso()`），
        不接受呼叫端傳入，避免時鐘漂移造成排序錯亂。"""
        observed_at = now_iso()
        with self.cursor() as cur:
            cur.execute(
                """
                INSERT INTO server_observations
                    (server_name, observed_at, online, probe_ok,
                     gpu_count, gpu_util_max, gpu_mem_used_mb, gpu_mem_total_mb,
                     load1, mem_total_bytes, mem_available_bytes, disk_avail_bytes)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    server_name,
                    observed_at,
                    1 if online else 0,
                    1 if probe_ok else 0,
                    gpu_count,
                    gpu_util_max,
                    gpu_mem_used_mb,
                    gpu_mem_total_mb,
                    load1,
                    mem_total_bytes,
                    mem_available_bytes,
                    disk_avail_bytes,
                ),
            )
            observation_id = int(cur.lastrowid)
            cur.execute(
                "SELECT * FROM server_observations WHERE id = ?", (observation_id,)
            )
            return ServerObservation.from_row(cur.fetchone())

    def list_server_observations(
        self, server_name: str, *, since_iso: str, limit: int
    ) -> list[ServerObservation]:
        """某台伺服器 `since_iso` 之後（含）的觀測列，最新在前。`limit` 由
        呼叫端（API 層）先夾限範圍，這裡不重複做邊界檢查。"""
        with self.cursor() as cur:
            cur.execute(
                """
                SELECT * FROM server_observations
                WHERE server_name = ? AND observed_at >= ?
                ORDER BY observed_at DESC, id DESC
                LIMIT ?
                """,
                (server_name, since_iso, limit),
            )
            return [ServerObservation.from_row(row) for row in cur.fetchall()]

    def prune_server_observations(self, *, before_iso: str) -> int:
        """刪除 `observed_at` 早於 `before_iso` 的觀測列，回傳刪除筆數。由
        monitor 迴圈機會性呼叫（best-effort 保留策略），不是排程強制的
        cleanup job。"""
        with self.cursor() as cur:
            cur.execute(
                "DELETE FROM server_observations WHERE observed_at < ?",
                (before_iso,),
            )
            return cur.rowcount if cur.rowcount is not None else 0

    def count_active_coding_jobs_by_server(self) -> dict[str, int]:
        """Goal 3 Phase D-1：每台 Runner 目前 active（queued＋running）的
        coding job 數——`pick_codex_runner()` 的決定性負載證據。queued 的
        job 用 `pin_server`（v2 coding job 建立時一律 pin 到選定 Runner），
        running 的用實際 `server`；兩者都沒有的列不計入任何機器。"""
        with self.cursor() as cur:
            cur.execute(
                """
                SELECT COALESCE(server, pin_server) AS runner, COUNT(*) AS n
                FROM jobs
                WHERE type = 'coding' AND status IN ('queued', 'running')
                      AND COALESCE(server, pin_server) IS NOT NULL
                GROUP BY runner
                """
            )
            return {row["runner"]: row["n"] for row in cur.fetchall()}

    # ---- nodes / node_attempts（Goal 3 C2，INV-NODE-*）------------------

    def _append_node_audit_event(
        self,
        cursor: sqlite3.Cursor,
        *,
        action: str,
        resource_id: str,
        params: dict[str, Any],
        approval_id: Optional[int] = None,
        result: str = "ok",
        event_id: Optional[str] = None,
        occurred_at: Optional[str] = None,
    ) -> None:
        """Append a safe Node lifecycle envelope inside its transaction.

        Node credentials are bearer material.  Lifecycle events therefore
        carry only bounded state/relationship facts; token values, digests,
        activation nonces, and credential identifiers never enter durable
        audit parameters.
        """

        self.append_durable_audit_event_in_transaction(
            cursor,
            action=action,
            params=params,
            result=result,
            resource_type="node",
            resource_id=resource_id,
            approval_id=approval_id,
            event_id=event_id,
            occurred_at=occurred_at,
        )

    def _append_node_attempt_audit_event(
        self,
        cursor: sqlite3.Cursor,
        *,
        action: str,
        resource_id: str,
        params: dict[str, Any],
        event_id: Optional[str] = None,
        occurred_at: Optional[str] = None,
    ) -> None:
        """Append a safe Node-attempt lifecycle envelope in its transaction."""

        self.append_durable_audit_event_in_transaction(
            cursor,
            action=action,
            params=params,
            result="ok",
            resource_type="node_attempt",
            resource_id=resource_id,
            event_id=event_id,
            occurred_at=occurred_at,
        )

    def _append_node_artifact_audit_event(
        self,
        cursor: sqlite3.Cursor,
        *,
        attempt_id: str,
        node_id: str,
        execution_attempt_id: Optional[str],
        artifacts: list[tuple[str, int, str, str]],
    ) -> None:
        """Append one idempotent, content-free artifact report summary."""

        if not artifacts:
            return
        fingerprint = [
            {
                "relative_path": relative_path,
                "kind": kind,
                "size_bytes": int(size_bytes),
                "sha256": sha256,
            }
            for relative_path, size_bytes, sha256, kind in sorted(
                artifacts, key=lambda item: item[0]
            )
        ]
        report_digest = utf8_sha256(canonical_json(fingerprint))
        resource_type = (
            "execution_attempt" if execution_attempt_id is not None else "node_attempt"
        )
        resource_id = execution_attempt_id or attempt_id
        self.append_durable_audit_event_in_transaction(
            cursor,
            action="execution_artifact_recorded",
            params={
                "node_id": node_id,
                "artifact_count": len(artifacts),
                "artifact_kinds": sorted({kind for _, _, _, kind in artifacts}),
                "report_digest": report_digest,
            },
            result="ok",
            resource_type=resource_type,
            resource_id=str(resource_id),
            event_id=f"{resource_type}:{resource_id}:artifacts:{report_digest}",
        )

    def _append_execution_attempt_artifact_audit_event(
        self,
        cursor: sqlite3.Cursor,
        *,
        attempt_id: str,
        approval_id: int,
        artifacts: list[tuple[str, str, int, str]],
    ) -> None:
        """Append a path-free, idempotent summary for SSH artifact evidence."""

        if not artifacts:
            return
        fingerprint = [
            {
                "relative_path": relative_path,
                "kind": kind,
                "size_bytes": size_bytes,
                "sha256": sha256,
            }
            for relative_path, kind, size_bytes, sha256 in sorted(
                artifacts, key=lambda item: item[0]
            )
        ]
        report_digest = utf8_sha256(canonical_json(fingerprint))
        self.append_durable_audit_event_in_transaction(
            cursor,
            action="execution_artifact_recorded",
            params={
                "backend": "ssh",
                "artifact_count": len(artifacts),
                "artifact_kinds": sorted({kind for _, kind, _, _ in artifacts}),
                "report_digest": report_digest,
            },
            result="ok",
            resource_type="execution_attempt",
            resource_id=attempt_id,
            approval_id=approval_id,
            event_id=f"execution_attempt:{attempt_id}:artifacts:{report_digest}",
        )

    def insert_node(
        self,
        *,
        node_id: str,
        server_name: str,
        secret_hash: str,
        approval_id: Optional[int] = None,
    ) -> Node:
        """登錄一個 node（INV-NODE-1）。呼叫端負責產生憑證並只把 digest
        交進來——raw token 永不進這一層。"""
        with self._immediate_cursor() as cur:
            created_at = self._sqlite_now(cur)
            cur.execute(
                """
                INSERT INTO nodes
                    (id, server_name, secret_hash, status, agent_version,
                     last_heartbeat_at, created_at, revoked_at, approval_id)
                VALUES (?, ?, ?, 'enrolled', NULL, NULL, ?, NULL, ?)
                """,
                (node_id, server_name, secret_hash, created_at, approval_id),
            )
            self._append_node_audit_event(
                cur,
                action="node_enrolled",
                resource_id=node_id,
                params={"server": server_name},
                approval_id=approval_id,
                event_id=f"node:{node_id}:enrolled",
                occurred_at=created_at,
            )
            cur.execute("SELECT * FROM nodes WHERE id = ?", (node_id,))
            return Node.from_row(cur.fetchone())

    def apply_node_enroll_decision(
        self,
        *,
        approval_id: int,
        node_id: str,
        server_name: str,
        secret_hash: str,
        decision_actor_id: Optional[str] = None,
        decision_actor_kind: Optional[str] = None,
        decision_mechanism: Optional[str] = None,
        approval_note: Optional[str] = None,
    ) -> Node:
        """Enroll a Node and decide its approval in one durable transaction.

        The raw credential is generated and returned by the approval layer; this
        method receives only its digest.  The node row, lifecycle event, and
        approval decision share one immediate transaction so an audit append
        failure cannot leave an enrolled node behind while its approval remains
        pending.  Direct ``insert_node`` callers retain their historical
        non-approval-compatible primitive.
        """

        if not isinstance(node_id, str) or not node_id.strip():
            raise ValueError("node_id is required")
        if not isinstance(server_name, str) or not server_name.strip():
            raise ValueError("server_name is required")
        if not isinstance(secret_hash, str) or not secret_hash.strip():
            raise ValueError("secret_hash is required")

        with self._immediate_cursor() as cur:
            approval = cur.execute(
                "SELECT * FROM approvals WHERE id = ?", (approval_id,)
            ).fetchone()
            if approval is None:
                raise ValueError("node enrollment approval not found")
            if approval["kind"] != "node_enroll" or approval["status"] != "pending":
                raise ValueError("node enrollment approval is no longer pending")
            try:
                payload = json.loads(approval["payload"])
            except (TypeError, json.JSONDecodeError) as exc:
                raise ValueError("node enrollment approval payload is malformed") from exc
            if not isinstance(payload, dict) or payload.get("server") != server_name:
                raise ValueError("node enrollment approval target changed")

            active = cur.execute(
                """
                SELECT 1 FROM nodes
                WHERE server_name = ? AND status = 'enrolled' AND revoked_at IS NULL
                LIMIT 1
                """,
                (server_name,),
            ).fetchone()
            if active is not None:
                raise ValueError("server already has an active node")

            created_at = self._sqlite_now(cur)
            cur.execute(
                """
                INSERT INTO nodes
                    (id, server_name, secret_hash, status, agent_version,
                     last_heartbeat_at, created_at, revoked_at, approval_id)
                VALUES (?, ?, ?, 'enrolled', NULL, NULL, ?, NULL, ?)
                """,
                (node_id, server_name, secret_hash, created_at, approval_id),
            )
            self._append_node_audit_event(
                cur,
                action="node_enrolled",
                resource_id=node_id,
                params={"server": server_name},
                approval_id=approval_id,
                event_id=f"node:{node_id}:enrolled",
                occurred_at=created_at,
            )

            decided_at = self._sqlite_now(cur)
            cur.execute(
                """
                UPDATE approvals
                SET status = 'approved', decided_at = ?,
                    decision_actor_id = ?, decision_mechanism = ?, note = ?
                WHERE id = ? AND status = 'pending'
                """,
                (
                    decided_at,
                    decision_actor_id,
                    decision_mechanism,
                    approval_note,
                    approval_id,
                ),
            )
            if cur.rowcount != 1:
                raise ValueError("node enrollment approval decision conflict")
            self._append_approval_decided_audit(
                cur,
                approval_id=approval_id,
                kind="node_enroll",
                status="approved",
                decision_actor_id=decision_actor_id,
                decision_actor_kind=decision_actor_kind,
                decision_mechanism=decision_mechanism,
            )
            row = cur.execute("SELECT * FROM nodes WHERE id = ?", (node_id,)).fetchone()
            if row is None:  # pragma: no cover - guarded by INSERT above
                raise RuntimeError("node disappeared after enrollment")
            return Node.from_row(row)

    def get_node(self, node_id: str) -> Optional[Node]:
        with self.cursor() as cur:
            cur.execute("SELECT * FROM nodes WHERE id = ?", (node_id,))
            row = cur.fetchone()
            return Node.from_row(row) if row else None

    def list_nodes(self, *, server_name: Optional[str] = None) -> list[Node]:
        with self.cursor() as cur:
            if server_name is None:
                cur.execute("SELECT * FROM nodes ORDER BY created_at ASC, id ASC")
            else:
                cur.execute(
                    "SELECT * FROM nodes WHERE server_name = ? ORDER BY created_at ASC",
                    (server_name,),
                )
            return [Node.from_row(row) for row in cur.fetchall()]

    def revoke_node_with_execution_hold(
        self,
        node_id: str,
        *,
        approval_id: Optional[int] = None,
        finalize_approval: bool = False,
        decision_actor_id: Optional[str] = None,
        decision_actor_kind: Optional[str] = None,
        decision_mechanism: Optional[str] = None,
        approval_note: Optional[str] = None,
    ) -> Optional[dict[str, Any]]:
        """Atomically revoke one Node and freeze all of its active ownership.

        A security revocation is not terminal evidence.  The associated Job,
        backend, target and attempt state therefore stay unchanged; only
        liveness becomes unknown and a durable recovery hold prevents new
        material outbox effects.  Legacy Node attempts have no generic
        liveness column, so their ownership rows are preserved verbatim and
        returned as affected evidence.
        """
        with self._immediate_cursor() as cur:
            approval = None
            if finalize_approval:
                if approval_id is None:
                    raise ValueError("node revocation approval is required")
                approval = cur.execute(
                    "SELECT * FROM approvals WHERE id = ?", (approval_id,)
                ).fetchone()
                if approval is None:
                    raise ValueError("node revocation approval not found")
                if approval["kind"] != "node_revoke" or approval["status"] != "pending":
                    raise ValueError("node revocation approval is no longer pending")
            cur.execute("SELECT * FROM nodes WHERE id = ?", (node_id,))
            existing = cur.fetchone()
            if existing is None:
                return None
            if existing["revoked_at"] is not None:
                return {
                    "node": Node.from_row(existing),
                    "execution_attempt_ids": [],
                    "node_attempt_ids": [],
                    "legacy_node_attempt_ids": [],
                    "already_revoked": True,
                }

            revoked_at = self._sqlite_now(cur)
            cur.execute(
                """
                SELECT DISTINCT
                       execution.id AS execution_attempt_id,
                       execution.state AS execution_state,
                       execution.liveness AS execution_liveness,
                       node_attempt.id AS node_attempt_id
                FROM node_attempts AS node_attempt
                JOIN execution_attempts AS execution
                  ON execution.id = node_attempt.execution_attempt_id
                WHERE node_attempt.node_id = ?
                  AND node_attempt.terminal_at IS NULL
                  AND execution.backend = 'node'
                  AND execution.state IN ('leased', 'dispatching', 'running')
                ORDER BY execution.id, node_attempt.id
                """,
                (node_id,),
            )
            generic_rows = [dict(row) for row in cur.fetchall()]
            cur.execute(
                """
                SELECT id
                FROM node_attempts
                WHERE node_id = ?
                  AND execution_attempt_id IS NULL
                  AND terminal_at IS NULL
                  AND status IN ('leased', 'acked', 'running')
                ORDER BY id
                """,
                (node_id,),
            )
            legacy_node_attempt_ids = [str(row["id"]) for row in cur.fetchall()]

            cur.execute(
                """
                UPDATE nodes
                SET status = 'revoked', revoked_at = ?,
                    previous_secret_hash = NULL,
                    previous_secret_expires_at = NULL,
                    pending_credential_id = NULL,
                    pending_secret_hash = NULL,
                    pending_activation_nonce_hash = NULL,
                    pending_expires_at = NULL,
                    pending_grace_sec = NULL,
                    pending_created_at = NULL,
                    pending_approval_id = NULL,
                    last_activation_credential_id = NULL,
                    last_activation_nonce_hash = NULL,
                    last_activation_expires_at = NULL
                WHERE id = ? AND revoked_at IS NULL
                """,
                (revoked_at, node_id),
            )
            if cur.rowcount != 1:
                raise ValueError("node revocation conflict")

            execution_attempt_ids: list[str] = []
            node_attempt_ids: list[str] = []
            for row in generic_rows:
                attempt_id = str(row["execution_attempt_id"])
                node_attempt_id = str(row["node_attempt_id"])
                cur.execute(
                    """
                    UPDATE execution_attempts
                    SET liveness = 'unknown',
                        recovery_hold_reason = 'security_credential_revoked'
                    WHERE id = ?
                      AND state = ?
                      AND liveness = ?
                    """,
                    (
                        attempt_id,
                        row["execution_state"],
                        row["execution_liveness"],
                    ),
                )
                if cur.rowcount != 1:
                    raise ValueError("node revocation attempt conflict")
                self._append_execution_event(
                    cur,
                    attempt_id=attempt_id,
                    event_type="security_credential_revoked",
                    from_state=row["execution_state"],
                    to_state=row["execution_state"],
                    from_liveness=row["execution_liveness"],
                    to_liveness="unknown",
                    reason_code="security_credential_revoked",
                    evidence={
                        "node_id": node_id,
                        "node_attempt_id": node_attempt_id,
                        "credential_scope": "single_node",
                    },
                    created_at=revoked_at,
                )
                execution_attempt_ids.append(attempt_id)
                node_attempt_ids.append(node_attempt_id)

            self._append_node_audit_event(
                cur,
                action="node_revoked",
                resource_id=node_id,
                params={
                    "server": str(existing["server_name"]),
                    "execution_attempt_count": len(execution_attempt_ids),
                    "node_attempt_count": len(node_attempt_ids),
                    "legacy_node_attempt_count": len(legacy_node_attempt_ids),
                    "recovery_hold_reason": "security_credential_revoked",
                },
                approval_id=approval_id,
                event_id=f"node:{node_id}:revoked",
                occurred_at=revoked_at,
            )

            if finalize_approval:
                decided_at = self._sqlite_now(cur)
                note = approval_note or (
                    f"node {node_id} 憑證已撤銷；"
                    f"{len(execution_attempt_ids)} 個 execution attempt "
                    "已進入 security credential recovery hold"
                )
                cur.execute(
                    """
                    UPDATE approvals
                    SET status = 'approved', decided_at = ?,
                        decision_actor_id = ?, decision_mechanism = ?, note = ?
                    WHERE id = ? AND status = 'pending'
                    """,
                    (
                        decided_at,
                        decision_actor_id,
                        decision_mechanism,
                        note,
                        approval_id,
                    ),
                )
                if cur.rowcount != 1:
                    raise ValueError("node revocation approval decision conflict")
                self._append_approval_decided_audit(
                    cur,
                    approval_id=approval_id,
                    kind="node_revoke",
                    status="approved",
                    decision_actor_id=decision_actor_id,
                    decision_actor_kind=decision_actor_kind,
                    decision_mechanism=decision_mechanism,
                )

            cur.execute("SELECT * FROM nodes WHERE id = ?", (node_id,))
            row = cur.fetchone()
            return {
                "node": Node.from_row(row),
                "execution_attempt_ids": execution_attempt_ids,
                "node_attempt_ids": node_attempt_ids,
                "legacy_node_attempt_ids": legacy_node_attempt_ids,
                "already_revoked": False,
            }

    def revoke_node(
        self, node_id: str, *, approval_id: Optional[int] = None
    ) -> Optional[Node]:
        """Compatibility projection for the richer atomic revocation result."""
        result = self.revoke_node_with_execution_hold(
            node_id, approval_id=approval_id
        )
        return result["node"] if result is not None else None

    def _require_pending_node_rotation_approval(
        self,
        cursor: sqlite3.Cursor,
        *,
        approval_id: Optional[int],
        node_id: str,
        server_name: str,
        rotation_mode: str,
        overlap_sec: Optional[int],
        pending_ttl_sec: Optional[int] = None,
        replace_pending_credential_id: Optional[str] = None,
    ) -> None:
        """Validate the immutable rotation approval inside the node UoW."""
        if approval_id is None:
            raise ValueError("node rotation approval is required")
        approval = cursor.execute(
            "SELECT kind, status, payload FROM approvals WHERE id = ?",
            (approval_id,),
        ).fetchone()
        if approval is None:
            raise ValueError("node rotation approval not found")
        if approval["kind"] != "node_rotate" or approval["status"] != "pending":
            raise ValueError("node rotation approval is no longer pending")
        try:
            payload = json.loads(approval["payload"])
        except (TypeError, json.JSONDecodeError) as exc:
            raise ValueError("node rotation approval payload is malformed") from exc
        if not isinstance(payload, dict):
            raise ValueError("node rotation approval payload is malformed")
        if (
            payload.get("node_id") != node_id
            or payload.get("server") != server_name
            or payload.get("rotation_mode") != rotation_mode
            or payload.get("overlap_sec") != overlap_sec
            or payload.get("pending_ttl_sec") != pending_ttl_sec
            or payload.get("replace_pending_credential_id")
            != replace_pending_credential_id
        ):
            raise ValueError("node rotation approval target changed")

    def _finalize_node_rotation_approval(
        self,
        cursor: sqlite3.Cursor,
        *,
        approval_id: int,
        note: str,
        decision_actor_id: Optional[str],
        decision_actor_kind: Optional[str],
        decision_mechanism: Optional[str],
    ) -> None:
        """Decide a node-rotation approval before its transaction commits."""
        decided_at = self._sqlite_now(cursor)
        cursor.execute(
            """
            UPDATE approvals
            SET status = 'approved', decided_at = ?,
                decision_actor_id = ?, decision_mechanism = ?, note = ?
            WHERE id = ? AND kind = 'node_rotate' AND status = 'pending'
            """,
            (
                decided_at,
                decision_actor_id,
                decision_mechanism,
                note,
                approval_id,
            ),
        )
        if cursor.rowcount != 1:
            raise ValueError("node rotation approval decision conflict")
        self._append_approval_decided_audit(
            cursor,
            approval_id=approval_id,
            kind="node_rotate",
            status="approved",
            decision_actor_id=decision_actor_id,
            decision_actor_kind=decision_actor_kind,
            decision_mechanism=decision_mechanism,
        )

    def update_node_secret(
        self,
        node_id: str,
        secret_hash: str,
        *,
        overlap_sec: Optional[int] = None,
        approval_id: Optional[int] = None,
        finalize_approval: bool = False,
        decision_actor_id: Optional[str] = None,
        decision_actor_kind: Optional[str] = None,
        decision_mechanism: Optional[str] = None,
        approval_note: Optional[str] = None,
    ) -> None:
        """Rotate the credential digest.

        DG-NODE-V2 N-4: with `overlap_sec`, the outgoing secret is retained and
        stays valid until it expires, so an agent that has not yet picked up
        the new token does not start failing. A hard cutover turns every
        rotation into an outage, which in practice means rotations stop
        happening. Without `overlap_sec` the old behavior is kept: immediate
        invalidation, which is what an emergency re-key wants.
        """
        with self._immediate_cursor() as cur:
            if overlap_sec is not None and (
                isinstance(overlap_sec, bool) or overlap_sec < 1
            ):
                raise ValueError("rotation overlap must be a positive number of seconds")
            cur.execute("SELECT server_name FROM nodes WHERE id = ?", (node_id,))
            existing = cur.fetchone()
            if existing is None:
                return
            if finalize_approval:
                self._require_pending_node_rotation_approval(
                    cur,
                    approval_id=approval_id,
                    node_id=node_id,
                    server_name=str(existing["server_name"]),
                    rotation_mode="legacy_overlap",
                    overlap_sec=overlap_sec,
                )
            if overlap_sec is None:
                cur.execute(
                    "UPDATE nodes SET secret_hash = ?, previous_secret_hash = NULL,"
                    " previous_secret_expires_at = NULL,"
                    " pending_credential_id = NULL, pending_secret_hash = NULL,"
                    " pending_activation_nonce_hash = NULL, pending_expires_at = NULL,"
                    " pending_grace_sec = NULL, pending_created_at = NULL,"
                    " pending_approval_id = NULL"
                    " WHERE id = ? AND status = 'enrolled' AND revoked_at IS NULL",
                    (secret_hash, node_id),
                )
                if cur.rowcount == 1:
                    self._append_node_audit_event(
                        cur,
                        action="node_rotated",
                        resource_id=node_id,
                        params={
                            "server": str(existing["server_name"]),
                            "rotation_mode": "legacy_hard_cutover",
                        },
                        approval_id=approval_id,
                    )
                    if finalize_approval:
                        self._finalize_node_rotation_approval(
                            cur,
                            approval_id=approval_id,
                            note=(
                                approval_note
                                or f"node {node_id} 已換發憑證（只顯示這一次；舊憑證立即失效）"
                            ),
                            decision_actor_id=decision_actor_id,
                            decision_actor_kind=decision_actor_kind,
                            decision_mechanism=decision_mechanism,
                        )
                return
            expires_at = (
                datetime.now(timezone.utc) + timedelta(seconds=int(overlap_sec))
            ).isoformat()
            cur.execute(
                """
                UPDATE nodes
                SET previous_secret_hash = secret_hash,
                    previous_secret_expires_at = ?,
                    secret_hash = ?,
                    pending_credential_id = NULL,
                    pending_secret_hash = NULL,
                    pending_activation_nonce_hash = NULL,
                    pending_expires_at = NULL,
                    pending_grace_sec = NULL,
                    pending_created_at = NULL,
                    pending_approval_id = NULL
                WHERE id = ? AND status = 'enrolled' AND revoked_at IS NULL
                """,
                (expires_at, secret_hash, node_id),
            )
            if cur.rowcount == 1:
                self._append_node_audit_event(
                    cur,
                    action="node_rotated",
                    resource_id=node_id,
                    params={
                        "server": str(existing["server_name"]),
                        "rotation_mode": "legacy_overlap",
                        "overlap_sec": int(overlap_sec),
                    },
                    approval_id=approval_id,
                )
                if finalize_approval:
                    self._finalize_node_rotation_approval(
                        cur,
                        approval_id=approval_id,
                        note=(
                            approval_note
                            or f"node {node_id} 已換發憑證（只顯示這一次；舊憑證保留 {overlap_sec} 秒）"
                        ),
                        decision_actor_id=decision_actor_id,
                        decision_actor_kind=decision_actor_kind,
                        decision_mechanism=decision_mechanism,
                    )

    def stage_node_credential(
        self,
        *,
        node_id: str,
        credential_id: str,
        secret_hash: str,
        activation_nonce_hash: str,
        pending_ttl_sec: int,
        grace_sec: int,
        approval_id: Optional[int],
        replace_pending_credential_id: Optional[str] = None,
        finalize_approval: bool = False,
        decision_actor_id: Optional[str] = None,
        decision_actor_kind: Optional[str] = None,
        decision_mechanism: Optional[str] = None,
        approval_note: Optional[str] = None,
    ) -> Optional[Node]:
        """Create a non-authoritative pending credential.

        The current primary is deliberately untouched. A live pending
        credential may only be replaced when the approval pinned its exact ID;
        this prevents an old approval from cancelling a newer operator action.
        """
        if isinstance(pending_ttl_sec, bool) or not (60 <= pending_ttl_sec <= 604800):
            raise ValueError("pending credential ttl is out of range")
        if isinstance(grace_sec, bool) or not (1 <= grace_sec <= 86400):
            raise ValueError("credential grace is out of range")
        with self._immediate_cursor() as cur:
            observed_at = self._sqlite_now(cur)
            cur.execute("SELECT * FROM nodes WHERE id = ?", (node_id,))
            row = cur.fetchone()
            if (
                row is None
                or row["status"] != "enrolled"
                or row["revoked_at"] is not None
            ):
                return None
            if finalize_approval:
                self._require_pending_node_rotation_approval(
                    cur,
                    approval_id=approval_id,
                    node_id=node_id,
                    server_name=str(row["server_name"]),
                    rotation_mode="staged_activation",
                    overlap_sec=grace_sec,
                    pending_ttl_sec=pending_ttl_sec,
                    replace_pending_credential_id=replace_pending_credential_id,
                )
            existing_id = row["pending_credential_id"]
            existing_expires = row["pending_expires_at"]
            existing_live = bool(
                existing_id
                and existing_expires
                and str(existing_expires) > observed_at
            )
            if (
                replace_pending_credential_id is not None
                and existing_id != replace_pending_credential_id
            ):
                raise ValueError("pending credential replacement target changed")
            if existing_live and replace_pending_credential_id != existing_id:
                raise ValueError("live pending credential already exists")
            pending_expires_at = self._sqlite_after(cur, pending_ttl_sec)
            created_at = self._sqlite_now(cur)
            cur.execute(
                """
                UPDATE nodes
                SET pending_credential_id = ?,
                    pending_secret_hash = ?,
                    pending_activation_nonce_hash = ?,
                    pending_expires_at = ?,
                    pending_grace_sec = ?,
                    pending_created_at = ?,
                    pending_approval_id = ?
                WHERE id = ? AND status = 'enrolled' AND revoked_at IS NULL
                """,
                (
                    credential_id,
                    secret_hash,
                    activation_nonce_hash,
                    pending_expires_at,
                    grace_sec,
                    created_at,
                    approval_id,
                    node_id,
                ),
            )
            if cur.rowcount != 1:
                return None
            self._append_node_audit_event(
                cur,
                action="node_rotated",
                resource_id=node_id,
                params={
                    "server": str(row["server_name"]),
                    "rotation_mode": "staged",
                    "pending_ttl_sec": int(pending_ttl_sec),
                    "grace_sec": int(grace_sec),
                },
                approval_id=approval_id,
                event_id=f"node:{node_id}:rotation:{credential_id}:staged",
                occurred_at=created_at,
            )
            if finalize_approval:
                self._finalize_node_rotation_approval(
                    cur,
                    approval_id=approval_id,
                    note=(
                        approval_note
                        or f"node {node_id} 已建立待啟用憑證（token/nonce 只顯示這一次）"
                    ),
                    decision_actor_id=decision_actor_id,
                    decision_actor_kind=decision_actor_kind,
                    decision_mechanism=decision_mechanism,
                )
            cur.execute("SELECT * FROM nodes WHERE id = ?", (node_id,))
            return Node.from_row(cur.fetchone())

    def activate_pending_node_credential(
        self,
        *,
        node_id: str,
        credential_id: str,
        secret_hash: str,
        activation_nonce_hash: str,
    ) -> Optional[dict[str, Any]]:
        """Atomically promote a verified pending secret and start old-key grace.

        A bounded activation receipt makes a committed activation retryable
        after response loss. The receipt stores digests only.
        """
        with self._immediate_cursor() as cur:
            observed_at = self._sqlite_now(cur)
            cur.execute("SELECT * FROM nodes WHERE id = ?", (node_id,))
            row = cur.fetchone()
            if (
                row is None
                or row["status"] != "enrolled"
                or row["revoked_at"] is not None
            ):
                return None

            if (
                row["pending_credential_id"] == credential_id
                and row["pending_secret_hash"] == secret_hash
                and row["pending_activation_nonce_hash"] == activation_nonce_hash
                and row["pending_expires_at"] is not None
                and row["pending_expires_at"] > observed_at
            ):
                grace_sec = row["pending_grace_sec"]
                if not isinstance(grace_sec, int) or not (1 <= grace_sec <= 86400):
                    return None
                grace_expires_at = self._sqlite_after(cur, grace_sec)
                activated_at = self._sqlite_now(cur)
                cur.execute(
                    """
                    UPDATE nodes
                    SET previous_secret_hash = secret_hash,
                        previous_secret_expires_at = ?,
                        secret_hash = pending_secret_hash,
                        primary_credential_id = pending_credential_id,
                        last_activation_credential_id = pending_credential_id,
                        last_activation_nonce_hash = pending_activation_nonce_hash,
                        last_activation_expires_at = ?,
                        last_activated_at = ?,
                        pending_credential_id = NULL,
                        pending_secret_hash = NULL,
                        pending_activation_nonce_hash = NULL,
                        pending_expires_at = NULL,
                        pending_grace_sec = NULL,
                        pending_created_at = NULL,
                        pending_approval_id = NULL
                    WHERE id = ? AND status = 'enrolled' AND revoked_at IS NULL
                      AND pending_credential_id = ?
                      AND pending_secret_hash = ?
                      AND pending_activation_nonce_hash = ?
                    """,
                    (
                        grace_expires_at,
                        grace_expires_at,
                        activated_at,
                        node_id,
                        credential_id,
                        secret_hash,
                        activation_nonce_hash,
                    ),
                )
                if cur.rowcount != 1:
                    return None
                duplicate = False
                self._append_node_audit_event(
                    cur,
                    action="node_credential_activated",
                    resource_id=node_id,
                    params={"activation_mode": "staged"},
                    approval_id=row["pending_approval_id"],
                    event_id=f"node:{node_id}:rotation:{credential_id}:activated",
                    occurred_at=activated_at,
                )
            elif (
                row["primary_credential_id"] == credential_id
                and row["secret_hash"] == secret_hash
                and row["last_activation_credential_id"] == credential_id
                and row["last_activation_nonce_hash"] == activation_nonce_hash
                and row["last_activation_expires_at"] is not None
                and row["last_activation_expires_at"] > observed_at
            ):
                duplicate = True
            else:
                return None

            cur.execute("SELECT * FROM nodes WHERE id = ?", (node_id,))
            refreshed = cur.fetchone()
            return {
                "node": Node.from_row(refreshed),
                "credential_id": credential_id,
                "duplicate": duplicate,
            }

    def get_node_retirement_blockers(
        self, node_id: str
    ) -> dict[str, list[str]]:
        """Return exact active ownership that prevents routine retirement."""
        with self.cursor() as cur:
            current_time = self._sqlite_now(cur)
            cur.execute(
                """
                SELECT DISTINCT execution.id
                FROM node_attempts AS node_attempt
                JOIN execution_attempts AS execution
                  ON execution.id = node_attempt.execution_attempt_id
                WHERE node_attempt.node_id = ?
                  AND node_attempt.terminal_at IS NULL
                  AND execution.state IN ('leased', 'dispatching', 'running')
                ORDER BY execution.id
                """,
                (node_id,),
            )
            execution_attempt_ids = [str(row["id"]) for row in cur.fetchall()]
            cur.execute(
                """
                SELECT id
                FROM node_attempts
                WHERE node_id = ?
                  AND execution_attempt_id IS NULL
                  AND terminal_at IS NULL
                  AND (
                        (status = 'leased' AND lease_expires_at > ?)
                        OR status IN ('acked', 'running')
                      )
                ORDER BY id
                """,
                (node_id, current_time),
            )
            legacy_node_attempt_ids = [str(row["id"]) for row in cur.fetchall()]
        return {
            "execution_attempt_ids": execution_attempt_ids,
            "legacy_node_attempt_ids": legacy_node_attempt_ids,
        }

    def _require_pending_node_retirement_approval(
        self,
        cursor: sqlite3.Cursor,
        *,
        approval_id: Optional[int],
        node_id: str,
        server_name: str,
        action: str,
    ) -> None:
        """Validate the immutable retirement approval inside the node UoW."""
        if approval_id is None:
            raise ValueError("node retirement approval is required")
        approval = cursor.execute(
            "SELECT kind, status, payload FROM approvals WHERE id = ?",
            (approval_id,),
        ).fetchone()
        if approval is None:
            raise ValueError("node retirement approval not found")
        if approval["kind"] != "node_retire" or approval["status"] != "pending":
            raise ValueError("node retirement approval is no longer pending")
        try:
            payload = json.loads(approval["payload"])
        except (TypeError, json.JSONDecodeError) as exc:
            raise ValueError("node retirement approval payload is malformed") from exc
        if not isinstance(payload, dict):
            raise ValueError("node retirement approval payload is malformed")
        if (
            payload.get("node_id") != node_id
            or payload.get("server") != server_name
            or payload.get("action") != action
        ):
            raise ValueError("node retirement approval target changed")

    def _finalize_node_retirement_approval(
        self,
        cursor: sqlite3.Cursor,
        *,
        approval_id: int,
        note: str,
        decision_actor_id: Optional[str],
        decision_actor_kind: Optional[str],
        decision_mechanism: Optional[str],
    ) -> None:
        """Decide a node-retirement approval before its transaction commits."""
        decided_at = self._sqlite_now(cursor)
        cursor.execute(
            """
            UPDATE approvals
            SET status = 'approved', decided_at = ?,
                decision_actor_id = ?, decision_mechanism = ?, note = ?
            WHERE id = ? AND kind = 'node_retire' AND status = 'pending'
            """,
            (
                decided_at,
                decision_actor_id,
                decision_mechanism,
                note,
                approval_id,
            ),
        )
        if cursor.rowcount != 1:
            raise ValueError("node retirement approval decision conflict")
        self._append_approval_decided_audit(
            cursor,
            approval_id=approval_id,
            kind="node_retire",
            status="approved",
            decision_actor_id=decision_actor_id,
            decision_actor_kind=decision_actor_kind,
            decision_mechanism=decision_mechanism,
        )

    def retire_node(
        self,
        node_id: str,
        *,
        approval_id: Optional[int] = None,
        finalize_approval: bool = False,
        decision_actor_id: Optional[str] = None,
        decision_actor_kind: Optional[str] = None,
        decision_mechanism: Optional[str] = None,
        approval_note: Optional[str] = None,
    ) -> Optional[Node]:
        """Complete a routine retirement after drain and active=0.

        The server binding and credential identifiers remain as historical
        evidence, but ``status=retired`` makes the credential unusable on every
        route.  Unlike emergency revoke this method must never create an
        unknown recovery hold because it is admissible only when ownership is
        already zero.
        """
        with self._immediate_cursor() as cur:
            cur.execute("SELECT * FROM nodes WHERE id = ?", (node_id,))
            row = cur.fetchone()
            if row is None:
                return None
            if finalize_approval:
                self._require_pending_node_retirement_approval(
                    cur,
                    approval_id=approval_id,
                    node_id=node_id,
                    server_name=str(row["server_name"]),
                    action="complete_retirement",
                )
            if row["status"] == "retired":
                return Node.from_row(row)
            if row["status"] != "enrolled" or row["revoked_at"] is not None:
                raise ValueError("revoked node cannot be routinely retired")
            if row["draining_at"] is None:
                raise ValueError("node must enter drain before retirement")

            current_time = self._sqlite_now(cur)
            cur.execute(
                """
                SELECT DISTINCT execution.id
                FROM node_attempts AS node_attempt
                JOIN execution_attempts AS execution
                  ON execution.id = node_attempt.execution_attempt_id
                WHERE node_attempt.node_id = ?
                  AND node_attempt.terminal_at IS NULL
                  AND execution.state IN ('leased', 'dispatching', 'running')
                ORDER BY execution.id
                """,
                (node_id,),
            )
            execution_attempt_ids = [str(item["id"]) for item in cur.fetchall()]
            cur.execute(
                """
                SELECT id
                FROM node_attempts
                WHERE node_id = ?
                  AND execution_attempt_id IS NULL
                  AND terminal_at IS NULL
                  AND (
                        (status = 'leased' AND lease_expires_at > ?)
                        OR status IN ('acked', 'running')
                      )
                ORDER BY id
                """,
                (node_id, current_time),
            )
            legacy_node_attempt_ids = [str(item["id"]) for item in cur.fetchall()]
            if execution_attempt_ids or legacy_node_attempt_ids:
                raise ValueError(
                    "node retirement blocked by active ownership: "
                    f"execution={execution_attempt_ids}, "
                    f"legacy_node={legacy_node_attempt_ids}"
                )

            retired_at = self._sqlite_now(cur)
            cur.execute(
                """
                UPDATE nodes
                SET status = 'retired', retired_at = ?,
                    previous_secret_hash = NULL,
                    previous_secret_expires_at = NULL,
                    pending_credential_id = NULL,
                    pending_secret_hash = NULL,
                    pending_activation_nonce_hash = NULL,
                    pending_expires_at = NULL,
                    pending_grace_sec = NULL,
                    pending_created_at = NULL,
                    pending_approval_id = NULL,
                    last_activation_credential_id = NULL,
                    last_activation_nonce_hash = NULL,
                    last_activation_expires_at = NULL
                WHERE id = ? AND status = 'enrolled'
                  AND revoked_at IS NULL AND draining_at IS NOT NULL
                """,
                (retired_at, node_id),
            )
            if cur.rowcount != 1:
                raise ValueError("node retirement conflict")
            self._append_node_audit_event(
                cur,
                action="node_retired",
                resource_id=node_id,
                params={"server": str(row["server_name"])},
                approval_id=approval_id,
                event_id=f"node:{node_id}:retired",
                occurred_at=retired_at,
            )
            if finalize_approval:
                self._finalize_node_retirement_approval(
                    cur,
                    approval_id=approval_id,
                    note=(
                        approval_note
                        or f"node {node_id} 已在 active=0 後完成例行退役"
                    ),
                    decision_actor_id=decision_actor_id,
                    decision_actor_kind=decision_actor_kind,
                    decision_mechanism=decision_mechanism,
                )
            cur.execute("SELECT * FROM nodes WHERE id = ?", (node_id,))
            return Node.from_row(cur.fetchone())

    def set_node_draining(
        self,
        node_id: str,
        *,
        draining: bool = True,
        approval_id: Optional[int] = None,
        finalize_approval: bool = False,
        decision_actor_id: Optional[str] = None,
        decision_actor_kind: Optional[str] = None,
        decision_mechanism: Optional[str] = None,
        approval_note: Optional[str] = None,
    ) -> Optional[Node]:
        """N-3: routine retirement. The node keeps its identity and finishes
        what it holds; it is simply offered nothing new. Reversible."""
        with self._immediate_cursor() as cur:
            cur.execute("SELECT * FROM nodes WHERE id = ?", (node_id,))
            existing = cur.fetchone()
            action = "start_drain" if draining else "resume_assignment"
            if finalize_approval and existing is not None:
                self._require_pending_node_retirement_approval(
                    cur,
                    approval_id=approval_id,
                    node_id=node_id,
                    server_name=str(existing["server_name"]),
                    action=action,
                )
            cur.execute(
                "UPDATE nodes SET draining_at = ?"
                " WHERE id = ? AND status = 'enrolled' AND revoked_at IS NULL",
                (self._sqlite_now(cur) if draining else None, node_id),
            )
            if (
                existing is not None
                and existing["status"] == "enrolled"
                and existing["revoked_at"] is None
                and bool(existing["draining_at"]) != bool(draining)
                and cur.rowcount == 1
            ):
                self._append_node_audit_event(
                    cur,
                    action="node_drained",
                    resource_id=node_id,
                    params={
                        "server": str(existing["server_name"]),
                        "draining": bool(draining),
                    },
                    approval_id=approval_id,
                    event_id=f"node:{node_id}:drain:{int(draining)}",
                )
            elif finalize_approval:
                raise ValueError("node retirement state conflict")
            if finalize_approval:
                self._finalize_node_retirement_approval(
                    cur,
                    approval_id=approval_id,
                    note=(
                        approval_note
                        or (
                            f"node {node_id} 已停止新派工並進入 drain"
                            if draining
                            else f"node {node_id} 已退出 drain，可重新接受派工"
                        )
                    ),
                    decision_actor_id=decision_actor_id,
                    decision_actor_kind=decision_actor_kind,
                    decision_mechanism=decision_mechanism,
                )
            cur.execute("SELECT * FROM nodes WHERE id = ?", (node_id,))
            row = cur.fetchone()
            return Node.from_row(row) if row else None

    def touch_node_heartbeat(
        self, node_id: str, *, agent_version: Optional[str] = None
    ) -> None:
        """更新 node 的最後心跳時間（INV-NODE-4：這只是觀測，不推斷任務
        狀態）。已撤銷的 node 不更新。"""
        with self.cursor() as cur:
            cur.execute(
                """
                UPDATE nodes SET last_heartbeat_at = ?,
                       agent_version = COALESCE(?, agent_version)
                WHERE id = ? AND status = 'enrolled' AND revoked_at IS NULL
                """,
                (now_iso(), agent_version, node_id),
            )

    def insert_node_attempt(
        self,
        *,
        attempt_id: str,
        job_id: int,
        node_id: str,
        command_sha256: str,
        lease_expires_at: str,
    ) -> NodeAttemptRow:
        """建立一筆 `leased` attempt。這一步必須在任何遠端副作用**之前**
        完成（DB-before-side-effect，INV-STATE-*／INV-NODE-2）。"""
        with self._immediate_cursor() as cur:
            created_at = self._sqlite_now(cur)
            cur.execute(
                """
                INSERT INTO node_attempts
                    (id, job_id, node_id, status, command_sha256,
                     lease_expires_at, created_at)
                VALUES (?, ?, ?, 'leased', ?, ?, ?)
                """,
                (
                    attempt_id,
                    job_id,
                    node_id,
                    command_sha256,
                    lease_expires_at,
                    created_at,
                ),
            )
            self._append_node_attempt_audit_event(
                cur,
                action="node_attempt_created",
                resource_id=attempt_id,
                params={
                    "job_id": int(job_id),
                    "node_id": node_id,
                    "lease_mode": "direct",
                },
                event_id=f"node-attempt:{attempt_id}:created",
                occurred_at=created_at,
            )
            cur.execute("SELECT * FROM node_attempts WHERE id = ?", (attempt_id,))
            return NodeAttemptRow.from_row(cur.fetchone())

    def lease_legacy_node_attempt(
        self,
        *,
        attempt_id: str,
        job_id: int,
        node_id: str,
        command_sha256: str,
        lease_expires_at: str,
        observed_at: str,
        expected_job_type: str,
        expected_require_tag: Optional[str],
    ) -> dict[str, Any]:
        """Atomically revalidate and create a legacy Node lease.

        This compatibility path predates generic ``execution_attempts``.  Its
        claim is nevertheless one ``BEGIN IMMEDIATE`` transaction: expiry,
        idempotent reuse, Job/Node eligibility and INSERT cannot interleave
        with another poller on a second SQLite connection.
        """
        with self._immediate_cursor() as cur:
            cur.execute("SELECT * FROM nodes WHERE id = ?", (node_id,))
            node = cur.fetchone()
            cur.execute("SELECT * FROM jobs WHERE id = ?", (job_id,))
            job = cur.fetchone()
            if (
                node is None
                or node["status"] != "enrolled"
                or node["revoked_at"] is not None
                or node["draining_at"] is not None
            ):
                return {"attempt": None, "reused": False, "reason": "node is not eligible"}
            if (
                job is None
                or job["type"] != expected_job_type
                or job["require_tag"] != expected_require_tag
                or utf8_sha256(job["command"]) != command_sha256
                or (job["pin_server"] is not None and job["pin_server"] != node["server_name"])
            ):
                return {"attempt": None, "reused": False, "reason": "job eligibility changed"}

            # Only an unacknowledged expired lease is safe to release.  This
            # transition is a persisted fact, and also removes the row from
            # the active unique indexes before a new claim is attempted.
            cur.execute(
                """
                UPDATE node_attempts
                SET status = 'expired', terminal_at = ?
                WHERE execution_attempt_id IS NULL
                  AND status = 'leased' AND acked_at IS NULL
                  AND julianday(lease_expires_at) <= julianday(?)
                  AND (job_id = ? OR node_id = ?)
                """,
                (observed_at, observed_at, job_id, node_id),
            )

            cur.execute(
                """
                SELECT * FROM node_attempts
                WHERE job_id = ? AND node_id = ?
                  AND status IN ('leased', 'acked', 'running')
                ORDER BY created_at, id LIMIT 1
                """,
                (job_id, node_id),
            )
            existing = cur.fetchone()
            if existing is not None:
                return {
                    "attempt": NodeAttemptRow.from_row(existing),
                    "reused": True,
                    "reason": "existing lease",
                }
            if job["status"] != "queued":
                return {
                    "attempt": None,
                    "reused": False,
                    "reason": "job eligibility changed",
                }
            cur.execute(
                """
                SELECT 1 FROM node_attempts
                WHERE status IN ('leased', 'acked', 'running')
                  AND (job_id = ? OR node_id = ?)
                LIMIT 1
                """,
                (job_id, node_id),
            )
            if cur.fetchone() is not None:
                return {
                    "attempt": None,
                    "reused": False,
                    "reason": "job or node already leased or in flight",
                }

            cur.execute(
                """
                INSERT INTO node_attempts
                    (id, job_id, node_id, status, command_sha256,
                     lease_expires_at, created_at)
                VALUES (?, ?, ?, 'leased', ?, ?, ?)
                """,
                (
                    attempt_id,
                    job_id,
                    node_id,
                    command_sha256,
                    lease_expires_at,
                    observed_at,
                ),
            )
            self._append_node_attempt_audit_event(
                cur,
                action="node_attempt_created",
                resource_id=attempt_id,
                params={
                    "job_id": int(job_id),
                    "node_id": node_id,
                    "lease_mode": "poll",
                },
                event_id=f"node-attempt:{attempt_id}:created",
            )
            cur.execute("SELECT * FROM node_attempts WHERE id = ?", (attempt_id,))
            return {
                "attempt": NodeAttemptRow.from_row(cur.fetchone()),
                "reused": False,
                "reason": "",
            }

    def get_node_attempt(self, attempt_id: str) -> Optional[NodeAttemptRow]:
        with self.cursor() as cur:
            cur.execute("SELECT * FROM node_attempts WHERE id = ?", (attempt_id,))
            row = cur.fetchone()
            return NodeAttemptRow.from_row(row) if row else None

    def list_node_attempts(
        self,
        *,
        job_id: Optional[int] = None,
        node_id: Optional[str] = None,
        status: Optional[str] = None,
    ) -> list[NodeAttemptRow]:
        clauses, params = [], []
        if job_id is not None:
            clauses.append("job_id = ?")
            params.append(job_id)
        if node_id is not None:
            clauses.append("node_id = ?")
            params.append(node_id)
        if status is not None:
            clauses.append("status = ?")
            params.append(status)
        where = f"WHERE {' AND '.join(clauses)}" if clauses else ""
        with self.cursor() as cur:
            cur.execute(
                f"SELECT * FROM node_attempts {where} ORDER BY created_at ASC, id ASC",
                tuple(params),
            )
            return [NodeAttemptRow.from_row(row) for row in cur.fetchall()]

    def has_active_node_ownership(self) -> bool:
        """Return whether any node protocol attempt still needs its channel.

        A rollout rollback may stop new assignment, but it cannot close the
        existing-attempt protocol while a lease/ack/running row is active.
        This read is used during startup before any node route or background
        task is created, so an unsafe configuration fails closed.
        """
        with self.cursor() as cur:
            cur.execute(
                """
                SELECT 1
                FROM node_attempts
                WHERE terminal_at IS NULL
                  AND status IN ('leased', 'acked', 'running')
                LIMIT 1
                """
            )
            return cur.fetchone() is not None

    def ack_node_attempt(self, attempt_id: str, node_id: str) -> bool:
        """原子性 acknowledge（INV-NODE-2）。

        `WHERE ... AND acked_at IS NULL AND node_id = ?` 讓「第一個 ack 才
        寫入」由 SQLite 保證——兩個並行請求只有一個會影響到列，另一個
        rowcount=0 並被呼叫端當成重複 ack（冪等回成功，不重複執行）。
        回傳 True 表示這一次確實是「第一次」ack。
        """
        with self.cursor() as cur:
            cur.execute(
                """
                UPDATE node_attempts
                SET status = 'acked', acked_at = ?, last_heartbeat_at = ?
                WHERE id = ? AND node_id = ? AND acked_at IS NULL
                      AND status = 'leased'
                """,
                (now_iso(), now_iso(), attempt_id, node_id),
            )
            return cur.rowcount == 1

    def upsert_node_attempt_artifact(
        self,
        *,
        attempt_id: str,
        relative_path: str,
        size_bytes: int,
        sha256: str,
        kind: str = "file",
    ) -> None:
        """Insert-or-verify one immutable artifact metadata record.

        A retry with the exact same size/digest is idempotent.  A later report
        that changes either value is rejected rather than overwriting evidence
        of what the agent originally reported.
        """
        with self._immediate_cursor() as cur:
            cur.execute(
                "SELECT node_id, execution_attempt_id FROM node_attempts WHERE id = ?",
                (attempt_id,),
            )
            attempt = cur.fetchone()
            if attempt is None:
                raise ValueError("attempt not found")
            cur.execute(
                """
                INSERT INTO node_attempt_artifacts
                    (attempt_id, relative_path, kind, size_bytes, sha256, reported_at)
                VALUES (?, ?, ?, ?, ?, ?)
                ON CONFLICT(attempt_id, relative_path) DO NOTHING
                """,
                (attempt_id, relative_path, kind, size_bytes, sha256, now_iso()),
            )
            row = cur.execute(
                "SELECT kind, size_bytes, sha256 FROM node_attempt_artifacts "
                "WHERE attempt_id = ? AND relative_path = ?",
                (attempt_id, relative_path),
            ).fetchone()
            if row is None or (
                row["kind"] != kind
                or int(row["size_bytes"]) != size_bytes
                or row["sha256"] != sha256
            ):
                raise ValueError("artifact metadata conflict")
            self._append_node_artifact_audit_event(
                cur,
                attempt_id=attempt_id,
                node_id=str(attempt["node_id"]),
                execution_attempt_id=attempt["execution_attempt_id"],
                artifacts=[(relative_path, size_bytes, sha256, kind)],
            )

    def upsert_node_attempt_artifacts_batch(
        self,
        *,
        attempt_id: str,
        node_id: str,
        artifacts: list[tuple[str, int, str] | tuple[str, int, str, str]],
    ) -> int:
        """Insert-or-verify one validated immutable artifact report."""
        with self._immediate_cursor() as cur:
            cur.execute(
                "SELECT node_id, acked_at, execution_attempt_id"
                " FROM node_attempts WHERE id = ?",
                (attempt_id,),
            )
            attempt = cur.fetchone()
            if attempt is None:
                raise ValueError("attempt not found")
            if attempt["node_id"] != node_id:
                raise ValueError("attempt belongs to another node")
            if attempt["acked_at"] is None:
                raise ValueError("attempt was never acknowledged")
            reported_at = self._sqlite_now(cur)
            normalized_artifacts: list[tuple[str, int, str, str]] = []
            for artifact in artifacts:
                if len(artifact) == 3:
                    relative_path, size_bytes, sha256 = artifact
                    kind = "file"
                elif len(artifact) == 4:
                    relative_path, size_bytes, sha256, kind = artifact
                else:  # pragma: no cover - callers validate before the DB seam
                    raise ValueError("invalid artifact metadata tuple")
                normalized_artifacts.append(
                    (relative_path, int(size_bytes), sha256, kind)
                )
                cur.execute(
                    """
                    INSERT INTO node_attempt_artifacts
                        (attempt_id, relative_path, kind, size_bytes, sha256, reported_at)
                    VALUES (?, ?, ?, ?, ?, ?)
                    ON CONFLICT(attempt_id, relative_path) DO NOTHING
                    """,
                    (attempt_id, relative_path, kind, size_bytes, sha256, reported_at),
                )
                row = cur.execute(
                    "SELECT kind, size_bytes, sha256 FROM node_attempt_artifacts "
                    "WHERE attempt_id = ? AND relative_path = ?",
                    (attempt_id, relative_path),
                ).fetchone()
                if row is None or (
                    row["kind"] != kind
                    or int(row["size_bytes"]) != size_bytes
                    or row["sha256"] != sha256
                ):
                    raise ValueError("artifact metadata conflict")
            self._append_node_artifact_audit_event(
                cur,
                attempt_id=attempt_id,
                node_id=node_id,
                execution_attempt_id=attempt["execution_attempt_id"],
                artifacts=normalized_artifacts,
            )
            return len(artifacts)

    def record_legacy_node_terminal(
        self,
        *,
        attempt_id: str,
        node_id: str,
        exit_code: int,
        log_tail: str,
    ) -> dict[str, Any]:
        """Atomically converge an unlinked Node attempt and canonical Job."""
        terminal_status = "done" if exit_code == 0 else "failed"
        with self._immediate_cursor() as cur:
            cur.execute(
                """
                SELECT attempt.*, job.status AS job_status,
                       job.exit_code AS job_exit_code,
                       job.log_tail AS job_log_tail
                FROM node_attempts AS attempt
                JOIN jobs AS job ON job.id = attempt.job_id
                WHERE attempt.id = ?
                """,
                (attempt_id,),
            )
            row = cur.fetchone()
            if row is None:
                raise ValueError("attempt not found")
            if row["node_id"] != node_id:
                raise ValueError("attempt belongs to another node")
            if row["execution_attempt_id"] is not None:
                raise ValueError("linked attempt requires v2 terminal transaction")

            if row["terminal_at"] is not None:
                if not (
                    row["status"] == terminal_status
                    and row["exit_code"] == exit_code
                    and (row["log_tail"] or "") == (log_tail or "")
                ):
                    raise ValueError("terminal conflicts with recorded result")
                job_transitioned = False
                if row["job_status"] in {"queued", "running"}:
                    cur.execute(
                        """
                        UPDATE jobs
                        SET status = ?, finished_at = ?, exit_code = ?, log_tail = ?
                        WHERE id = ? AND status IN ('queued', 'running')
                        """,
                        (
                            terminal_status,
                            row["terminal_at"],
                            row["exit_code"],
                            row["log_tail"],
                            row["job_id"],
                        ),
                    )
                    job_transitioned = cur.rowcount == 1
                elif not (
                    row["job_status"] == terminal_status
                    and row["job_exit_code"] == row["exit_code"]
                    and (row["job_log_tail"] or "") == (row["log_tail"] or "")
                ):
                    raise ValueError("job terminal conflicts with recorded attempt")
                return {
                    "accepted": True,
                    "duplicate": True,
                    "job_id": int(row["job_id"]),
                    "job_transitioned": job_transitioned,
                }

            if row["acked_at"] is None:
                raise ValueError("attempt was never acknowledged")
            if row["status"] not in {"acked", "running"}:
                raise ValueError("attempt is not terminal-eligible")
            if row["job_status"] not in {"queued", "running"}:
                raise ValueError("job is not terminal-eligible")

            terminal_at = self._sqlite_now(cur)
            cur.execute(
                """
                UPDATE node_attempts
                SET status = ?, terminal_at = ?, exit_code = ?, log_tail = ?,
                    last_heartbeat_at = ?
                WHERE id = ? AND node_id = ? AND terminal_at IS NULL
                  AND acked_at IS NOT NULL
                """,
                (
                    terminal_status,
                    terminal_at,
                    exit_code,
                    log_tail,
                    terminal_at,
                    attempt_id,
                    node_id,
                ),
            )
            if cur.rowcount != 1:
                raise ValueError("claim_conflict")
            cur.execute(
                """
                UPDATE jobs
                SET status = ?, finished_at = ?, exit_code = ?, log_tail = ?
                WHERE id = ? AND status IN ('queued', 'running')
                """,
                (terminal_status, terminal_at, exit_code, log_tail, row["job_id"]),
            )
            if cur.rowcount != 1:
                raise ValueError("claim_conflict")
            self.append_durable_audit_event_in_transaction(
                cur,
                action="execution_terminal_recorded",
                params={
                    "node_id": node_id,
                    "job_id": int(row["job_id"]),
                    "exit_code": int(exit_code),
                    "terminal_state": terminal_status,
                },
                result=terminal_status,
                resource_type="node_attempt",
                resource_id=attempt_id,
                event_id=f"node-attempt:{attempt_id}:terminal",
            )
            return {
                "accepted": True,
                "duplicate": False,
                "job_id": int(row["job_id"]),
                "job_transitioned": True,
            }

    def list_node_attempt_artifacts(self, attempt_id: str) -> list[dict]:
        """某個 attempt 已回報的 artifact 中繼資料（路徑排序，確定性）。"""
        with self.cursor() as cur:
            cur.execute(
                """
                SELECT relative_path, kind, size_bytes, sha256, reported_at
                FROM node_attempt_artifacts WHERE attempt_id = ?
                ORDER BY relative_path ASC
                """,
                (attempt_id,),
            )
            return [dict(row) for row in cur.fetchall()]

    def upsert_execution_attempt_artifacts_batch(
        self,
        *,
        attempt_id: str,
        artifacts: list[tuple[str, int, str] | tuple[str, int, str, str]],
    ) -> int:
        """Insert-or-verify immutable SSH artifact metadata as one batch.

        The caller may only pass canonical checkout-relative metadata.  All
        validation happens before the transaction starts, so a malformed or
        conflicting report cannot leave a partial batch behind.
        """
        if len(artifacts) > MAX_ARTIFACTS_PER_REPORT:
            raise ValueError("artifact report exceeds maximum item count")
        normalized: list[tuple[str, str, int, str]] = []
        seen: set[str] = set()
        for artifact in artifacts:
            if len(artifact) == 3:
                relative_path, size_bytes, sha256 = artifact
                kind = "file"
            elif len(artifact) == 4:
                relative_path, size_bytes, sha256, kind = artifact
            else:
                raise ValueError("invalid artifact metadata tuple")
            relative_path = validate_artifact_path(relative_path)
            if any(ord(character) < 0x20 or ord(character) == 0x7F for character in relative_path):
                raise ValueError("artifact path contains a control character")
            if relative_path in seen:
                raise ValueError("duplicate artifact metadata path")
            seen.add(relative_path)
            kind = validate_artifact_kind(kind)
            if kind != "file":
                raise ValueError("execution artifact metadata requires regular files")
            normalized.append(
                (
                    relative_path,
                    kind,
                    validate_artifact_size(size_bytes),
                    validate_artifact_digest(sha256),
                )
            )
        with self._immediate_cursor() as cur:
            attempt = cur.execute(
                "SELECT backend, execution_approval_id FROM execution_attempts WHERE id = ?", (attempt_id,)
            ).fetchone()
            if attempt is None:
                raise ValueError("execution attempt not found")
            if attempt["backend"] != "ssh":
                raise ValueError("execution artifact metadata requires ssh attempt")
            reported_at = self._sqlite_now(cur)
            for relative_path, kind, size_bytes, sha256 in normalized:
                cur.execute(
                    """
                    INSERT INTO execution_attempt_artifacts
                        (attempt_id, relative_path, kind, size_bytes, sha256, reported_at)
                    VALUES (?, ?, ?, ?, ?, ?)
                    ON CONFLICT(attempt_id, relative_path) DO NOTHING
                    """,
                    (attempt_id, relative_path, kind, size_bytes, sha256, reported_at),
                )
                row = cur.execute(
                    """
                    SELECT kind, size_bytes, sha256
                    FROM execution_attempt_artifacts
                    WHERE attempt_id = ? AND relative_path = ?
                    """,
                    (attempt_id, relative_path),
                ).fetchone()
                if row is None or (
                    row["kind"] != kind
                    or int(row["size_bytes"]) != size_bytes
                    or row["sha256"] != sha256
                ):
                    raise ValueError("artifact metadata conflict")
            self._append_execution_attempt_artifact_audit_event(
                cur,
                attempt_id=attempt_id,
                approval_id=int(attempt["execution_approval_id"]),
                artifacts=normalized,
            )
            return len(normalized)

    def list_execution_attempt_artifacts(self, attempt_id: str) -> list[dict]:
        """Read immutable generic attempt metadata in deterministic order."""
        with self.cursor() as cur:
            rows = cur.execute(
                """
                SELECT relative_path, kind, size_bytes, sha256, reported_at
                FROM execution_attempt_artifacts
                WHERE attempt_id = ?
                ORDER BY relative_path ASC
                """,
                (attempt_id,),
            ).fetchall()
            return [dict(row) for row in rows]

    def request_node_attempt_stop(self, attempt_id: str) -> bool:
        """記下一個已核准的停止請求（Goal 3 C3，roadmap Phase 3 stop-request）。

        只對**尚未終態**的 attempt 生效；已經停過的重複請求是 no-op（冪等）。
        回傳 True 表示這一次確實寫入了新的請求。

        這裡刻意**不改** attempt status——control plane 沒有入站通道可以真的
        殺掉遠端行程,只能留下請求等 agent 取回。狀態仍以 agent 回報的終態
        為準（INV-NODE-4：不得因為「我請求停止了」就推斷它停了）。
        """
        requested_at = now_iso()
        with self._immediate_cursor() as cur:
            cur.execute(
                "SELECT execution_attempt_id, node_id, job_id"
                " FROM node_attempts WHERE id = ?",
                (attempt_id,),
            )
            row = cur.fetchone()
            if row is None:
                return False
            cur.execute(
                """
                UPDATE node_attempts SET stop_requested_at = ?
                WHERE id = ? AND stop_requested_at IS NULL AND terminal_at IS NULL
                """,
                (requested_at, attempt_id),
            )
            requested = cur.rowcount == 1
            if requested and row["execution_attempt_id"] is not None:
                cur.execute(
                    """
                    UPDATE execution_attempts
                    SET stop_requested_at = ?
                    WHERE id = ? AND stop_requested_at IS NULL
                      AND state IN ('leased', 'dispatching', 'running')
                    """,
                    (requested_at, row["execution_attempt_id"]),
                )
                if cur.rowcount != 1:
                    raise ValueError("claim_conflict")
                self._append_execution_event(
                    cur,
                    attempt_id=row["execution_attempt_id"],
                    event_type="stop_requested",
                    reason_code="contract_validated",
                    evidence={"node_attempt_id": attempt_id},
                    created_at=requested_at,
                )
            if requested:
                resource_type = (
                    "execution_attempt"
                    if row["execution_attempt_id"] is not None
                    else "node_attempt"
                )
                resource_id = row["execution_attempt_id"] or attempt_id
                self.append_durable_audit_event_in_transaction(
                    cur,
                    action="execution_stop_requested",
                    params={
                        "job_id": int(row["job_id"]),
                        "node_id": str(row["node_id"]),
                        "stop_channel": "node",
                    },
                    result="requested",
                    resource_type=resource_type,
                    resource_id=str(resource_id),
                    event_id=f"{resource_type}:{resource_id}:stop-requested",
                )
            return requested

    def ack_node_attempt_stop(self, attempt_id: str, node_id: str) -> bool:
        """agent 確認收到停止請求。只有該 attempt 的擁有者能 ack。"""
        acknowledged_at = now_iso()
        with self._immediate_cursor() as cur:
            cur.execute(
                "SELECT execution_attempt_id, node_id, job_id"
                " FROM node_attempts WHERE id = ?",
                (attempt_id,),
            )
            row = cur.fetchone()
            if row is None:
                return False
            cur.execute(
                """
                UPDATE node_attempts SET stop_acked_at = ?
                WHERE id = ? AND node_id = ? AND stop_requested_at IS NOT NULL
                      AND stop_acked_at IS NULL
                """,
                (acknowledged_at, attempt_id, node_id),
            )
            acknowledged = cur.rowcount == 1
            if acknowledged and row["execution_attempt_id"] is not None:
                cur.execute(
                    """
                    UPDATE execution_attempts
                    SET stop_acknowledged_at = ?, last_observed_at = ?
                    WHERE id = ? AND stop_requested_at IS NOT NULL
                      AND stop_acknowledged_at IS NULL
                      AND state IN ('leased', 'dispatching', 'running')
                    """,
                    (
                        acknowledged_at,
                        acknowledged_at,
                        row["execution_attempt_id"],
                    ),
                )
                if cur.rowcount != 1:
                    raise ValueError("claim_conflict")
                self._append_execution_event(
                    cur,
                    attempt_id=row["execution_attempt_id"],
                    event_type="stop_acknowledged",
                    reason_code="remote_state_observed",
                    evidence={
                        "node_attempt_id": attempt_id,
                        "node_id": node_id,
                    },
                    created_at=acknowledged_at,
                )
            if acknowledged:
                resource_type = (
                    "execution_attempt"
                    if row["execution_attempt_id"] is not None
                    else "node_attempt"
                )
                resource_id = row["execution_attempt_id"] or attempt_id
                self.append_durable_audit_event_in_transaction(
                    cur,
                    action="execution_stop_acknowledged",
                    params={
                        "job_id": int(row["job_id"]),
                        "node_id": str(row["node_id"]),
                        "stop_channel": "node",
                    },
                    result="acknowledged",
                    resource_type=resource_type,
                    resource_id=str(resource_id),
                    event_id=f"{resource_type}:{resource_id}:stop-acknowledged",
                )
            return acknowledged

    def update_node_attempt(
        self,
        attempt_id: str,
        *,
        status: Optional[str] = None,
        last_heartbeat_at: Optional[str] = None,
        terminal_at: Optional[str] = None,
        exit_code: Optional[int] = None,
        log_tail: Optional[str] = None,
    ) -> Optional[NodeAttemptRow]:
        sets, params = [], []
        for column, value in (
            ("status", status),
            ("last_heartbeat_at", last_heartbeat_at),
            ("terminal_at", terminal_at),
            ("exit_code", exit_code),
            ("log_tail", log_tail),
        ):
            if value is not None:
                sets.append(f"{column} = ?")
                params.append(value)
        if not sets:
            return self.get_node_attempt(attempt_id)
        params.append(attempt_id)
        with self.cursor() as cur:
            cur.execute(
                f"UPDATE node_attempts SET {', '.join(sets)} WHERE id = ?",
                tuple(params),
            )
            cur.execute("SELECT * FROM node_attempts WHERE id = ?", (attempt_id,))
            row = cur.fetchone()
            return NodeAttemptRow.from_row(row) if row else None

    # ---- server_bootstrap_reports（Goal 3 Phase B）----------------------

    def begin_server_bootstrap_intent(
        self,
        *,
        approval_id: int,
        host: str,
        username: str,
        port: int,
        script_sha256: str,
        audit_actor: AuditActor | None = None,
    ) -> dict[str, Any]:
        """Claim a bootstrap approval before uploading or executing its script."""

        event_id = f"server-bootstrap:{approval_id}:intent"
        with self._immediate_cursor() as cur:
            approval = cur.execute(
                "SELECT kind, status, payload, materialization_started_at "
                "FROM approvals WHERE id = ?",
                (approval_id,),
            ).fetchone()
            if approval is None or approval["kind"] != "server_bootstrap":
                raise ValueError("server_bootstrap approval is missing or mismatched")
            if approval["status"] != "pending":
                raise ValueError("server_bootstrap approval is no longer pending")
            try:
                payload = json.loads(approval["payload"] or "{}")
            except (TypeError, json.JSONDecodeError):
                raise ValueError("server_bootstrap approval payload is malformed") from None
            if not isinstance(payload, dict):
                raise ValueError("server_bootstrap approval payload is malformed")
            if (
                payload.get("host") != host
                or payload.get("username") != username
                or payload.get("port") != port
                or payload.get("script_sha256") != script_sha256
            ):
                raise ValueError("server_bootstrap approval payload conflict")
            params = {
                "approval_id": approval_id,
                "host": host,
                "username": username,
                "port": port,
                "payload_sha256": canonical_json_sha256(payload),
                "script_sha256": script_sha256,
            }
            existing = cur.execute(
                "SELECT action, result, params_json, approval_id, resource_id "
                "FROM audit_events WHERE event_id = ?",
                (event_id,),
            ).fetchone()
            if existing is not None:
                if (
                    existing["action"] != "server_bootstrap_intent"
                    or existing["result"] != "intent"
                    or existing["approval_id"] != approval_id
                    or existing["resource_id"] != str(approval_id)
                    or json.loads(existing["params_json"] or "{}") != params
                ):
                    raise ValueError("server_bootstrap intent payload conflict")
            elif approval["materialization_started_at"] is not None:
                raise ValueError("server_bootstrap intent claim is incomplete")
            if approval["materialization_started_at"] is None:
                cur.execute(
                    "UPDATE approvals SET materialization_started_at = ? "
                    "WHERE id = ? AND status = 'pending' "
                    "AND materialization_started_at IS NULL",
                    (now_iso(), approval_id),
                )
                if cur.rowcount != 1:
                    raise ValueError("server_bootstrap intent claim conflicted")
            self.append_durable_audit_event_in_transaction(
                cur,
                action="server_bootstrap_intent",
                params=params,
                result="intent",
                resource_type="server_bootstrap",
                resource_id=str(approval_id),
                approval_id=approval_id,
                event_id=event_id,
                **self._dataset_audit_actor_kwargs(audit_actor),
            )
            return params

    def record_server_bootstrap_unknown(
        self,
        *,
        approval_id: int,
        host: str,
        username: str,
        port: int,
        audit_actor: AuditActor | None = None,
    ) -> None:
        """Record an uncertain remote bootstrap result and keep approval pending."""

        with self._immediate_cursor() as cur:
            approval = cur.execute(
                "SELECT kind, status, payload FROM approvals WHERE id = ?",
                (approval_id,),
            ).fetchone()
            if approval is None or approval["kind"] != "server_bootstrap":
                raise ValueError("server_bootstrap approval is missing or mismatched")
            if approval["status"] != "pending":
                return
            try:
                payload = json.loads(approval["payload"] or "{}")
            except (TypeError, json.JSONDecodeError):
                raise ValueError("server_bootstrap approval payload is malformed") from None
            intent = cur.execute(
                "SELECT action, result, params_json, approval_id, resource_id "
                "FROM audit_events WHERE event_id = ?",
                (f"server-bootstrap:{approval_id}:intent",),
            ).fetchone()
            if intent is None:
                raise ValueError("server_bootstrap intent is missing")
            intent_params = json.loads(intent["params_json"] or "{}")
            if (
                intent["action"] != "server_bootstrap_intent"
                or intent["result"] != "intent"
                or intent["approval_id"] != approval_id
                or intent["resource_id"] != str(approval_id)
                or intent_params.get("host") != host
                or intent_params.get("username") != username
                or intent_params.get("port") != port
                or intent_params.get("payload_sha256") != canonical_json_sha256(payload)
            ):
                raise ValueError("server_bootstrap intent payload conflict")
            self.append_durable_audit_event_in_transaction(
                cur,
                action="server_bootstrap_outcome",
                params={
                    "approval_id": approval_id,
                    "host": host,
                    "username": username,
                    "port": port,
                    "payload_sha256": intent_params["payload_sha256"],
                    "error_category": "remote_outcome_unknown",
                },
                result="unknown",
                resource_type="server_bootstrap",
                resource_id=str(approval_id),
                approval_id=approval_id,
                event_id=f"server-bootstrap:{approval_id}:outcome:unknown",
                **self._dataset_audit_actor_kwargs(audit_actor),
            )
            cur.execute(
                "UPDATE approvals SET note = ? WHERE id = ? AND status = 'pending'",
                ("server_bootstrap 遠端結果未知，禁止自動重跑，需人工確認", approval_id),
            )

    def finalize_server_bootstrap_decision(
        self,
        *,
        approval_id: int,
        host: str,
        username: str,
        port: int,
        components: list[str],
        script_version: str,
        script_sha256: str,
        passed: bool,
        report: dict[str, Any],
        note: Optional[str],
        decision_actor_id: Optional[str] = None,
        decision_actor_kind: Optional[str] = None,
        decision_mechanism: Optional[str] = None,
        audit_actor: AuditActor | None = None,
    ) -> dict[str, Any]:
        """Commit bootstrap report, bounded outcome, and approval decision."""

        with self._immediate_cursor() as cur:
            approval = cur.execute(
                "SELECT kind, status, payload FROM approvals WHERE id = ?",
                (approval_id,),
            ).fetchone()
            if (
                approval is None
                or approval["kind"] != "server_bootstrap"
                or approval["status"] != "pending"
            ):
                raise ValueError("server_bootstrap approval is not pending")
            try:
                payload = json.loads(approval["payload"] or "{}")
            except (TypeError, json.JSONDecodeError):
                raise ValueError("server_bootstrap approval payload is malformed") from None
            payload_sha256 = canonical_json_sha256(payload)
            intent = cur.execute(
                "SELECT action, result, params_json, approval_id, resource_id "
                "FROM audit_events WHERE event_id = ?",
                (f"server-bootstrap:{approval_id}:intent",),
            ).fetchone()
            if intent is None:
                raise ValueError("server_bootstrap intent is missing")
            intent_params = json.loads(intent["params_json"] or "{}")
            if (
                intent["action"] != "server_bootstrap_intent"
                or intent["result"] != "intent"
                or intent["approval_id"] != approval_id
                or intent["resource_id"] != str(approval_id)
                or intent_params.get("host") != host
                or intent_params.get("username") != username
                or intent_params.get("port") != port
                or intent_params.get("payload_sha256") != payload_sha256
                or intent_params.get("script_sha256") != script_sha256
            ):
                raise ValueError("server_bootstrap intent payload conflict")

            cur.execute(
                """
                INSERT INTO server_bootstrap_reports
                    (host, username, port, components, script_version,
                     script_sha256, passed, report, approval_id, created_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    host,
                    username,
                    port,
                    json.dumps(components, ensure_ascii=False),
                    script_version,
                    script_sha256,
                    1 if passed else 0,
                    json.dumps(report, ensure_ascii=False),
                    approval_id,
                    now_iso(),
                ),
            )
            report_id = int(cur.lastrowid)
            self.append_durable_audit_event_in_transaction(
                cur,
                action="server_bootstrap_outcome",
                params={
                    "approval_id": approval_id,
                    "host": host,
                    "username": username,
                    "port": port,
                    "payload_sha256": payload_sha256,
                    "report_id": report_id,
                    "passed": passed,
                },
                result="applied",
                resource_type="server_bootstrap",
                resource_id=str(approval_id),
                approval_id=approval_id,
                event_id=f"server-bootstrap:{approval_id}:outcome:applied",
                **self._dataset_audit_actor_kwargs(audit_actor),
            )
            status = "approved"
            cur.execute(
                "UPDATE approvals SET status = ?, decided_at = ?, note = ?, "
                "decision_actor_id = ?, decision_mechanism = ? "
                "WHERE id = ? AND status = 'pending'",
                (
                    status,
                    now_iso(),
                    note,
                    decision_actor_id,
                    decision_mechanism,
                    approval_id,
                ),
            )
            if cur.rowcount != 1:
                raise ValueError("server_bootstrap approval decision lost its pending CAS")
            self._append_approval_decided_audit(
                cur,
                approval_id=approval_id,
                kind="server_bootstrap",
                status=status,
                decision_actor_id=decision_actor_id,
                decision_actor_kind=decision_actor_kind,
                decision_mechanism=decision_mechanism,
            )
            return {"status": status, "report_id": report_id, "passed": passed}

    def insert_server_bootstrap_report(
        self,
        *,
        host: str,
        username: str,
        port: int,
        components: list[str],
        script_version: str,
        script_sha256: str,
        passed: bool,
        report: dict,
        approval_id: Optional[int] = None,
    ) -> ServerBootstrapReport:
        """插入一筆 bootstrap 結果報告。`created_at` 一律用伺服器現在時間
        （同 `insert_server_observation()` 慣例）。"""
        with self.cursor() as cur:
            cur.execute(
                """
                INSERT INTO server_bootstrap_reports
                    (host, username, port, components, script_version,
                     script_sha256, passed, report, approval_id, created_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    host,
                    username,
                    port,
                    json.dumps(components, ensure_ascii=False),
                    script_version,
                    script_sha256,
                    1 if passed else 0,
                    json.dumps(report, ensure_ascii=False),
                    approval_id,
                    now_iso(),
                ),
            )
            report_id = int(cur.lastrowid)
            cur.execute(
                "SELECT * FROM server_bootstrap_reports WHERE id = ?", (report_id,)
            )
            return ServerBootstrapReport.from_row(cur.fetchone())

    def list_server_bootstrap_reports(
        self,
        *,
        host: Optional[str] = None,
        limit: int = 50,
    ) -> list[ServerBootstrapReport]:
        """報告列表（最新在前），可選 host 過濾。`limit` 由 API 層夾限。"""
        with self.cursor() as cur:
            if host is None:
                cur.execute(
                    """
                    SELECT * FROM server_bootstrap_reports
                    ORDER BY created_at DESC, id DESC LIMIT ?
                    """,
                    (limit,),
                )
            else:
                cur.execute(
                    """
                    SELECT * FROM server_bootstrap_reports
                    WHERE host = ?
                    ORDER BY created_at DESC, id DESC LIMIT ?
                    """,
                    (host, limit),
                )
            return [ServerBootstrapReport.from_row(row) for row in cur.fetchall()]

    def latest_server_bootstrap_report(
        self, *, host: str, username: str, port: int
    ) -> Optional[ServerBootstrapReport]:
        """同一目標 (host, username, port) 的最新報告；沒有 → None。
        `server_add` 閘只看最新一筆——舊的失敗報告被之後成功的一筆覆蓋。"""
        with self.cursor() as cur:
            cur.execute(
                """
                SELECT * FROM server_bootstrap_reports
                WHERE host = ? AND username = ? AND port = ?
                ORDER BY created_at DESC, id DESC LIMIT 1
                """,
                (host, username, port),
            )
            row = cur.fetchone()
            return ServerBootstrapReport.from_row(row) if row else None

    # ---- engineering_tasks CRUD（AI Engineering Task backend v1）-------

    _ENGINEERING_TASK_UPDATE_FIELDS = {"coding_run_id", "status", "updated_at"}

    @classmethod
    def _insert_engineering_task_event_cur(
        cls,
        cur: sqlite3.Cursor,
        *,
        task_id: str,
        event_type: str,
        summary: str,
        attempt_number: Optional[int] = None,
        phase: Optional[str] = None,
        state: Optional[str] = None,
        details: Optional[dict] = None,
        source_kind: str,
        source_id: Optional[str] = None,
        actor_id: Optional[str] = None,
        event_key: str,
        occurred_at: Optional[str] = None,
        recorded_at: Optional[str] = None,
    ) -> bool:
        safe_details = cls._validate_engineering_event_details(details)
        encoded_details = json.dumps(
            safe_details, sort_keys=True, separators=(",", ":")
        )
        cur.execute(
            """
            INSERT OR IGNORE INTO engineering_task_events
                (event_key, engineering_task_id, attempt_number, event_type, phase, state,
                 summary, details, source_kind, source_id, actor_id,
                 occurred_at, recorded_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                event_key,
                task_id,
                attempt_number,
                event_type,
                phase,
                state,
                summary,
                encoded_details,
                source_kind,
                source_id,
                actor_id,
                occurred_at,
                recorded_at or now_iso(),
            ),
        )
        inserted = cur.rowcount == 1
        if not inserted:
            cur.execute(
                """
                SELECT attempt_number, event_type, phase, state, summary, details,
                       source_kind, source_id, actor_id, occurred_at
                FROM engineering_task_events
                WHERE engineering_task_id = ? AND event_key = ?
                """,
                (task_id, event_key),
            )
            existing = cur.fetchone()
            expected = (
                attempt_number,
                event_type,
                phase,
                state,
                summary,
                encoded_details,
                source_kind,
                source_id,
                actor_id,
                occurred_at,
            )
            actual = tuple(existing) if existing is not None else None
            if actual != expected:
                raise ValueError("engineering task event idempotency conflict")
        return inserted

    def insert_engineering_task_request(
        self,
        *,
        project_id: str,
        project_name: str,
        project_version_id: str,
        base_commit: str,
        agent_provider_id: str,
        provider_capabilities: dict,
        execution_contract: dict,
        contract_version: str,
        structured_request: dict,
        instruction: str,
        detected_metadata: dict,
        runner_server: str,
        validation_target: Optional[str],
        approval_payload: dict,
        requester_actor_id: Optional[str] = None,
        task_id: Optional[str] = None,
    ) -> tuple[str, int]:
        """以單一 transaction 建立 immutable task 與 pending coding_task approval。"""

        task_id = task_id or str(uuid.uuid4())
        try:
            task_id = str(uuid.UUID(task_id))
        except (ValueError, TypeError, AttributeError) as exc:
            raise ValueError("invalid engineering task id") from exc
        if approval_payload.get("engineering_task_id") != task_id:
            raise ValueError("approval payload engineering_task_id mismatch")
        now = now_iso()
        with self._immediate_cursor() as cur:
            cur.execute(
                """
                INSERT INTO approvals
                    (kind, payload, status, created_at, requester_actor_id)
                VALUES ('coding_task', ?, 'pending', ?, ?)
                """,
                (json.dumps(approval_payload), now, requester_actor_id),
            )
            approval_id = int(cur.lastrowid)
            self._append_approval_created_audit(
                cur,
                approval_id=approval_id,
                kind="coding_task",
                requester_actor_id=requester_actor_id,
            )
            cur.execute(
                """
                INSERT INTO engineering_tasks
                    (id, approval_id, project_id, project_name,
                     project_version_id, base_commit, agent_provider_id,
                     provider_capabilities, execution_contract, contract_version, structured_request,
                     instruction, detected_metadata, runner_server,
                     validation_target, status, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                        'pending_approval', ?, ?)
                """,
                (
                    task_id,
                    approval_id,
                    project_id,
                    project_name,
                    project_version_id,
                    base_commit,
                    agent_provider_id,
                    json.dumps(provider_capabilities),
                    json.dumps(execution_contract),
                    contract_version,
                    json.dumps(structured_request),
                    instruction,
                    json.dumps(detected_metadata),
                    runner_server,
                    validation_target,
                    now,
                    now,
                ),
            )
            self._insert_engineering_task_event_cur(
                cur,
                task_id=task_id,
                event_type="task_created",
                phase="approval",
                state="pending_approval",
                summary="AI Engineering Task 已建立，等待人工核准",
                details={
                    "approval_id": approval_id,
                    "project_version_id": project_version_id,
                    "base_commit": base_commit,
                    "agent_provider_id": agent_provider_id,
                },
                source_kind="task",
                source_id=str(approval_id),
                actor_id=requester_actor_id,
                event_key=f"task-created:{task_id}",
                occurred_at=now,
                recorded_at=now,
            )
            self.append_durable_audit_event_in_transaction(
                cur,
                action="engineering_task_created",
                params={
                    "task_id": task_id,
                    "project_id": project_id,
                    "project_name": project_name,
                    "project_version_id": project_version_id,
                    "contract_version": contract_version,
                    "runner_server": runner_server,
                },
                result="pending_approval",
                resource_type="engineering_task",
                resource_id=task_id,
                approval_id=approval_id,
                actor_id=requester_actor_id or "system",
                actor_kind="actor" if requester_actor_id else "system",
                authentication="engineering_task_request",
                event_id=f"engineering-task:{task_id}:created",
            )
        return task_id, approval_id

    def get_engineering_task(self, task_id: str) -> Optional[EngineeringTask]:
        with self.cursor() as cur:
            cur.execute("SELECT * FROM engineering_tasks WHERE id = ?", (task_id,))
            row = cur.fetchone()
            return EngineeringTask.from_row(row) if row else None

    def get_engineering_task_by_approval_id(
        self, approval_id: int
    ) -> Optional[EngineeringTask]:
        with self.cursor() as cur:
            cur.execute(
                "SELECT * FROM engineering_tasks WHERE approval_id = ?", (approval_id,)
            )
            row = cur.fetchone()
            return EngineeringTask.from_row(row) if row else None

    def list_engineering_tasks(
        self,
        *,
        project: Optional[str] = None,
        status: Optional[str] = None,
        limit: int = 50,
    ) -> list[EngineeringTask]:
        query = "SELECT * FROM engineering_tasks WHERE 1=1"
        params: list[Any] = []
        if project:
            query += " AND project_name = ?"
            params.append(project)
        if status:
            query += " AND status = ?"
            params.append(status)
        query += " ORDER BY created_at DESC, id DESC LIMIT ?"
        params.append(limit)
        with self.cursor() as cur:
            cur.execute(query, params)
            return [EngineeringTask.from_row(row) for row in cur.fetchall()]

    @staticmethod
    def _validate_engineering_visibility_text(value: str, *, field_name: str) -> None:
        if not value or len(value) > 512 or any(char in value for char in ("\n", "\r", "\0")):
            raise ValueError(f"invalid engineering visibility {field_name}")
        lowered = value.lower()
        if any(
            marker in lowered
            for marker in ("-----begin ", "authorization:", "bearer ", "/home/", "../")
        ):
            raise ValueError(f"unsafe engineering visibility {field_name}")

    @staticmethod
    def _validate_engineering_event_details(details: Optional[dict]) -> dict:
        if details is None:
            return {}
        if not isinstance(details, dict):
            raise ValueError("engineering event details must be an object")

        forbidden_keys = (
            "token",
            "secret",
            "password",
            "passwd",
            "cookie",
            "command",
            "credential",
            "authorization",
            "private_key",
            "api_key",
            "access_key",
            "session_key",
            "ssh_key",
            "log",
            "diff",
            "path",
        )
        unsafe_values = (
            "-----begin ",
            "authorization:",
            "authorization=",
            "bearer ",
            "access_token=",
            "access_token:",
            "api_key=",
            "api_key:",
            "api-key=",
            "api-key:",
            "password=",
            "password:",
            "passwd=",
            "passwd:",
            "secret=",
            "secret:",
            "cookie=",
            "cookie:",
            "/home/",
            "/root/",
            "/tmp/",
            "github_pat_",
            "ghp_",
            "gho_",
            "ghu_",
            "ghs_",
            "ghr_",
            "sk-",
            "akia",
            "c:\\users\\",
            "c:/users/",
        )

        def normalize(value: Any, *, depth: int) -> Any:
            if depth > 8:
                raise ValueError("engineering event details are too deeply nested")
            if isinstance(value, dict):
                normalized_object: dict[str, Any] = {}
                for key, nested_value in value.items():
                    if not isinstance(key, str) or not key or len(key) > 128:
                        raise ValueError("engineering event details contain an invalid field")
                    lowered_key = key.casefold().replace("-", "_")
                    if any(marker in lowered_key for marker in forbidden_keys):
                        raise ValueError(
                            "engineering event details contain a forbidden field"
                        )
                    if any(char in key for char in ("\n", "\r", "\0")):
                        raise ValueError("engineering event details contain an invalid field")
                    normalized_object[key] = normalize(nested_value, depth=depth + 1)
                return normalized_object
            if isinstance(value, (list, tuple)):
                return [normalize(item, depth=depth + 1) for item in value]
            if value is None or isinstance(value, (str, bool, int)):
                if isinstance(value, str):
                    if any(char in value for char in ("\0",)):
                        raise ValueError(
                            "engineering event details contain unsafe content"
                        )
                    lowered_value = value.casefold()
                    if any(marker in lowered_value for marker in unsafe_values):
                        raise ValueError(
                            "engineering event details contain unsafe content"
                        )
                return value
            if isinstance(value, float) and math.isfinite(value):
                return value
            raise ValueError("engineering event details contain an unsupported value")

        normalized = normalize(details, depth=0)
        encoded = json.dumps(normalized, sort_keys=True, separators=(",", ":"))
        if len(encoded) > 4096:
            raise ValueError("engineering event details are too large")
        return normalized

    def append_engineering_task_event(
        self,
        *,
        task_id: str,
        event_key: str,
        event_type: str,
        source_kind: str,
        summary: str,
        attempt_number: Optional[int] = None,
        phase: Optional[str] = None,
        state: Optional[str] = None,
        source_id: Optional[str] = None,
        actor_id: Optional[str] = None,
        details: Optional[dict] = None,
        occurred_at: Optional[str] = None,
        recorded_at: Optional[str] = None,
    ) -> EngineeringTaskEvent:
        """Append an idempotent, bounded visibility fact.

        Reusing a key with different immutable content fails closed.  This is a
        query journal only; it never drives Approval, Job or CodingRun state.
        """

        for value, name in (
            (event_key, "event_key"),
            (event_type, "event_type"),
            (source_kind, "source_kind"),
            (summary, "summary"),
        ):
            self._validate_engineering_visibility_text(value, field_name=name)
        if source_kind not in VALID_ENGINEERING_EVENT_SOURCES:
            raise ValueError("invalid engineering event source")
        safe_details = self._validate_engineering_event_details(details)
        with self.cursor() as cur:
            cur.execute("SELECT 1 FROM engineering_tasks WHERE id = ?", (task_id,))
            if cur.fetchone() is None:
                raise ValueError("engineering task does not exist")
            self._insert_engineering_task_event_cur(
                cur,
                task_id=task_id,
                event_key=event_key,
                event_type=event_type,
                source_kind=source_kind,
                summary=summary,
                attempt_number=attempt_number,
                phase=phase,
                state=state,
                source_id=source_id,
                actor_id=actor_id,
                details=safe_details,
                occurred_at=occurred_at,
                recorded_at=recorded_at,
            )
            cur.execute(
                """
                SELECT * FROM engineering_task_events
                WHERE engineering_task_id = ? AND event_key = ?
                """,
                (task_id, event_key),
            )
            return EngineeringTaskEvent.from_row(cur.fetchone())

    def list_engineering_task_events(
        self,
        task_id: str,
        *,
        after_id: int = 0,
        attempt_number: Optional[int] = None,
        limit: int = 100,
    ) -> list[EngineeringTaskEvent]:
        query = (
            "SELECT * FROM engineering_task_events "
            "WHERE engineering_task_id = ? AND id > ?"
        )
        params: list[Any] = [task_id, max(after_id, 0)]
        if attempt_number is not None:
            query += " AND attempt_number = ?"
            params.append(attempt_number)
        query += " ORDER BY id ASC LIMIT ?"
        params.append(max(1, min(limit, 200)))
        with self.cursor() as cur:
            cur.execute(query, params)
            return [EngineeringTaskEvent.from_row(row) for row in cur.fetchall()]

    def get_engineering_task_presentation_flags(self, task_id: str) -> dict[str, bool]:
        """Return full-journal safety flags used by task presentation.

        Timeline pages are intentionally bounded, so presentation must not infer
        the absence of a safety-significant event from the first page.  Keep the
        query and returned key set fixed: this is not a general event search API.
        """

        event_types = ("execution_interrupted", "runner_contract_mismatch")
        with self.cursor() as cur:
            cur.execute(
                """
                SELECT DISTINCT event_type
                FROM engineering_task_events
                WHERE engineering_task_id = ?
                  AND event_type IN (?, ?)
                """,
                (task_id, *event_types),
            )
            observed = {str(row["event_type"]) for row in cur.fetchall()}
        return {event_type: event_type in observed for event_type in event_types}

    def register_engineering_task_command(
        self,
        *,
        task_id: str,
        attempt_number: int,
        sequence: int,
        command_key: str,
        command_role: str,
        display_command: str,
        execution_location: str,
        working_directory_label: str,
        policy_family: str,
        policy_disposition: str,
        status_source: str,
        job_id: Optional[int] = None,
        coding_run_id: Optional[int] = None,
        command_digest: Optional[str] = None,
        target_ref: Optional[str] = None,
        approval_id: Optional[int] = None,
        recorded_status: Optional[str] = None,
        recorded_started_at: Optional[str] = None,
        recorded_finished_at: Optional[str] = None,
        recorded_exit_code: Optional[int] = None,
    ) -> EngineeringTaskCommand:
        if attempt_number < 1 or sequence < 1:
            raise ValueError("engineering command attempt/sequence must be positive")
        for value, name in (
            (command_key, "command_key"),
            (command_role, "command_role"),
            (display_command, "display_command"),
            (execution_location, "execution_location"),
            (working_directory_label, "working_directory_label"),
            (policy_family, "policy_family"),
            (policy_disposition, "policy_disposition"),
            (status_source, "status_source"),
        ):
            self._validate_engineering_visibility_text(value, field_name=name)
        if command_role not in VALID_ENGINEERING_COMMAND_ROLES:
            raise ValueError("invalid engineering command role")
        if execution_location not in VALID_ENGINEERING_EXECUTION_LOCATIONS:
            raise ValueError("invalid engineering execution location")
        if policy_disposition not in VALID_ENGINEERING_POLICY_DISPOSITIONS:
            raise ValueError("invalid engineering command policy disposition")
        if status_source not in VALID_ENGINEERING_STATUS_SOURCES:
            raise ValueError("invalid engineering command status source")
        if command_digest is not None and (
            len(command_digest) != 64 or not _is_full_hex_digest(command_digest)
        ):
            raise ValueError("invalid engineering command digest")
        now = now_iso()
        spec = (
            task_id,
            attempt_number,
            sequence,
            command_key,
            job_id,
            coding_run_id,
            command_role,
            display_command,
            command_digest,
            execution_location,
            target_ref,
            working_directory_label,
            policy_family,
            policy_disposition,
            approval_id,
            status_source,
        )
        with self.cursor() as cur:
            cur.execute("SELECT 1 FROM engineering_tasks WHERE id = ?", (task_id,))
            if cur.fetchone() is None:
                raise ValueError("engineering task does not exist")
            if job_id is not None:
                cur.execute(
                    """
                    SELECT 1 FROM jobs
                    WHERE id = ? AND engineering_task_id = ?
                      AND engineering_attempt_number = ?
                    """,
                    (job_id, task_id, attempt_number),
                )
                if cur.fetchone() is None:
                    raise ValueError("engineering command job ownership mismatch")
            if coding_run_id is not None:
                cur.execute(
                    """
                    SELECT 1 FROM coding_runs
                    WHERE id = ? AND engineering_task_id = ? AND attempt_number = ?
                    """,
                    (coding_run_id, task_id, attempt_number),
                )
                if cur.fetchone() is None:
                    raise ValueError("engineering command run ownership mismatch")
            cur.execute(
                """
                INSERT OR IGNORE INTO engineering_task_commands
                    (engineering_task_id, attempt_number, sequence, command_key,
                     job_id, coding_run_id, command_role, display_command,
                     command_digest, execution_location, target_ref,
                     working_directory_label, policy_family, policy_disposition,
                     approval_id, status_source, recorded_status,
                     recorded_started_at, recorded_finished_at,
                     recorded_exit_code, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                spec
                + (
                    recorded_status,
                    recorded_started_at,
                    recorded_finished_at,
                    recorded_exit_code,
                    now,
                    now,
                ),
            )
            cur.execute(
                """
                SELECT * FROM engineering_task_commands
                WHERE engineering_task_id = ? AND attempt_number = ? AND command_key = ?
                """,
                (task_id, attempt_number, command_key),
            )
            row = cur.fetchone()
            if row is None:
                raise ValueError("engineering command registration failed")
            actual_spec = tuple(
                row[column]
                for column in (
                    "engineering_task_id", "attempt_number", "sequence", "command_key",
                    "job_id", "coding_run_id", "command_role", "display_command",
                    "command_digest", "execution_location", "target_ref",
                    "working_directory_label", "policy_family", "policy_disposition",
                    "approval_id", "status_source",
                )
            )
            if actual_spec != spec:
                raise ValueError("engineering command idempotency conflict")
            return EngineeringTaskCommand.from_row(row)

    def update_engineering_task_command_observation(
        self,
        command_id: int,
        *,
        recorded_status: Optional[str],
        recorded_started_at: Optional[str],
        recorded_finished_at: Optional[str],
        recorded_exit_code: Optional[int],
    ) -> Optional[EngineeringTaskCommand]:
        with self.cursor() as cur:
            cur.execute(
                """
                UPDATE engineering_task_commands
                SET recorded_status = ?, recorded_started_at = ?,
                    recorded_finished_at = ?, recorded_exit_code = ?, updated_at = ?
                WHERE id = ?
                """,
                (
                    recorded_status,
                    recorded_started_at,
                    recorded_finished_at,
                    recorded_exit_code,
                    now_iso(),
                    command_id,
                ),
            )
            cur.execute("SELECT * FROM engineering_task_commands WHERE id = ?", (command_id,))
            row = cur.fetchone()
            return EngineeringTaskCommand.from_row(row) if row else None

    def list_engineering_task_commands(
        self,
        task_id: str,
        *,
        attempt_number: Optional[int] = None,
        after_id: int = 0,
        limit: int = 100,
    ) -> list[EngineeringTaskCommand]:
        query = (
            "SELECT * FROM engineering_task_commands "
            "WHERE engineering_task_id = ? AND id > ?"
        )
        params: list[Any] = [task_id, max(after_id, 0)]
        if attempt_number is not None:
            query += " AND attempt_number = ?"
            params.append(attempt_number)
        query += " ORDER BY attempt_number, sequence, id LIMIT ?"
        params.append(max(1, min(limit, 200)))
        with self.cursor() as cur:
            cur.execute(query, params)
            return [EngineeringTaskCommand.from_row(row) for row in cur.fetchall()]

    def get_engineering_task_command(
        self, task_id: str, command_id: int
    ) -> Optional[EngineeringTaskCommand]:
        with self.cursor() as cur:
            cur.execute(
                """
                SELECT * FROM engineering_task_commands
                WHERE engineering_task_id = ? AND id = ?
                """,
                (task_id, command_id),
            )
            row = cur.fetchone()
            return EngineeringTaskCommand.from_row(row) if row else None

    def get_engineering_task_command_by_job_id(
        self, job_id: int
    ) -> Optional[EngineeringTaskCommand]:
        """Return the immutable command-journal row owned by one Job.

        ``idx_engineering_task_commands_job`` makes this relation one-to-one
        whenever ``job_id`` is present.  Execution contract gates use this
        narrow lookup instead of trusting the mutable ``jobs.command`` column
        on its own.
        """

        with self.cursor() as cur:
            cur.execute(
                "SELECT * FROM engineering_task_commands WHERE job_id = ?",
                (job_id,),
            )
            row = cur.fetchone()
            return EngineeringTaskCommand.from_row(row) if row else None

    def register_engineering_task_artifact(
        self,
        *,
        task_id: str,
        attempt_number: int,
        artifact_key: str,
        kind: str,
        label: str,
        storage_kind: str,
        coding_run_id: Optional[int] = None,
        source_job_id: Optional[int] = None,
        storage_key: Optional[str] = None,
        content_type: Optional[str] = None,
        verification_status: str = "pending",
        redaction_status: str = "pending",
        availability: str = "pending",
    ) -> EngineeringTaskArtifact:
        if attempt_number < 1:
            raise ValueError("engineering artifact attempt must be positive")
        for value, name in (
            (artifact_key, "artifact_key"),
            (kind, "kind"),
            (label, "label"),
            (storage_kind, "storage_kind"),
            (verification_status, "verification_status"),
            (redaction_status, "redaction_status"),
            (availability, "availability"),
        ):
            self._validate_engineering_visibility_text(value, field_name=name)
        if availability not in VALID_ENGINEERING_ARTIFACT_AVAILABILITY:
            raise ValueError("invalid engineering artifact availability")
        if verification_status not in VALID_ENGINEERING_ARTIFACT_VERIFICATION:
            raise ValueError("invalid engineering artifact verification status")
        if redaction_status not in VALID_ENGINEERING_ARTIFACT_REDACTION:
            raise ValueError("invalid engineering artifact redaction status")
        if storage_key is not None:
            self._validate_engineering_visibility_text(storage_key, field_name="storage_key")
            if "/" in storage_key or "\\" in storage_key:
                raise ValueError("artifact storage_key must be opaque")
        artifact_id = str(uuid.uuid5(uuid.NAMESPACE_URL, f"{task_id}:{attempt_number}:{artifact_key}"))
        now = now_iso()
        identity = (
            artifact_id,
            artifact_key,
            task_id,
            attempt_number,
            coding_run_id,
            source_job_id,
            kind,
            label,
            storage_kind,
            storage_key,
            content_type,
        )
        with self.cursor() as cur:
            cur.execute("SELECT 1 FROM engineering_tasks WHERE id = ?", (task_id,))
            if cur.fetchone() is None:
                raise ValueError("engineering task does not exist")
            if source_job_id is not None:
                cur.execute(
                    """
                    SELECT 1 FROM jobs
                    WHERE id = ? AND engineering_task_id = ?
                      AND engineering_attempt_number = ?
                    """,
                    (source_job_id, task_id, attempt_number),
                )
                if cur.fetchone() is None:
                    raise ValueError("engineering artifact job ownership mismatch")
            if coding_run_id is not None:
                cur.execute(
                    """
                    SELECT 1 FROM coding_runs
                    WHERE id = ? AND engineering_task_id = ? AND attempt_number = ?
                    """,
                    (coding_run_id, task_id, attempt_number),
                )
                if cur.fetchone() is None:
                    raise ValueError("engineering artifact run ownership mismatch")
            cur.execute(
                """
                INSERT OR IGNORE INTO engineering_task_artifacts
                    (id, artifact_key, engineering_task_id, attempt_number,
                     coding_run_id, source_job_id, kind, label, storage_kind,
                     storage_key, content_type, verification_status,
                     redaction_status, availability, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                identity
                + (
                    verification_status,
                    redaction_status,
                    availability,
                    now,
                    now,
                ),
            )
            cur.execute("SELECT * FROM engineering_task_artifacts WHERE id = ?", (artifact_id,))
            row = cur.fetchone()
            if row is None:
                raise ValueError("engineering artifact registration failed")
            actual = tuple(
                row[column]
                for column in (
                    "id", "artifact_key", "engineering_task_id", "attempt_number",
                    "coding_run_id", "source_job_id", "kind", "label", "storage_kind",
                    "storage_key", "content_type",
                )
            )
            if actual != identity:
                raise ValueError("engineering artifact idempotency conflict")
            return EngineeringTaskArtifact.from_row(row)

    def record_engineering_task_artifact_collection(
        self,
        artifact_id: str,
        *,
        source_sha256: Optional[str],
        source_size_bytes: Optional[int],
        verification_status: str,
        redaction_status: str,
        availability: str,
        collected_at: Optional[str] = None,
    ) -> Optional[EngineeringTaskArtifact]:
        if source_sha256 is not None and (
            len(source_sha256) != 64 or not _is_full_hex_digest(source_sha256)
        ):
            raise ValueError("invalid engineering artifact digest")
        if source_size_bytes is not None and source_size_bytes < 0:
            raise ValueError("invalid engineering artifact size")
        now = now_iso()
        if availability not in VALID_ENGINEERING_ARTIFACT_AVAILABILITY:
            raise ValueError("invalid engineering artifact availability")
        if verification_status not in VALID_ENGINEERING_ARTIFACT_VERIFICATION:
            raise ValueError("invalid engineering artifact verification status")
        if redaction_status not in VALID_ENGINEERING_ARTIFACT_REDACTION:
            raise ValueError("invalid engineering artifact redaction status")
        with self.cursor() as cur:
            cur.execute("SELECT * FROM engineering_task_artifacts WHERE id = ?", (artifact_id,))
            existing = cur.fetchone()
            if existing is None:
                return None
            if existing["source_sha256"] not in (None, source_sha256):
                raise ValueError("engineering artifact digest is immutable")
            if existing["source_size_bytes"] not in (None, source_size_bytes):
                raise ValueError("engineering artifact size is immutable")
            forward = {
                "verification_status": {
                    "pending": VALID_ENGINEERING_ARTIFACT_VERIFICATION,
                    "unknown": {"unknown", "pending", "verified", "rejected"},
                    "not_required": {"not_required"},
                    "verified": {"verified"},
                    "rejected": {"rejected"},
                },
                "redaction_status": {
                    "pending": VALID_ENGINEERING_ARTIFACT_REDACTION,
                    "not_applicable": {"not_applicable"},
                    "redacted": {"redacted"},
                    "withheld": {"withheld"},
                },
                "availability": {
                    "pending": VALID_ENGINEERING_ARTIFACT_AVAILABILITY,
                    "missing": VALID_ENGINEERING_ARTIFACT_AVAILABILITY,
                    "available": {"available", "cleaned"},
                    "withheld": {"withheld", "cleaned"},
                    "rejected": {"rejected", "cleaned"},
                    "cleaned": {"cleaned"},
                },
            }
            for field_name, requested in (
                ("verification_status", verification_status),
                ("redaction_status", redaction_status),
                ("availability", availability),
            ):
                if requested not in forward[field_name][existing[field_name]]:
                    raise ValueError(f"engineering artifact {field_name} cannot regress")
            cur.execute(
                """
                UPDATE engineering_task_artifacts
                SET source_sha256 = COALESCE(source_sha256, ?),
                    source_size_bytes = COALESCE(source_size_bytes, ?),
                    verification_status = ?, redaction_status = ?,
                    availability = ?, collected_at = COALESCE(collected_at, ?),
                    updated_at = ?
                WHERE id = ?
                """,
                (
                    source_sha256,
                    source_size_bytes,
                    verification_status,
                    redaction_status,
                    availability,
                    collected_at or now,
                    now,
                    artifact_id,
                ),
            )
            cur.execute("SELECT * FROM engineering_task_artifacts WHERE id = ?", (artifact_id,))
            return EngineeringTaskArtifact.from_row(cur.fetchone())

    def mark_engineering_task_artifacts_cleaned(
        self, *, task_id: str, attempt_number: Optional[int] = None
    ) -> int:
        query = (
            "UPDATE engineering_task_artifacts SET availability = 'cleaned', updated_at = ? "
            "WHERE engineering_task_id = ? AND availability != 'cleaned'"
        )
        params: list[Any] = [now_iso(), task_id]
        if attempt_number is not None:
            query += " AND attempt_number = ?"
            params.append(attempt_number)
        with self.cursor() as cur:
            cur.execute(query, params)
            return cur.rowcount

    def list_engineering_task_artifacts(
        self, task_id: str, *, attempt_number: Optional[int] = None
    ) -> list[EngineeringTaskArtifact]:
        query = "SELECT * FROM engineering_task_artifacts WHERE engineering_task_id = ?"
        params: list[Any] = [task_id]
        if attempt_number is not None:
            query += " AND attempt_number = ?"
            params.append(attempt_number)
        query += " ORDER BY attempt_number, kind, id"
        with self.cursor() as cur:
            cur.execute(query, params)
            return [EngineeringTaskArtifact.from_row(row) for row in cur.fetchall()]

