    def list_engineering_task_approvals(self, task_id: str) -> list[Approval]:
        """Return the parent and linked Worker-validation approvals in order.

        ``UNION`` deliberately deduplicates approval ids before the canonical
        ``created_at, id`` ordering is applied.  Callers still have to use a
        safe projection: :class:`Approval` contains the immutable payload and
        must not be serialized wholesale by task-detail APIs.
        """

        with self.cursor() as cur:
            cur.execute(
                """
                SELECT approval.*
                FROM approvals AS approval
                WHERE approval.id IN (
                    SELECT approval_id
                    FROM engineering_tasks
                    WHERE id = ?
                    UNION
                    SELECT approval_id
                    FROM engineering_validation_requests
                    WHERE engineering_task_id = ?
                )
                ORDER BY approval.created_at, approval.id
                """,
                (task_id, task_id),
            )
            return [Approval.from_row(row) for row in cur.fetchall()]

    @staticmethod
    def _next_engineering_validation_transition_number_cur(
        cur: sqlite3.Cursor,
        *,
        task_id: str,
        transition_prefix: str,
    ) -> int:
        """Return a collision-free, deterministic transition ordinal.

        Event rows are append-only, but a restored or manually inspected
        database can contain gaps or malformed keys.  Counting matching rows
        is therefore not an ordinal allocator: one existing ``4:running`` row
        plus two unrelated/malformed rows would make ``COUNT(*) + 1`` choose
        the already-used ordinal 4.  Parse bounded positive decimal ordinals
        and choose the first unused value instead.

        The exact-prefix ``substr`` predicate deliberately avoids SQL ``LIKE``
        wildcard semantics.  Oversized numeric fragments are treated as
        malformed, so corrupt input cannot force unbounded integer parsing.
        """

        cur.execute(
            """
            SELECT event_key
            FROM engineering_task_events
            WHERE engineering_task_id = ?
              AND substr(event_key, 1, ?) = ?
            """,
            (task_id, len(transition_prefix), transition_prefix),
        )
        used_ordinals: set[int] = set()
        for event in cur.fetchall():
            event_key = event["event_key"]
            if not isinstance(event_key, str):
                continue
            ordinal_text, separator, _state = event_key[
                len(transition_prefix) :
            ].partition(":")
            if (
                not separator
                or not ordinal_text
                or len(ordinal_text) > 128
                or not ordinal_text.isascii()
                or not ordinal_text.isdecimal()
            ):
                continue
            ordinal = int(ordinal_text)
            if ordinal > 0:
                used_ordinals.add(ordinal)
        candidate = 1
        while candidate in used_ordinals:
            candidate += 1
        return candidate

    def reject_engineering_validation_approval(
        self,
        *,
        validation_request_id: str,
        approval_id: int,
        note: Optional[str],
        decision_actor_id: Optional[str],
        decision_mechanism: str,
    ) -> None:
        """Atomically reject a pending Worker-validation proposal.

        Rejection is a decision on the linked ordinary ``enqueue`` approval,
        but the validation projection and its safe journal fact must become
        durable in the same transaction.  No read-side refresh is required,
        and a proposal that has acquired any Job linkage fails closed.
        """

        timestamp = now_iso()
        with self._immediate_cursor() as cur:
            cur.execute(
                """
                SELECT validation.engineering_task_id,
                       validation.attempt_number,
                       validation.status AS validation_status,
                       validation.bundle_push_job_id,
                       validation.downstream_job_id,
                       approval.kind AS approval_kind,
                       approval.status AS approval_status
                FROM engineering_validation_requests AS validation
                JOIN approvals AS approval
                  ON approval.id = validation.approval_id
                WHERE validation.id = ? AND approval.id = ?
                """,
                (validation_request_id, approval_id),
            )
            row = cur.fetchone()
            if row is None:
                raise ValueError("engineering validation approval linkage is missing")
            if (
                row["approval_kind"] != "enqueue"
                or row["approval_status"] != "pending"
                or row["validation_status"] != "pending_approval"
                or row["bundle_push_job_id"] is not None
                or row["downstream_job_id"] is not None
            ):
                raise ValueError("engineering validation approval is not rejectable")
            cur.execute(
                """
                SELECT 1
                FROM jobs
                WHERE engineering_validation_request_id = ?
                LIMIT 1
                """,
                (validation_request_id,),
            )
            if cur.fetchone() is not None:
                raise ValueError("engineering validation already has linked Jobs")

            cur.execute(
                """
                UPDATE approvals
                SET status = 'rejected', decided_at = ?, note = ?,
                    decision_actor_id = ?, decision_mechanism = ?
                WHERE id = ? AND status = 'pending'
                """,
                (
                    timestamp,
                    note,
                    decision_actor_id,
                    decision_mechanism,
                    approval_id,
                ),
            )
            if cur.rowcount != 1:
                raise ValueError(
                    "engineering validation approval changed during rejection"
                )
            self._append_approval_decided_audit(
                cur,
                approval_id=approval_id,
                kind=str(row["approval_kind"]),
                status="rejected",
                decision_actor_id=decision_actor_id,
                decision_mechanism=decision_mechanism,
            )
            cur.execute(
                """
                UPDATE engineering_validation_requests
                SET status = 'rejected', result_status = NULL,
                    result_exit_code = NULL, result_finished_at = NULL,
                    updated_at = ?
                WHERE id = ? AND status = 'pending_approval'
                  AND bundle_push_job_id IS NULL
                  AND downstream_job_id IS NULL
                """,
                (timestamp, validation_request_id),
            )
            if cur.rowcount != 1:
                raise ValueError(
                    "engineering validation state changed during rejection"
                )
            self._insert_engineering_task_event_cur(
                cur,
                task_id=row["engineering_task_id"],
                attempt_number=row["attempt_number"],
                event_key=f"worker-validation:{validation_request_id}:rejected",
                event_type="worker_validation_rejected",
                phase="validation",
                state="rejected",
                summary=_ENGINEERING_VALIDATION_STATUS_SUMMARIES["rejected"],
                details={
                    "approval_id": approval_id,
                    "previous_state": "requested",
                    "validation_request_id": validation_request_id,
                },
                source_kind="approval",
                source_id=str(approval_id),
                actor_id=decision_actor_id,
                occurred_at=timestamp,
                recorded_at=timestamp,
            )

    def finalize_engineering_validation_request(
        self,
        *,
        validation_request_id: str,
        approval_id: int,
        request_snapshot_sha256: str,
        bundle_push_command: str,
        downstream_command: str,
        job_type: str,
        project: str,
        target_server: str,
        require_tag: Optional[str],
        gpus_needed: Optional[int],
        priority: str,
        source_coding_run_id: int,
        approval_note: Optional[str],
        decision_actor_id: Optional[str],
        decision_mechanism: str,
    ) -> tuple[int, int]:
        """Approve and publish the push/main ordinary Jobs in one transaction."""

        if job_type not in VALID_TYPES or priority not in VALID_PRIORITIES:
            raise ValueError("invalid engineering validation Job contract")
        push_digest = hashlib.sha256(bundle_push_command.encode("utf-8")).hexdigest()
        downstream_digest = hashlib.sha256(
            downstream_command.encode("utf-8")
        ).hexdigest()
        timestamp = now_iso()
        with self._immediate_cursor() as cur:
            cur.execute("SELECT * FROM approvals WHERE id = ?", (approval_id,))
            approval = cur.fetchone()
            cur.execute(
                "SELECT * FROM engineering_validation_requests WHERE id = ?",
                (validation_request_id,),
            )
            validation = cur.fetchone()
            if (
                approval is None
                or approval["kind"] != "enqueue"
                or approval["status"] != "pending"
                or validation is None
                or validation["approval_id"] != approval_id
                or validation["status"] != "pending_approval"
                or validation["request_snapshot_sha256"]
                != request_snapshot_sha256
                or validation["project_name"] != project
                or validation["target_server"] != target_server
                or validation["coding_run_id"] != source_coding_run_id
                or validation["bundle_push_job_id"] is not None
                or validation["downstream_job_id"] is not None
            ):
                raise ValueError("engineering validation request is not finalizable")
            approval_payload = json.loads(approval["payload"] or "{}")
            if (
                approval_payload.get("validation_request_id")
                != validation_request_id
                or approval_payload.get("request_snapshot_sha256")
                != request_snapshot_sha256
            ):
                raise ValueError("engineering validation approval payload changed")
            snapshot = json.loads(validation["request_snapshot"] or "{}")
            execution_snapshot = snapshot.get("execution")
            parent_approval_snapshot = snapshot.get("parent_approval")
            if not isinstance(execution_snapshot, dict) or not isinstance(
                parent_approval_snapshot, dict
            ):
                raise ValueError("engineering validation snapshot changed")
            if (
                execution_snapshot.get("bundle_push_command_sha256") != push_digest
                or execution_snapshot.get("downstream_command_sha256")
                != downstream_digest
            ):
                raise ValueError("engineering validation generated command changed")
            cur.execute(
                "SELECT * FROM engineering_tasks WHERE id = ?",
                (validation["engineering_task_id"],),
            )
            task = cur.fetchone()
            cur.execute(
                "SELECT * FROM coding_runs WHERE id = ?",
                (source_coding_run_id,),
            )
            run = cur.fetchone()
            cur.execute(
                "SELECT * FROM project_versions WHERE id = ?",
                (validation["project_version_id"],),
            )
            version = cur.fetchone()
            parent_approval = None
            if task is not None:
                cur.execute(
                    "SELECT * FROM approvals WHERE id = ?", (task["approval_id"],)
                )
                parent_approval = cur.fetchone()
            if (
                task is None
                or run is None
                or version is None
                or parent_approval is None
                or parent_approval["kind"] != "coding_task"
                or parent_approval["status"] != "approved"
                or parent_approval["id"] != parent_approval_snapshot.get("id")
                or hashlib.sha256(
                    json.dumps(
                        json.loads(parent_approval["payload"] or "{}"),
                        sort_keys=True,
                        separators=(",", ":"),
                    ).encode("utf-8")
                ).hexdigest()
                != parent_approval_snapshot.get("payload_sha256")
                or task["coding_run_id"] != source_coding_run_id
                or task["project_id"] != validation["project_id"]
                or task["project_name"] != validation["project_name"]
                or task["project_version_id"] != validation["project_version_id"]
                or task["base_commit"] != validation["base_commit"]
                or run["engineering_task_id"] != validation["engineering_task_id"]
                or run["attempt_number"] != validation["attempt_number"]
                or run["project_version_id"] != validation["project_version_id"]
                or run["base_binding"] != "project_version_pinned"
                or run["base_commit"] != validation["base_commit"]
                or run["status"] != "done"
                or run["result_commit"] != validation["result_commit"]
                or version["project_id"] != validation["project_id"]
                or version["project_name"] != validation["project_name"]
                or version["git_commit"] != validation["base_commit"]
            ):
                raise ValueError("engineering validation parent contract changed")

            cur.execute(
                """
                INSERT INTO jobs
                    (type, project, command, pin_server, depends_on, status,
                     priority, created_at, engineering_validation_request_id)
                VALUES ('sync', ?, ?, '_local', '[]', 'queued', 'normal', ?, ?)
                """,
                (project, bundle_push_command, timestamp, validation_request_id),
            )
            push_job_id = int(cur.lastrowid)
            cur.execute(
                """
                INSERT INTO jobs
                    (type, project, command, require_tag, pin_server,
                     depends_on, gpus_needed, status, priority, created_at,
                     source_coding_run_id, engineering_validation_request_id)
                VALUES (?, ?, ?, ?, ?, ?, ?, 'queued', ?, ?, ?, ?)
                """,
                (
                    job_type,
                    project,
                    downstream_command,
                    require_tag,
                    target_server,
                    json.dumps([push_job_id]),
                    gpus_needed,
                    priority,
                    timestamp,
                    source_coding_run_id,
                    validation_request_id,
                ),
            )
            downstream_job_id = int(cur.lastrowid)
            cur.execute(
                """
                UPDATE engineering_validation_requests
                SET status = 'queued', bundle_push_job_id = ?,
                    downstream_job_id = ?, result_status = 'queued',
                    bundle_push_command_sha256 = ?,
                    downstream_command_sha256 = ?, updated_at = ?
                WHERE id = ? AND status = 'pending_approval'
                """,
                (
                    push_job_id,
                    downstream_job_id,
                    push_digest,
                    downstream_digest,
                    timestamp,
                    validation_request_id,
                ),
            )
            if cur.rowcount != 1:
                raise ValueError("engineering validation linkage changed")
            final_note = approval_note or (
                f"已建立 worker validation Job #{downstream_job_id}"
                f"（bundle push Job #{push_job_id}）"
            )
            cur.execute(
                """
                UPDATE approvals
                SET status = 'approved', decided_at = ?, note = ?,
                    decision_actor_id = ?, decision_mechanism = ?
                WHERE id = ? AND status = 'pending'
                """,
                (
                    timestamp,
                    final_note,
                    decision_actor_id,
                    decision_mechanism,
                    approval_id,
                ),
            )
            if cur.rowcount != 1:
                raise ValueError("engineering validation approval changed")
            self._append_approval_decided_audit(
                cur,
                approval_id=approval_id,
                kind=str(approval["kind"]),
                status="approved",
                decision_actor_id=decision_actor_id,
                decision_mechanism=decision_mechanism,
            )
            materialization_actor_id = (
                decision_actor_id
                if isinstance(decision_actor_id, str) and decision_actor_id
                else "system"
            )
            materialization_actor_kind = self._durable_actor_kind(
                cur,
                materialization_actor_id,
                fallback="system" if materialization_actor_id == "system" else None,
            )
            materialization_authentication = (
                decision_mechanism
                if materialization_actor_id != "system"
                else "system"
            )
            for job_id, job_role, dependency_count in (
                (push_job_id, "bundle_push", 0),
                (downstream_job_id, "main", 1),
            ):
                self.append_durable_audit_event_in_transaction(
                    cur,
                    action="execution_job_materialized",
                    params={
                        "approval_kind": "enqueue",
                        "dependency_count": dependency_count,
                        "graph_size": 2,
                        "job_id": job_id,
                        "job_role": job_role,
                        "legacy_unpinned": True,
                        "validation_request_id": validation_request_id,
                    },
                    result="queued",
                    actor_id=materialization_actor_id,
                    actor_kind=materialization_actor_kind,
                    authentication=materialization_authentication,
                    resource_type="job",
                    resource_id=str(job_id),
                    approval_id=approval_id,
                    event_id=f"approval:{approval_id}:job:{job_id}",
                )
            self._insert_engineering_task_event_cur(
                cur,
                task_id=validation["engineering_task_id"],
                attempt_number=validation["attempt_number"],
                event_key=f"worker-validation:{validation_request_id}:queued",
                event_type="worker_validation_queued",
                phase="validation",
                state="queued",
                summary="Worker validation 已核准並排入 ordinary Job 佇列",
                details={
                    "approval_id": approval_id,
                    "bundle_push_job_id": push_job_id,
                    "downstream_job_id": downstream_job_id,
                    "validation_request_id": validation_request_id,
                },
                source_kind="job",
                source_id=str(downstream_job_id),
                actor_id=decision_actor_id,
                occurred_at=timestamp,
                recorded_at=timestamp,
            )
        return push_job_id, downstream_job_id

    def refresh_engineering_validation_request_status(
        self, validation_request_id: str
    ) -> Optional[EngineeringValidationRequest]:
        """Project approval/Job state without guessing unknown remote outcomes."""

        validation_statuses = VALID_STATUSES | {
            "pending_approval",
            "rejected",
            "unknown",
        }
        # The process normally owns one Database object, but tests, CLI tools,
        # and rolling restarts can briefly use multiple SQLite connections.
        # Compare-and-set keeps two observers of the same transition from both
        # journaling it. A bounded retry is enough because this is a derived,
        # presentation-only projection; the next read can safely reconcile
        # again if the row is changing continuously.
        for _attempt in range(4):
            with self.cursor() as cur:
                cur.execute(
                    "SELECT * FROM engineering_validation_requests WHERE id = ?",
                    (validation_request_id,),
                )
                row = cur.fetchone()
                if row is None:
                    return None
                cur.execute(
                    "SELECT * FROM approvals WHERE id = ?", (row["approval_id"],)
                )
                approval = cur.fetchone()
                job = None
                if row["downstream_job_id"] is not None:
                    cur.execute(
                        "SELECT * FROM jobs WHERE id = ?",
                        (row["downstream_job_id"],),
                    )
                    job = cur.fetchone()

                raw_job_status = job["status"] if job is not None else None
                safe_job_status = (
                    raw_job_status if raw_job_status in VALID_STATUSES else "unknown"
                )
                if approval is None:
                    projected = "unknown"
                elif approval["status"] == "pending":
                    projected = "pending_approval"
                elif approval["status"] == "rejected":
                    projected = "rejected"
                elif approval["status"] != "approved" or job is None:
                    projected = "unknown"
                else:
                    projected = safe_job_status

                result_status = safe_job_status if job is not None else None
                if (
                    job is not None
                    and safe_job_status
                    in _ENGINEERING_VALIDATION_TERMINAL_RESULT_STATUSES
                ):
                    result_exit_code = _safe_engineering_validation_exit_code(
                        job["exit_code"]
                    )
                    result_finished_at = _safe_engineering_validation_timestamp(
                        job["finished_at"]
                    )
                else:
                    result_exit_code = None
                    result_finished_at = None
                stored_status = (
                    row["status"] if row["status"] in validation_statuses else "unknown"
                )
                status_changed = stored_status != projected
                projection_changed = (
                    row["status"] != projected
                    or row["result_status"] != result_status
                    or row["result_exit_code"] != result_exit_code
                    or row["result_finished_at"] != result_finished_at
                )
                if not projection_changed:
                    return EngineeringValidationRequest.from_row(row)

                timestamp = now_iso()
                cur.execute(
                    """
                    UPDATE engineering_validation_requests
                    SET status = ?, result_status = ?, result_exit_code = ?,
                        result_finished_at = ?, updated_at = ?
                    WHERE id = ?
                      AND status IS ?
                      AND result_status IS ?
                      AND result_exit_code IS ?
                      AND result_finished_at IS ?
                    """,
                    (
                        projected,
                        result_status,
                        result_exit_code,
                        result_finished_at,
                        timestamp,
                        validation_request_id,
                        row["status"],
                        row["result_status"],
                        row["result_exit_code"],
                        row["result_finished_at"],
                    ),
                )
                if cur.rowcount != 1:
                    continue

                if status_changed:
                    journal_state = (
                        "requested" if projected == "pending_approval" else projected
                    )
                    previous_state = (
                        "requested" if stored_status == "pending_approval" else stored_status
                    )
                    # A Job may legitimately requeue and later run again.  A
                    # deterministic unused per-request ordinal makes every
                    # occurrence unique while the CAS above ensures that two
                    # SQLite connections cannot journal the same observation.
                    transition_prefix = (
                        f"worker-validation:{validation_request_id}:transition:"
                    )
                    transition_number = (
                        self._next_engineering_validation_transition_number_cur(
                            cur,
                            task_id=row["engineering_task_id"],
                            transition_prefix=transition_prefix,
                        )
                    )
                    source_kind = "job" if job is not None else "approval"
                    source_id = (
                        str(row["downstream_job_id"])
                        if job is not None
                        else str(row["approval_id"])
                    )
                    actor_id = (
                        approval["decision_actor_id"]
                        if approval is not None and projected == "rejected"
                        else None
                    )
                    occurred_at = timestamp
                    if projected == "rejected" and approval is not None:
                        occurred_at = (
                            _safe_engineering_validation_timestamp(
                                approval["decided_at"]
                            )
                            or timestamp
                        )
                    elif job is not None and projected == "running":
                        occurred_at = (
                            _safe_engineering_validation_timestamp(job["started_at"])
                            or timestamp
                        )
                    elif job is not None and projected in {
                        "done",
                        "failed",
                        "cancelled",
                    }:
                        occurred_at = result_finished_at or timestamp
                    self._insert_engineering_task_event_cur(
                        cur,
                        task_id=row["engineering_task_id"],
                        attempt_number=row["attempt_number"],
                        event_key=(
                            f"{transition_prefix}{transition_number}:{journal_state}"
                        ),
                        event_type=f"worker_validation_{journal_state}",
                        phase="validation",
                        state=journal_state,
                        summary=_ENGINEERING_VALIDATION_STATUS_SUMMARIES.get(
                            journal_state,
                            "Worker validation 狀態已更新",
                        ),
                        details={
                            "approval_id": row["approval_id"],
                            "downstream_job_id": row["downstream_job_id"],
                            "previous_state": previous_state,
                            "validation_request_id": validation_request_id,
                        },
                        source_kind=source_kind,
                        source_id=source_id,
                        actor_id=actor_id,
                        occurred_at=occurred_at,
                        recorded_at=timestamp,
                    )
                cur.execute(
                    "SELECT * FROM engineering_validation_requests WHERE id = ?",
                    (validation_request_id,),
                )
                return EngineeringValidationRequest.from_row(cur.fetchone())

        # A continuously changing projection is not an execution failure.  Do
        # not guess or raise from this read path; return the latest durable row
        # and let a later refresh reconcile it.
        return self.get_engineering_validation_request(validation_request_id)

    def list_engineering_task_jobs(
        self, task_id: str, *, attempt_number: Optional[int] = None
    ) -> list[Job]:
        query = "SELECT * FROM jobs WHERE engineering_task_id = ?"
        params: list[Any] = [task_id]
        if attempt_number is not None:
            query += " AND engineering_attempt_number = ?"
            params.append(attempt_number)
        query += " ORDER BY engineering_attempt_number, id"
        with self.cursor() as cur:
            cur.execute(query, params)
            return [Job.from_row(row) for row in cur.fetchall()]

    def list_engineering_task_attempt_runs(self, task_id: str) -> list[CodingRun]:
        with self.cursor() as cur:
            cur.execute(
                """
                SELECT * FROM coding_runs
                WHERE engineering_task_id = ?
                ORDER BY attempt_number, id
                """,
                (task_id,),
            )
            return [CodingRun.from_row(row) for row in cur.fetchall()]

    def update_engineering_task(self, task_id: str, **fields: Any) -> None:
        if not fields:
            return
        invalid = set(fields) - self._ENGINEERING_TASK_UPDATE_FIELDS
        if invalid:
            raise ValueError(f"invalid engineering_task field(s): {sorted(invalid)}")
        fields.setdefault("updated_at", now_iso())
        cols = ", ".join(f"{key} = ?" for key in fields)
        values = list(fields.values()) + [task_id]
        with self._immediate_cursor() as cur:
            previous_status = None
            approval_id: Optional[int] = None
            if "status" in fields:
                cur.execute(
                    "SELECT status, approval_id FROM engineering_tasks WHERE id = ?",
                    (task_id,),
                )
                row = cur.fetchone()
                previous_status = row["status"] if row is not None else None
                approval_id = int(row["approval_id"]) if row is not None and row["approval_id"] is not None else None
            else:
                row = cur.execute(
                    "SELECT approval_id FROM engineering_tasks WHERE id = ?",
                    (task_id,),
                ).fetchone()
                approval_id = int(row["approval_id"]) if row is not None and row["approval_id"] is not None else None
            cur.execute(f"UPDATE engineering_tasks SET {cols} WHERE id = ?", values)
            new_status = fields.get("status")
            if cur.rowcount == 1 and new_status is not None and new_status != previous_status:
                self._insert_engineering_task_event_cur(
                    cur,
                    task_id=task_id,
                    event_type="status_changed",
                    phase=_engineering_phase_for_status(new_status),
                    state=new_status,
                    summary=_engineering_status_summary(new_status),
                    details={"previous_status": previous_status},
                    source_kind="system",
                    event_key=(
                        f"task-status:{previous_status or 'none'}:{new_status}:"
                        f"{fields['updated_at']}"
                    ),
                    occurred_at=fields["updated_at"],
                )
            if cur.rowcount == 1:
                params: dict[str, Any] = {
                    "field_names": sorted(fields),
                    "field_count": len(fields),
                }
                if new_status is not None:
                    params.update(
                        {
                            "previous_status": previous_status,
                            "new_status": new_status,
                        }
                    )
                self.append_durable_audit_event_in_transaction(
                    cur,
                    action="engineering_task_updated",
                    params=params,
                    result="updated",
                    resource_type="engineering_task",
                    resource_id=task_id,
                    approval_id=approval_id,
                    event_id=f"engineering-task:{task_id}:update:{uuid.uuid4()}",
                )

    def reject_engineering_task_approval(
        self,
        *,
        task_id: str,
        approval_id: int,
        note: Optional[str],
        decision_actor_id: Optional[str],
        decision_mechanism: str,
    ) -> None:
        """Atomically reject the approval, parent cache and safe journal fact."""

        timestamp = now_iso()
        with self._immediate_cursor() as cur:
            cur.execute(
                """
                SELECT task.status AS task_status, approval.status AS approval_status
                FROM engineering_tasks AS task
                JOIN approvals AS approval ON approval.id = task.approval_id
                WHERE task.id = ? AND approval.id = ?
                """,
                (task_id, approval_id),
            )
            row = cur.fetchone()
            if row is None:
                raise ValueError("engineering task approval linkage is missing")
            if row["approval_status"] != "pending" or row["task_status"] not in {
                "pending_approval",
                "planning",
            }:
                raise ValueError("engineering task approval is not rejectable")
            cur.execute(
                """
                UPDATE approvals
                SET status = 'rejected', decided_at = ?, note = ?,
                    decision_actor_id = ?, decision_mechanism = ?
                WHERE id = ? AND status = 'pending'
                """,
                (
                    timestamp,
                    note,
                    decision_actor_id,
                    decision_mechanism,
                    approval_id,
                ),
            )
            if cur.rowcount != 1:
                raise ValueError("engineering task approval changed during rejection")
            self._append_approval_decided_audit(
                cur,
                approval_id=approval_id,
                kind="coding_task",
                status="rejected",
                decision_actor_id=decision_actor_id,
                decision_mechanism=decision_mechanism,
            )
            cur.execute(
                """
                UPDATE engineering_tasks
                SET status = 'rejected', updated_at = ?
                WHERE id = ?
                """,
                (timestamp, task_id),
            )
            if cur.rowcount != 1:
                raise ValueError("engineering task changed during rejection")
            self.append_durable_audit_event_in_transaction(
                cur,
                action="engineering_task_updated",
                params={
                    "field_names": ["status", "updated_at"],
                    "field_count": 2,
                    "previous_status": row["task_status"],
                    "new_status": "rejected",
                },
                result="rejected",
                resource_type="engineering_task",
                resource_id=task_id,
                approval_id=approval_id,
                event_id=f"engineering-task:{task_id}:approval:{approval_id}:rejected",
            )
            self._insert_engineering_task_event_cur(
                cur,
                task_id=task_id,
                event_key=f"approval:{approval_id}:rejected",
                event_type="approval_rejected",
                phase="approval",
                state="rejected",
                summary="AI Engineering Task 核准請求已拒絕",
                details={"approval_id": approval_id},
                source_kind="approval",
                source_id=str(approval_id),
                actor_id=decision_actor_id,
                occurred_at=timestamp,
                recorded_at=timestamp,
            )

    def _insert_engineering_task_attempt_rows(
        self,
        cur: sqlite3.Cursor,
        *,
        task_id: str,
        attempt_number: int,
        approval_id: int,
        project: str,
        runner_server: str,
        instruction: str,
        base_commit: str,
        project_version_id: str,
        validation_target: Optional[str],
        worktree_path: str,
        staging_command: str,
        coding_command: str,
        decision_actor_id: Optional[str],
        decision_mechanism: str,
        timestamp: str,
    ) -> tuple[int, int, int]:
        """Insert one attempt's coding_run/jobs/command-journal rows.

        Shared by ``finalize_engineering_task_approval_plan`` (attempt 1, the
        original coding_task approval) and
        ``finalize_engineering_task_retry_plan`` (attempt N>1).  Callers own
        every precondition check; this helper only performs the atomic insert
        shape and must stay an exact transformation of the original attempt-1
        SQL, parameterized by ``attempt_number``.
        """

        cur.execute(
            """
            INSERT INTO coding_runs
                (approval_id, job_id, project, runner_server, instruction,
                 base_branch, base_commit, worktree_path, validation_target,
                 status, engineering_task_id, project_version_id,
                 base_binding, attempt_number, created_at)
            VALUES (?, NULL, ?, ?, ?, NULL, ?, ?, ?, 'queued', ?, ?,
                    'project_version_pinned', ?, ?)
            """,
            (
                approval_id,
                project,
                runner_server,
                instruction,
                base_commit,
                worktree_path,
                validation_target,
                task_id,
                project_version_id,
                attempt_number,
                timestamp,
            ),
        )
        run_id = int(cur.lastrowid)

        cur.execute(
            """
            INSERT INTO jobs
                (type, project, command, pin_server, depends_on, status,
                 priority, created_at, engineering_task_id,
                 engineering_task_role, engineering_attempt_number)
            VALUES ('sync', ?, ?, '_local', '[]', 'queued', 'normal', ?,
                    ?, 'staging', ?)
            """,
            (project, staging_command, timestamp, task_id, attempt_number),
        )
        staging_job_id = int(cur.lastrowid)

        cur.execute(
            """
            INSERT INTO jobs
                (type, project, command, pin_server, depends_on, status,
                 priority, created_at, engineering_task_id,
                 engineering_task_role, engineering_attempt_number)
            VALUES ('coding', ?, ?, ?, ?, 'queued', 'normal', ?,
                    ?, 'coding', ?)
            """,
            (
                project,
                coding_command,
                runner_server,
                json.dumps([staging_job_id]),
                timestamp,
                task_id,
                attempt_number,
            ),
        )
        coding_job_id = int(cur.lastrowid)
        command_rows = (
            (
                task_id,
                attempt_number,
                1,
                "staging-job",
                staging_job_id,
                run_id,
                "staging",
                f"Stage approved ProjectVersion {base_commit[:12]} bundle",
                hashlib.sha256(staging_command.encode("utf-8")).hexdigest(),
                "server_a",
                "Server A",
                "Server A local staging area",
                "immutable_base_staging",
                "task_approved",
                approval_id,
                "job",
                "queued",
                timestamp,
                timestamp,
            ),
            (
                task_id,
                attempt_number,
                2,
                "codex-agent-turn",
                coding_job_id,
                run_id,
                "agent_turn",
                "Codex agent turn in isolated worktree",
                hashlib.sha256(coding_command.encode("utf-8")).hexdigest(),
                "coding_runner",
                runner_server,
                "Isolated task worktree",
                "approved_agent_execution",
                "task_approved",
                approval_id,
                "job",
                "queued",
                timestamp,
                timestamp,
            ),
        )
        cur.executemany(
            """
            INSERT INTO engineering_task_commands
                (engineering_task_id, attempt_number, sequence, command_key,
                 job_id, coding_run_id, command_role, display_command,
                 command_digest, execution_location, target_ref,
                 working_directory_label, policy_family, policy_disposition,
                 approval_id, status_source, recorded_status,
                 created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            command_rows,
        )

        cur.execute(
            "UPDATE coding_runs SET job_id = ? WHERE id = ?",
            (coding_job_id, run_id),
        )
        cur.execute(
            """
            UPDATE engineering_tasks
            SET coding_run_id = ?, status = 'queued', updated_at = ?
            WHERE id = ?
            """,
                (run_id, timestamp, task_id),
        )
        approval_row = cur.execute(
            "SELECT kind FROM approvals WHERE id = ?", (approval_id,)
        ).fetchone()
        materialization_actor_id = (
            decision_actor_id
            if isinstance(decision_actor_id, str) and decision_actor_id
            else "system"
        )
        materialization_actor_kind = self._durable_actor_kind(
            cur,
            materialization_actor_id,
            fallback="system" if materialization_actor_id == "system" else None,
        )
        materialization_authentication = (
            decision_mechanism
            if materialization_actor_id != "system"
            else "system"
        )
        approval_kind = (
            str(approval_row["kind"])
            if approval_row is not None
            else "coding_task"
        )
        for job_id, job_role, dependency_count in (
            (staging_job_id, "staging", 0),
            (coding_job_id, "coding", 1),
        ):
            self.append_durable_audit_event_in_transaction(
                cur,
                action="execution_job_materialized",
                params={
                    "approval_kind": approval_kind,
                    "dependency_count": dependency_count,
                    "graph_size": 2,
                    "job_id": job_id,
                    "job_role": job_role,
                    "engineering_task_id": task_id,
                    "engineering_attempt_number": attempt_number,
                    "pinned_execution": True,
                },
                result="queued",
                actor_id=materialization_actor_id,
                actor_kind=materialization_actor_kind,
                authentication=materialization_authentication,
                resource_type="job",
                resource_id=str(job_id),
                approval_id=approval_id,
                event_id=f"approval:{approval_id}:job:{job_id}",
            )
        self.append_durable_audit_event_in_transaction(
            cur,
            action="engineering_task_updated",
            params={
                "field_names": ["coding_run_id", "status", "updated_at"],
                "field_count": 3,
                "attempt_number": attempt_number,
                "coding_run_id": run_id,
                "status": "queued",
            },
            result="updated",
            resource_type="engineering_task",
            resource_id=task_id,
            approval_id=approval_id,
            event_id=f"engineering-task:{task_id}:attempt:{attempt_number}:queued",
        )

        self._insert_engineering_task_event_cur(
            cur,
            task_id=task_id,
            attempt_number=attempt_number,
            event_key=f"approval:{approval_id}:approved",
            event_type="approval_approved",
            phase="approval",
            state="queued",
            summary="AI Engineering Task 已核准",
            details={"approval_id": approval_id},
            source_kind="approval",
            source_id=str(approval_id),
            actor_id=decision_actor_id,
            occurred_at=timestamp,
            recorded_at=timestamp,
        )
        self._insert_engineering_task_event_cur(
            cur,
            task_id=task_id,
            attempt_number=attempt_number,
            event_key=f"attempt:{attempt_number}:queued:{coding_job_id}",
            event_type="attempt_queued",
            phase="queue",
            state="queued",
            summary="不可變執行計畫已排入佇列",
            details={
                "coding_run_id": run_id,
                "staging_job_id": staging_job_id,
                "coding_job_id": coding_job_id,
            },
            source_kind="coding_run",
            source_id=str(run_id),
            occurred_at=timestamp,
            recorded_at=timestamp,
        )
        return run_id, staging_job_id, coding_job_id

    def finalize_engineering_task_approval_plan(
        self,
        *,
        task_id: str,
        approval_id: int,
        project: str,
        runner_server: str,
        instruction: str,
        base_commit: str,
        project_version_id: str,
        validation_target: Optional[str],
        worktree_path: str,
        staging_command: str,
        coding_command: str,
        approval_note: Optional[str],
        decision_actor_id: Optional[str],
        decision_mechanism: str,
    ) -> tuple[int, int, int]:
        """Atomically approve and publish a complete immutable execution plan.

        No scheduler-visible owner Job may exist while the approval is pending.
        A process crash therefore leaves either the original pending request and
        no execution rows, or an approved task with its run, dependency edge and
        both Jobs fully linked.  SQLite rolls every intermediate insert back.
        """

        timestamp = now_iso()
        with self._immediate_cursor() as cur:
            cur.execute("SELECT * FROM approvals WHERE id = ?", (approval_id,))
            approval_row = cur.fetchone()
            if (
                approval_row is None
                or approval_row["kind"] != "coding_task"
                or approval_row["status"] != "pending"
            ):
                raise ValueError("engineering task approval is not pending")

            cur.execute("SELECT * FROM engineering_tasks WHERE id = ?", (task_id,))
            task_row = cur.fetchone()
            if (
                task_row is None
                or task_row["approval_id"] != approval_id
                or task_row["status"] != "pending_approval"
                or task_row["project_name"] != project
                or task_row["runner_server"] != runner_server
                or task_row["project_version_id"] != project_version_id
                or task_row["base_commit"].lower() != base_commit.lower()
                or task_row["instruction"] != instruction
            ):
                raise ValueError("engineering task contract is not finalizable")

            # Partial owner rows can only come from an older/broken planner.
            # Do not adopt them: they may already have been observed by a
            # scheduler and cannot be proven equivalent to this atomic plan.
            cur.execute(
                "SELECT 1 FROM coding_runs WHERE engineering_task_id = ? LIMIT 1",
                (task_id,),
            )
            if cur.fetchone() is not None:
                raise ValueError("engineering task already has a partial coding run")
            cur.execute(
                "SELECT 1 FROM jobs WHERE engineering_task_id = ? LIMIT 1",
                (task_id,),
            )
            if cur.fetchone() is not None:
                raise ValueError("engineering task already has partial jobs")

            run_id, staging_job_id, coding_job_id = (
                self._insert_engineering_task_attempt_rows(
                    cur,
                    task_id=task_id,
                    attempt_number=1,
                    approval_id=approval_id,
                    project=project,
                    runner_server=runner_server,
                    instruction=instruction,
                    base_commit=base_commit,
                    project_version_id=project_version_id,
                    validation_target=validation_target,
                    worktree_path=worktree_path,
                    staging_command=staging_command,
                    coding_command=coding_command,
                    decision_actor_id=decision_actor_id,
                    decision_mechanism=decision_mechanism,
                    timestamp=timestamp,
                )
            )
            final_note = approval_note or (
                f"已建立 immutable coding 任務 #{coding_job_id}（Runner "
                f"{runner_server}，coding_run #{run_id}，staging Job "
                f"#{staging_job_id}）"
            )

            cur.execute(
                """
                UPDATE approvals
                SET status = 'approved', decided_at = ?, note = ?,
                    decision_actor_id = ?, decision_mechanism = ?
                WHERE id = ? AND status = 'pending'
                """,
                (
                    timestamp,
                    final_note,
                    decision_actor_id,
                    decision_mechanism,
                    approval_id,
                ),
            )
            if cur.rowcount != 1:
                raise ValueError("engineering task approval changed during finalization")
            self._append_approval_decided_audit(
                cur,
                approval_id=approval_id,
                kind=str(approval_row["kind"]),
                status="approved",
                decision_actor_id=decision_actor_id,
                decision_mechanism=decision_mechanism,
            )

        return run_id, staging_job_id, coding_job_id

    def finalize_engineering_task_retry_plan(
        self,
        *,
        task_id: str,
        approval_id: int,
        attempt_number: int,
        project: str,
        runner_server: str,
        instruction: str,
        base_commit: str,
        project_version_id: str,
        validation_target: Optional[str],
        worktree_path: str,
        staging_command: str,
        coding_command: str,
        approval_note: Optional[str],
        decision_actor_id: Optional[str],
        decision_mechanism: str,
    ) -> tuple[int, int, int]:
        """Atomically approve an ``engineering_task_retry`` and publish attempt N.

        Mirrors ``finalize_engineering_task_approval_plan`` (attempt 1's atomic
        plan builder) but scopes the "no partial owner rows" guard to this
        exact ``(task_id, attempt_number)`` pair instead of the whole task, so
        a prior terminal attempt does not block a later one.  The caller
        already re-validated the retry contract against current DB/config
        state; this method re-checks only what a concurrent writer could have
        changed since that revalidation.
        """

        if attempt_number < 2:
            raise ValueError("engineering task retry must target attempt_number >= 2")
        timestamp = now_iso()
        with self._immediate_cursor() as cur:
            cur.execute("SELECT * FROM approvals WHERE id = ?", (approval_id,))
            approval_row = cur.fetchone()
            if (
                approval_row is None
                or approval_row["kind"] != "engineering_task_retry"
                or approval_row["status"] != "pending"
            ):
                raise ValueError("engineering task retry approval is not pending")

            cur.execute("SELECT * FROM engineering_tasks WHERE id = ?", (task_id,))
            task_row = cur.fetchone()
            if (
                task_row is None
                or task_row["project_name"] != project
                or task_row["runner_server"] != runner_server
                or task_row["project_version_id"] != project_version_id
                or task_row["base_commit"].lower() != base_commit.lower()
                or task_row["instruction"] != instruction
                or task_row["status"] not in _CODING_RUN_TERMINAL_STATUSES
            ):
                raise ValueError("engineering task retry contract is not finalizable")

            # Scoped by (task_id, attempt_number): unlike the attempt-1 planner,
            # earlier terminal attempts are expected to already have rows.
            cur.execute(
                """
                SELECT 1 FROM coding_runs
                WHERE engineering_task_id = ? AND attempt_number = ? LIMIT 1
                """,
                (task_id, attempt_number),
            )
            if cur.fetchone() is not None:
                raise ValueError("engineering task already has this attempt's coding run")
            cur.execute(
                """
                SELECT 1 FROM jobs
                WHERE engineering_task_id = ? AND engineering_attempt_number = ? LIMIT 1
                """,
                (task_id, attempt_number),
            )
            if cur.fetchone() is not None:
                raise ValueError("engineering task already has this attempt's jobs")

            run_id, staging_job_id, coding_job_id = (
                self._insert_engineering_task_attempt_rows(
                    cur,
                    task_id=task_id,
                    attempt_number=attempt_number,
                    approval_id=approval_id,
                    project=project,
                    runner_server=runner_server,
                    instruction=instruction,
                    base_commit=base_commit,
                    project_version_id=project_version_id,
                    validation_target=validation_target,
                    worktree_path=worktree_path,
                    staging_command=staging_command,
                    coding_command=coding_command,
                    decision_actor_id=decision_actor_id,
                    decision_mechanism=decision_mechanism,
                    timestamp=timestamp,
                )
            )
            final_note = approval_note or (
                f"已核准 attempt #{attempt_number} retry：coding 任務 "
                f"#{coding_job_id}（Runner {runner_server}，coding_run #{run_id}，"
                f"staging Job #{staging_job_id}）"
            )
            cur.execute(
                """
                UPDATE approvals
                SET status = 'approved', decided_at = ?, note = ?,
                    decision_actor_id = ?, decision_mechanism = ?
                WHERE id = ? AND status = 'pending'
                """,
                (
                    timestamp,
                    final_note,
                    decision_actor_id,
                    decision_mechanism,
                    approval_id,
                ),
            )
            if cur.rowcount != 1:
                raise ValueError(
                    "engineering task retry approval changed during finalization"
                )
            self._append_approval_decided_audit(
                cur,
                approval_id=approval_id,
                kind=str(approval_row["kind"]),
                status="approved",
                decision_actor_id=decision_actor_id,
                decision_mechanism=decision_mechanism,
            )
            self.append_durable_audit_event_in_transaction(
                cur,
                action="engineering_task_retry_recorded",
                params={
                    "attempt_number": attempt_number,
                    "coding_run_id": run_id,
                    "staging_job_id": staging_job_id,
                    "coding_job_id": coding_job_id,
                },
                result="approved",
                resource_type="engineering_task",
                resource_id=task_id,
                approval_id=approval_id,
                event_id=f"engineering-task:{task_id}:retry:{attempt_number}",
            )

        return run_id, staging_job_id, coding_job_id

    def finalize_engineering_task_discard(
        self,
        *,
        task_id: str,
        approval_id: int,
        note: str,
        decision_actor_id: Optional[str],
        decision_mechanism: str,
    ) -> None:
        """Atomically approve a discard and publish its durable task evidence."""

        timestamp = now_iso()
        with self._immediate_cursor() as cur:
            cur.execute(
                """
                SELECT status AS approval_status, kind AS approval_kind
                FROM approvals
                WHERE id = ?
                """,
                (approval_id,),
            )
            row = cur.fetchone()
            if row is None:
                raise ValueError("engineering task discard approval linkage is missing")
            if (
                row["approval_kind"] != "engineering_task_discard"
                or row["approval_status"] != "pending"
            ):
                raise ValueError("engineering task discard approval is not finalizable")
            task_row = cur.execute(
                "SELECT status FROM engineering_tasks WHERE id = ?",
                (task_id,),
            ).fetchone()
            if task_row is None:
                raise ValueError("engineering task discard target is missing")
            if task_row["status"] not in _CODING_RUN_TERMINAL_STATUSES:
                raise ValueError("engineering task discard target is not terminal")
            cur.execute(
                """
                SELECT 1 FROM jobs
                WHERE engineering_task_id = ?
                  AND status IN ('queued', 'running')
                LIMIT 1
                """,
                (task_id,),
            )
            if cur.fetchone() is not None:
                raise ValueError("engineering task discard has active owner jobs")

            self.update_engineering_task(
                task_id,
                status="discarded",
                updated_at=timestamp,
            )
            self.update_approval(
                approval_id,
                status="approved",
                decided_at=timestamp,
                note=note,
                decision_actor_id=decision_actor_id,
                decision_mechanism=decision_mechanism,
            )
            self.append_durable_audit_event_in_transaction(
                cur,
                action="engineering_task_discarded",
                params={"approval_id": approval_id},
                result="approved",
                resource_type="engineering_task",
                resource_id=task_id,
                approval_id=approval_id,
                event_id=f"engineering-task:{task_id}:discard:{approval_id}",
            )
            self._insert_engineering_task_event_cur(
                cur,
                task_id=task_id,
                attempt_number=None,
                event_key=f"approval:{approval_id}:discarded",
                event_type="task_discarded",
                phase="approval",
                state="discarded",
                source_kind="approval",
                source_id=str(approval_id),
                summary="AI Engineering Task 已標記作廢；結果與 artifact 視同 withheld",
                details={"approval_id": approval_id},
                actor_id=decision_actor_id,
                occurred_at=timestamp,
                recorded_at=timestamp,
            )

    def engineering_task_job_is_approved(self, job: Job) -> bool:
        """Owner Jobs are dispatchable only after their parent approval commits."""

        if job.engineering_task_id is None:
            return True
        with self.cursor() as cur:
            cur.execute(
                """
                SELECT 1
                FROM engineering_tasks AS task
                JOIN approvals AS approval ON approval.id = task.approval_id
                WHERE task.id = ? AND approval.status = 'approved'
                """,
                (job.engineering_task_id,),
            )
            return cur.fetchone() is not None

    def execution_job_approval_is_approved(self, job: Job) -> bool:
        """Every pinned execution Job waits for its approval to commit.

        This is deliberately broader than the Engineering Task compatibility
        guard.  A plan/materialization crash must never leave a queued Job that
        a legacy scheduler can dispatch while its approval is still pending.
        Unpinned legacy Jobs retain their existing behavior.
        """
        if job.execution_approval_id is None:
            return True
        with self.cursor() as cur:
            cur.execute(
                """
                SELECT 1 FROM approvals
                WHERE id = ? AND status = 'approved'
                """,
                (job.execution_approval_id,),
            )
            return cur.fetchone() is not None

    def refresh_engineering_task_status_from_jobs(self, task_id: str) -> Optional[str]:
        """Derive the parent status from its durable staging/coding owner Jobs."""

        task = self.get_engineering_task(task_id)
        if task is None or task.status == "rejected":
            return task.status if task is not None else None
        staging = self.get_engineering_task_job(task_id, "staging", 1)
        coding = self.get_engineering_task_job(task_id, "coding", 1)
        if staging is None or coding is None:
            return task.status

        if staging.status not in VALID_STATUSES or coding.status not in VALID_STATUSES:
            status = "unknown"
        elif staging.status == "running":
            status = "staging"
        elif staging.status in {"failed", "blocked"}:
            status = "staging_failed" if staging.status == "failed" else "blocked"
        elif staging.status == "cancelled":
            status = "cancelled"
        elif staging.status != "done":
            status = "queued"
        elif coding.status == "running":
            status = "running"
        elif coding.status == "done":
            status = "finalizing"
        elif coding.status in {"failed", "blocked", "cancelled"}:
            status = coding.status
        else:
            status = "queued"

        if task.status != status:
            self.update_engineering_task(task_id, status=status)
        return status

    # ---- datasets CRUD（階段 3）------------------------------------------

    @staticmethod
    def _dataset_audit_actor_kwargs(
        audit_actor: AuditActor | None,
    ) -> dict[str, str]:
        """Project a request actor onto the narrow durable audit envelope."""

        if audit_actor is None:
            return {}
        return {
            "actor_id": audit_actor.id,
            "actor_kind": audit_actor.kind,
            "authentication": audit_actor.authentication,
        }

    def _append_dataset_audit_event(
        self,
        cursor: sqlite3.Cursor,
        *,
        action: str,
        result: str,
        resource_id: str,
        params: dict[str, Any],
        event_id: str,
        audit_actor: AuditActor | None = None,
    ) -> None:
        """Append a dataset registry/cache event inside its write transaction.

        Dataset rows contain source paths, manifests, and card text.  The
        durable envelope intentionally carries only identifiers, counts, and
        digests; the reviewed row remains the source of truth and is never
        copied into the audit ledger.
        """

        self.append_durable_audit_event_in_transaction(
            cursor,
            action=action,
            params=params,
            result=result,
            resource_type="dataset",
            resource_id=resource_id,
            event_id=event_id,
            **self._dataset_audit_actor_kwargs(audit_actor),
        )

    def insert_dataset(
        self,
        name: str,
        version: str,
        size_bytes: int,
        source_path: str,
        manifest: dict,
        card: Optional[dict] = None,
        sync_mode: str = "packed",
        audit_actor: AuditActor | None = None,
    ) -> None:
        """同一個 (name, version) 重複註冊會丟 sqlite3.IntegrityError，呼叫端轉
        400——版本是一級概念（原規格 5.2），要更新內容請註冊新版本，不是覆蓋。

        階段 16（PLAN.md Q 節）：`card` 選填（`None` = 沒有資料卡，見
        `app/datasets.py` 的 `build_dataset_card()`）；`sync_mode` 選填，
        預設 `'packed'`（Q.1），本批只存取欄位、不使用其邏輯（見 Dataset
        dataclass 的欄位註解）。
        """
        with self._immediate_cursor() as cur:
            cur.execute(
                """
                INSERT INTO datasets
                    (name, version, size_bytes, source_path, manifest, created_at, card, sync_mode)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    name,
                    version,
                    size_bytes,
                    source_path,
                    json.dumps(manifest),
                    now_iso(),
                    json.dumps(card) if card is not None else None,
                    sync_mode,
                ),
            )
            self._append_dataset_audit_event(
                cur,
                action="dataset_created",
                result="created",
                resource_id=f"{name}@{version}",
                params={
                    "dataset": name,
                    "version": version,
                    "size_bytes": int(size_bytes),
                    "sync_mode": sync_mode,
                },
                event_id=f"dataset:{name}:{version}:created",
                audit_actor=audit_actor,
            )

    def get_dataset(self, name: str, version: str) -> Optional[Dataset]:
        with self.cursor() as cur:
            cur.execute(
                "SELECT * FROM datasets WHERE name = ? AND version = ?", (name, version)
            )
            row = cur.fetchone()
            return Dataset.from_row(row) if row else None

    def list_datasets(self) -> list[Dataset]:
        with self.cursor() as cur:
            cur.execute("SELECT * FROM datasets ORDER BY name ASC, version ASC")
            return [Dataset.from_row(r) for r in cur.fetchall()]

    # ---- immutable dataset snapshots (DG-DATASET-SNAPSHOT-v1) ---------

    def get_dataset_snapshot(self, snapshot_id: str) -> Optional[DatasetSnapshot]:
        with self.cursor() as cur:
            cur.execute("SELECT * FROM dataset_snapshots WHERE id = ?", (snapshot_id,))
            row = cur.fetchone()
            return DatasetSnapshot.from_row(row) if row else None

    def list_dataset_snapshots(
        self,
        *,
        dataset_name: Optional[str] = None,
        dataset_version: Optional[str] = None,
        state: Optional[str] = None,
    ) -> list[DatasetSnapshot]:
        query = "SELECT * FROM dataset_snapshots WHERE 1 = 1"
        params: list[Any] = []
        if dataset_name is not None:
            query += " AND dataset_name = ?"
            params.append(dataset_name)
        if dataset_version is not None:
            query += " AND dataset_version = ?"
            params.append(dataset_version)
        if state is not None:
            query += " AND state = ?"
            params.append(state)
        query += " ORDER BY created_at ASC, id ASC"
        with self.cursor() as cur:
            cur.execute(query, params)
            return [DatasetSnapshot.from_row(row) for row in cur.fetchall()]

    def get_dataset_snapshot_shards(self, snapshot_id: str) -> list[dict[str, Any]]:
        with self.cursor() as cur:
            cur.execute(
                """
                SELECT shard_index, shard_sha256, shard_bytes, file_count
                FROM dataset_snapshot_shards
                WHERE snapshot_id = ?
                ORDER BY shard_index ASC
                """,
                (snapshot_id,),
            )
            return [dict(row) for row in cur.fetchall()]

    def begin_dataset_snapshot_build(
        self,
        *,
        snapshot_id: str,
        approval_id: int,
        payload: dict[str, Any],
        decision_actor_id: Optional[str] = None,
        decision_mechanism: str = "human",
        approval_note: Optional[str] = None,
    ) -> DatasetSnapshot:
        """Atomically approve a snapshot contract and create its build row.

        The approval payload and the current registry row are checked inside the
        same transaction as the status transition.  A crash therefore leaves
        either a pending approval with no snapshot, or an approved approval
        with exactly one ``building`` snapshot—never a half-authorized build.
        """

        if not isinstance(snapshot_id, str) or not snapshot_id.strip():
            raise ValueError("snapshot_id is required")
        if not isinstance(payload, dict):
            raise ValueError("dataset snapshot payload is malformed")
        expected_digest = utf8_sha256(canonical_json(payload))
        with self._immediate_cursor() as cur:
            cur.execute("SELECT * FROM approvals WHERE id = ?", (approval_id,))
            approval = cur.fetchone()
            if approval is None:
                raise ValueError("snapshot build approval not found")
            if approval["status"] != "pending":
                raise ValueError("snapshot build approval is no longer pending")
            if approval["kind"] != "dataset_snapshot_build":
                raise ValueError("approval kind mismatch")
            if approval["payload_contract_version"] != "dataset-snapshot-build-v1":
                raise ValueError("snapshot build contract version mismatch")
            if approval["payload_sha256"] != expected_digest:
                raise ValueError("snapshot build approval payload drifted")
            if canonical_json(json.loads(approval["payload"] or "{}")) != canonical_json(
                payload
            ):
                raise ValueError("snapshot build approval payload drifted")

            cur.execute(
                "SELECT * FROM datasets WHERE name = ? AND version = ?",
                (payload.get("dataset_name"), payload.get("dataset_version")),
            )
            dataset = cur.fetchone()
            if dataset is None:
                raise ValueError("dataset registry row no longer exists")
            if dataset["source_path"] != payload.get("source_path"):
                raise ValueError("dataset source path drifted")

            cur.execute("SELECT 1 FROM dataset_snapshots WHERE id = ?", (snapshot_id,))
            if cur.fetchone() is not None:
                raise ValueError("dataset snapshot id already exists")

            # One source candidate has one active/published winner.  This is a
            # database transaction guard rather than an in-memory lock, so two
            # approval workers racing on separate connections cannot create
            # interleaved staging/published rows for the same reviewed bytes.
            cur.execute(
                """
                SELECT id, state
                FROM dataset_snapshots
                WHERE dataset_name = ? AND dataset_version = ?
                  AND source_candidate_digest = ?
                  AND state IN ('building', 'published')
                ORDER BY created_at ASC, id ASC
                LIMIT 1
                """,
                (
                    payload["dataset_name"],
                    payload["dataset_version"],
                    payload["source_candidate_digest"],
                ),
            )
            existing = cur.fetchone()
            if existing is not None:
                raise ValueError(
                    "dataset snapshot build already has a winner: "
                    f"{existing['id']} ({existing['state']})"
                )

            timestamp = self._sqlite_now(cur)
            cur.execute(
                """
                INSERT INTO dataset_snapshots
                    (id, dataset_name, dataset_version, state,
                     source_candidate_digest, store_revision, shard_policy_json,
                     build_approval_id, created_at)
                VALUES (?, ?, ?, 'building', ?, ?, ?, ?, ?)
                """,
                (
                    snapshot_id,
                    payload["dataset_name"],
                    payload["dataset_version"],
                    payload["source_candidate_digest"],
                    payload["store_revision"],
                    canonical_json(payload["shard_policy"]),
                    approval_id,
                    timestamp,
                ),
            )
            cur.execute(
                """
                UPDATE approvals
                SET status = 'approved', decided_at = ?, note = ?,
                    decision_actor_id = ?, decision_mechanism = ?
                WHERE id = ? AND status = 'pending'
                """,
                (
                    timestamp,
                    approval_note,
                    decision_actor_id,
                    decision_mechanism,
                    approval_id,
                ),
            )
            if cur.rowcount != 1:
                raise ValueError("snapshot build approval changed during finalization")
            self._append_approval_decided_audit(
                cur,
                approval_id=approval_id,
                kind=str(approval["kind"]),
                status="approved",
                decision_actor_id=decision_actor_id,
                decision_mechanism=decision_mechanism,
            )
            cur.execute("SELECT * FROM dataset_snapshots WHERE id = ?", (snapshot_id,))
            row = cur.fetchone()
            if row is None:  # pragma: no cover - guarded by the INSERT above
                raise ValueError("dataset snapshot insert failed")
            return DatasetSnapshot.from_row(row)

    def complete_dataset_snapshot_publish(
        self,
        *,
        snapshot_id: str,
        manifest_digest: str,
        manifest_path: str,
        descriptor_path: str,
        file_count: int,
        total_bytes: int,
        shards: list[dict[str, Any]],
    ) -> DatasetSnapshot:
        """Commit publication metadata and shard evidence in one transaction."""

        if not manifest_digest or not manifest_path or not descriptor_path:
            raise ValueError("published snapshot metadata is incomplete")
        if file_count < 0 or total_bytes < 0:
            raise ValueError("published snapshot sizes are invalid")
        with self._immediate_cursor() as cur:
            cur.execute("SELECT * FROM dataset_snapshots WHERE id = ?", (snapshot_id,))
            row = cur.fetchone()
            if row is None:
                raise ValueError("dataset snapshot not found")
            if row["state"] != "building":
                raise ValueError("dataset snapshot is not building")
            for shard in shards:
                cur.execute(
                    """
                    INSERT INTO dataset_snapshot_shards
                        (snapshot_id, shard_index, shard_sha256, shard_bytes, file_count)
                    VALUES (?, ?, ?, ?, ?)
                    """,
                    (
                        snapshot_id,
                        int(shard["index"]),
                        str(shard["sha256"]),
                        int(shard["size"]),
                        int(shard["file_count"]),
                    ),
                )
            published_at = self._sqlite_now(cur)
            cur.execute(
                """
                UPDATE dataset_snapshots
                SET state = 'published', manifest_digest = ?, manifest_path = ?,
                    descriptor_path = ?, file_count = ?, total_bytes = ?,
                    published_at = ?, last_error_category = NULL,
                    sanitized_error_detail = NULL
                WHERE id = ? AND state = 'building'
                """,
                (
                    manifest_digest,
                    manifest_path,
                    descriptor_path,
                    file_count,
                    total_bytes,
                    published_at,
                    snapshot_id,
                ),
            )
            if cur.rowcount != 1:
                raise ValueError("dataset snapshot publication claim conflict")
            self.append_durable_audit_event_in_transaction(
                cur,
                action="project_snapshot_published",
                params={
                    "dataset_name": row["dataset_name"],
                    "dataset_version": row["dataset_version"],
                    "file_count": int(file_count),
                    "total_bytes": int(total_bytes),
                    "shard_count": len(shards),
                    "manifest_digest": manifest_digest,
                },
                result="published",
                resource_type="dataset_snapshot",
                resource_id=snapshot_id,
                approval_id=row["build_approval_id"],
                event_id=f"dataset-snapshot:{snapshot_id}:published",
            )
            cur.execute("SELECT * FROM dataset_snapshots WHERE id = ?", (snapshot_id,))
            return DatasetSnapshot.from_row(cur.fetchone())

    def fail_dataset_snapshot_build(
        self,
        *,
        snapshot_id: str,
        state: str,
        last_error_category: str,
        sanitized_error_detail: str,
    ) -> DatasetSnapshot:
        """Record a failed/unknown build without mutating published evidence."""

        if state not in {"aborted", "verification_unknown"}:
            raise ValueError("invalid dataset snapshot failure state")
        detail = (sanitized_error_detail or "")[:500]
        with self._immediate_cursor() as cur:
            cur.execute("SELECT * FROM dataset_snapshots WHERE id = ?", (snapshot_id,))
            row = cur.fetchone()
            if row is None:
                raise ValueError("dataset snapshot not found")
            if row["state"] != "building":
                raise ValueError("dataset snapshot is not building")
            cur.execute(
                """
                UPDATE dataset_snapshots
                SET state = ?, last_error_category = ?, sanitized_error_detail = ?
                WHERE id = ? AND state = 'building'
                """,
                (state, last_error_category, detail, snapshot_id),
            )
            if cur.rowcount != 1:
                raise ValueError("dataset snapshot failure claim conflict")
            self.append_durable_audit_event_in_transaction(
                cur,
                action="project_snapshot_published",
                params={
                    "dataset_name": row["dataset_name"],
                    "dataset_version": row["dataset_version"],
                    "failure_state": state,
                },
                result=state,
                resource_type="dataset_snapshot",
                resource_id=snapshot_id,
                approval_id=row["build_approval_id"],
                event_id=f"dataset-snapshot:{snapshot_id}:{state}",
            )
            cur.execute("SELECT * FROM dataset_snapshots WHERE id = ?", (snapshot_id,))
            return DatasetSnapshot.from_row(cur.fetchone())

    def update_dataset_card(
        self,
        name: str,
        version: str,
        card: dict,
        audit_actor: AuditActor | None = None,
    ) -> None:
        """階段 16（PLAN.md Q.3）：整份 card dict 覆蓋寫入（不是逐欄
        UPDATE）——呼叫端（`app/main.py` 的 PATCH
        `/datasets/{name}/{version}/card`）負責組出完整的新 card（含保留
        原 `created_at`、更新 `updated_at`），這裡只管寫入序列化後的
        JSON。呼叫端應先 `get_dataset()` 確認資料集存在（同既有 CRUD
        慣例，這裡不檢查、不報錯，資料集不存在時是 no-op）。"""
        with self._immediate_cursor() as cur:
            cur.execute(
                "UPDATE datasets SET card = ? WHERE name = ? AND version = ?",
                (json.dumps(card), name, version),
            )
            if cur.rowcount == 1:
                card_sha256 = utf8_sha256(canonical_json(card))
                self._append_dataset_audit_event(
                    cur,
                    action="dataset_updated",
                    result="updated",
                    resource_id=f"{name}@{version}",
                    params={
                        "dataset": name,
                        "version": version,
                    },
                    event_id=f"dataset:{name}:{version}:card:{card_sha256}",
                    audit_actor=audit_actor,
                )

    def finalize_dataset_sync_verification(
        self,
        job_id: int,
        *,
        job_status: str,
        finished_at: str,
        exit_code: Optional[int],
        log_tail: Optional[str],
        outcome: str,
        reason_code: str,
        server: Optional[str],
        dataset: Optional[str],
        version: Optional[str],
        remote_file_count: Optional[int] = None,
        remote_total_size: Optional[int] = None,
        audit_actor: AuditActor | None = None,
    ) -> None:
        """Commit a sync verification result, cache update, and audit event.

        The local rsync Job is the canonical execution record.  Verification
        used to update that row, update ``dataset_cache``, and append a JSONL
        summary in three independent steps.  Keeping the terminal observation,
        cache eligibility, and durable audit envelope in one immediate
        transaction prevents a cache entry from surviving a missing or
        conflicting verification event (and makes retries idempotent).

        ``reason_code`` is deliberately an enum rather than a free-form SSH
        exception or manifest text.  The detailed log remains in the Job row,
        where the existing engineering-task redaction policy applies.
        """

        if job_status not in VALID_STATUSES:
            raise ValueError(f"invalid job status: {job_status}")
        if outcome not in DATASET_SYNC_VERIFICATION_OUTCOMES:
            raise ValueError(f"invalid dataset sync verification outcome: {outcome}")
        if reason_code not in DATASET_SYNC_VERIFICATION_REASONS:
            raise ValueError(f"invalid dataset sync verification reason: {reason_code}")
        if not isinstance(job_id, int) or isinstance(job_id, bool) or job_id <= 0:
            raise ValueError("job_id must be a positive integer")
        for field_name, value in (
            ("remote_file_count", remote_file_count),
            ("remote_total_size", remote_total_size),
        ):
            if value is not None and (
                not isinstance(value, int) or isinstance(value, bool) or value < 0
            ):
                raise ValueError(f"{field_name} must be a non-negative integer")
        if outcome == "verified" and not (server and dataset and version):
            raise ValueError("verified sync result requires server and dataset identity")

        params: dict[str, Any] = {
            "job_id": job_id,
            "server": server,
            "dataset": dataset,
            "version": version,
            "reason_code": reason_code,
        }
        if remote_file_count is not None:
            params["remote_file_count"] = remote_file_count
        if remote_total_size is not None:
            params["remote_total_size"] = remote_total_size

        with self._immediate_cursor() as cur:
            if cur.execute("SELECT 1 FROM jobs WHERE id = ?", (job_id,)).fetchone() is None:
                raise ValueError(f"job not found: {job_id}")
            self.update_job(
                job_id,
                status=job_status,
                finished_at=finished_at,
                exit_code=exit_code,
                log_tail=log_tail,
            )
            if outcome == "verified":
                # The identity check above makes these values non-None for
                # type checkers and guards future callers that bypass it.
                assert server is not None
                assert dataset is not None
                assert version is not None
                self.upsert_dataset_cache(
                    server,
                    dataset,
                    version,
                    audit_actor=audit_actor,
                )
            self.append_durable_audit_event_in_transaction(
                cur,
                action="dataset_sync_verification_recorded",
                params=params,
                result=outcome,
                resource_type="job",
                resource_id=str(job_id),
                event_id=f"dataset-sync:{job_id}:verification:{outcome}",
                **self._dataset_audit_actor_kwargs(audit_actor),
            )

    # ---- dataset_cache CRUD（階段 3：快取地圖）----------------------------

    def upsert_dataset_cache(
        self,
        server: str,
        dataset: str,
        version: str,
        audit_actor: AuditActor | None = None,
    ) -> None:
        with self._immediate_cursor() as cur:
            cur.execute(
                "SELECT 1 FROM dataset_cache "
                "WHERE server = ? AND dataset = ? AND version = ?",
                (server, dataset, version),
            )
            existed = cur.fetchone() is not None
            cur.execute(
                """
                INSERT INTO dataset_cache (server, dataset, version, registered_at)
                VALUES (?, ?, ?, ?)
                ON CONFLICT(server, dataset, version)
                DO UPDATE SET registered_at = excluded.registered_at
                """,
                (server, dataset, version, now_iso()),
            )
            if not existed:
                self._append_dataset_audit_event(
                    cur,
                    action="dataset_cache_added",
                    result="cached",
                    resource_id=f"{dataset}@{version}",
                    params={
                        "dataset": dataset,
                        "version": version,
                        "server": server,
                    },
                    event_id=f"dataset-cache:{server}:{dataset}:{version}:added",
                    audit_actor=audit_actor,
                )

    def delete_dataset_cache(
        self,
        server: str,
        dataset: str,
        version: str,
        audit_actor: AuditActor | None = None,
    ) -> None:
        with self._immediate_cursor() as cur:
            cur.execute(
                "DELETE FROM dataset_cache WHERE server = ? AND dataset = ? AND version = ?",
                (server, dataset, version),
            )
            if cur.rowcount == 1:
                self._append_dataset_audit_event(
                    cur,
                    action="dataset_cache_removed",
                    result="removed",
                    resource_id=f"{dataset}@{version}",
                    params={
                        "dataset": dataset,
                        "version": version,
                        "server": server,
                    },
                    event_id=f"dataset-cache:{server}:{dataset}:{version}:removed",
                    audit_actor=audit_actor,
                )

    def reconcile_dataset_cache(
        self,
        server: str,
        found: list[tuple[str, str]],
        audit_actor: AuditActor | None = None,
    ) -> tuple[set[tuple[str, str]], set[tuple[str, str]]]:
        """Reconcile one server's observed cache in a single DB UoW.

        The scheduler receives one read-only directory observation from a
        remote server.  Previously each add/remove used a separate transaction
        and the loop appended a JSONL summary afterwards, so a crash could
        leave a partial cache map with no bounded operation evidence.  Direct
        cache CRUD remains unchanged; this method joins all row events and a
        count-only reconcile event under one immediate transaction.
        """

        if not isinstance(server, str) or not server:
            raise ValueError("dataset cache server is required")
        found_set = set(found)
        with self._immediate_cursor() as cur:
            rows = cur.execute(
                "SELECT dataset, version FROM dataset_cache WHERE server = ?",
                (server,),
            ).fetchall()
            existing_set = {(row["dataset"], row["version"]) for row in rows}
            to_add = found_set - existing_set
            to_remove = existing_set - found_set

            for name, version in sorted(to_add):
                self.upsert_dataset_cache(
                    server,
                    name,
                    version,
                    audit_actor=audit_actor,
                )
            for name, version in sorted(to_remove):
                self.delete_dataset_cache(
                    server,
                    name,
                    version,
                    audit_actor=audit_actor,
                )

            if to_add or to_remove:
                reconcile_digest = utf8_sha256(
                    canonical_json(
                        {
                            "server": server,
                            "added": [list(item) for item in sorted(to_add)],
                            "removed": [list(item) for item in sorted(to_remove)],
                        }
                    )
                )
                self.append_durable_audit_event_in_transaction(
                    cur,
                    action="dataset_cache_reconciled",
                    params={
                        "server": server,
                        "added_count": len(to_add),
                        "removed_count": len(to_remove),
                    },
                    result="reconciled",
                    resource_type="dataset_cache",
                    resource_id=server,
                    event_id=f"dataset-cache-reconcile:{server}:{reconcile_digest}",
                    **self._dataset_audit_actor_kwargs(audit_actor),
                )
            return to_add, to_remove

    def is_dataset_cached(self, server: str, dataset: str, version: str) -> bool:
        with self.cursor() as cur:
            cur.execute(
                """
                SELECT 1 FROM dataset_cache
                WHERE server = ? AND dataset = ? AND version = ? LIMIT 1
                """,
                (server, dataset, version),
            )
            return cur.fetchone() is not None

    def is_dataset_cached_anywhere(self, dataset: str, version: str) -> bool:
        """某個資料集＠版本是否已經同步到**任何一台**機器（不指定 server）。
        「自動」派工模式下用來判斷：這個訓練任務需要的資料集哪台機器都
        沒有，會提醒使用者（見 `app/approvals.py` 的 warning 機制），
        因為 `has_dataset` 資格過濾之後這種任務會一直卡在 queued。"""
        with self.cursor() as cur:
            cur.execute(
                "SELECT 1 FROM dataset_cache WHERE dataset = ? AND version = ? LIMIT 1",
                (dataset, version),
            )
            return cur.fetchone() is not None

    def list_dataset_cache(self, server: Optional[str] = None) -> list[DatasetCacheEntry]:
        with self.cursor() as cur:
            if server:
                cur.execute(
                    "SELECT * FROM dataset_cache WHERE server = ? ORDER BY dataset ASC, version ASC",
                    (server,),
                )
            else:
                cur.execute("SELECT * FROM dataset_cache ORDER BY server ASC, dataset ASC")
            return [DatasetCacheEntry.from_row(r) for r in cur.fetchall()]

    # ---- 輔助查詢：setup 任務是否已在某機完成過（階段 3）--------------------

    def has_completed_setup(self, project: str, server: str) -> bool:
        """某機是否已經成功跑過某專案的 setup 任務（type='setup' 且 status='done'）。

        用既有 `jobs` 表歷史紀錄判斷「機器是否已經跑過這個專案」，取代對工作機
        做即時 SSH 目錄探測——這樣建立核准請求時不需要 SSH（見
        app/datasets.py 的設計說明），且不需要為此另外新增一張表。
        """
        with self.cursor() as cur:
            cur.execute(
                """
                SELECT 1 FROM jobs
                WHERE type = 'setup' AND project = ? AND server = ? AND status = 'done'
                LIMIT 1
                """,
                (project, server),
            )
            return cur.fetchone() is not None

    # ---- coding_runs CRUD（階段 13，PLAN.md N.6：Codex Worker v2）---------

    #: `update_coding_run()` 允許更新的欄位白名單，比照 `update_job`／
    #: `update_project` 的既有 whitelist 慣例（白名單外一律 raise
    #: ValueError）。刻意排除 `approval_id`/`project`/`runner_server`/
    #: `instruction`/`created_at`——這些是建立時就定案、不該被之後的
    #: dispatch/回填流程改動的欄位。
    _CODING_RUN_UPDATE_FIELDS = {
        "job_id",
        "base_branch",
        "base_commit",
        "result_branch",
        "result_commit",
        "worktree_path",
        "bundle_path",
        "validation_target",
        "codex_version",
        "status",
        "test_command",
        "test_exit_code",
        "started_at",
        "finished_at",
        "error_message",
    }

    def insert_coding_run(
        self,
        *,
        approval_id: int,
        project: str,
        runner_server: str,
        instruction: str,
        job_id: Optional[int] = None,
        base_branch: Optional[str] = None,
        base_commit: Optional[str] = None,
        result_branch: Optional[str] = None,
        result_commit: Optional[str] = None,
        worktree_path: Optional[str] = None,
        bundle_path: Optional[str] = None,
        validation_target: Optional[str] = None,
        codex_version: Optional[str] = None,
        status: str = "queued",
        test_command: Optional[str] = None,
        test_exit_code: Optional[int] = None,
        engineering_task_id: Optional[str] = None,
        project_version_id: Optional[str] = None,
        base_binding: str = "legacy_unpinned",
        attempt_number: Optional[int] = None,
    ) -> int:
        if base_binding not in VALID_CODING_BASE_BINDINGS:
            raise ValueError(f"invalid coding base binding: {base_binding}")
        if base_binding == "project_version_pinned":
            if not all(
                (
                    engineering_task_id,
                    project_version_id,
                    base_commit,
                    attempt_number is not None and attempt_number > 0,
                )
            ):
                raise ValueError("pinned coding run requires task/version/base/attempt")
        elif any(
            value is not None
            for value in (engineering_task_id, project_version_id, attempt_number)
        ):
            raise ValueError("legacy coding run cannot claim engineering task binding")
        with self._immediate_cursor() as cur:
            cur.execute(
                """
                INSERT INTO coding_runs
                    (approval_id, job_id, project, runner_server, instruction,
                     base_branch, base_commit, result_branch, result_commit,
                     worktree_path, bundle_path, validation_target, codex_version,
                     status, test_command, test_exit_code, engineering_task_id,
                     project_version_id, base_binding, attempt_number, created_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    approval_id,
                    job_id,
                    project,
                    runner_server,
                    instruction,
                    base_branch,
                    base_commit,
                    result_branch,
                    result_commit,
                    worktree_path,
                    bundle_path,
                    validation_target,
                    codex_version,
                    status,
                    test_command,
                    test_exit_code,
                    engineering_task_id,
                    project_version_id,
                    base_binding,
                    attempt_number,
                    now_iso(),
                ),
            )
            coding_run_id = int(cur.lastrowid)
            self.append_durable_audit_event_in_transaction(
                cur,
                action="run_created",
                params={
                    "project": project,
                    "runner_server": runner_server,
                    "base_binding": base_binding,
                    "status": status,
                    "engineering_bound": engineering_task_id is not None,
                },
                result="created",
                resource_type="coding_run",
                resource_id=str(coding_run_id),
                approval_id=approval_id,
                event_id=f"coding-run:{coding_run_id}:created",
            )
            return coding_run_id

    def get_coding_run(self, coding_run_id: int) -> Optional[CodingRun]:
        with self.cursor() as cur:
            cur.execute("SELECT * FROM coding_runs WHERE id = ?", (coding_run_id,))
            row = cur.fetchone()
            return CodingRun.from_row(row) if row else None

    def get_coding_run_by_job_id(self, job_id: int) -> Optional[CodingRun]:
        """依 `jobs.id` 找對應的 `coding_runs` 一列（PLAN.md N.6 回填）：
        `approve()` 建立 coding_run 時已經把 `job_id` 寫回去（見
        `update_coding_run(run_id, job_id=job.id)`），這裡只是反查。v1
        遺留的 coding job（沒有對應 coding_run）回傳 `None`，呼叫端
        （`app.jobfinish`）應該跳過回填、不當成錯誤。"""
        with self.cursor() as cur:
            cur.execute(
                "SELECT * FROM coding_runs WHERE job_id = ? ORDER BY id DESC LIMIT 1",
                (job_id,),
            )
            row = cur.fetchone()
            return CodingRun.from_row(row) if row else None

    def get_coding_run_by_engineering_attempt(
        self, task_id: str, attempt_number: int
    ) -> Optional[CodingRun]:
        with self.cursor() as cur:
            cur.execute(
                """
                SELECT * FROM coding_runs
                WHERE engineering_task_id = ? AND attempt_number = ?
                LIMIT 1
                """,
                (task_id, attempt_number),
            )
            row = cur.fetchone()
            return CodingRun.from_row(row) if row else None

    def list_coding_runs(
        self,
        status: Optional[str] = None,
        project: Optional[str] = None,
        limit: int = 50,
    ) -> list[CodingRun]:
        """新到舊（`id DESC`），比照其他「最近 N 筆」查詢的既有慣例。"""
        query = "SELECT * FROM coding_runs WHERE 1=1"
        params: list[Any] = []
        if status:
            query += " AND status = ?"
            params.append(status)
        if project:
            query += " AND project = ?"
            params.append(project)
        query += " ORDER BY id DESC LIMIT ?"
        params.append(limit)
        with self.cursor() as cur:
            cur.execute(query, params)
            return [CodingRun.from_row(r) for r in cur.fetchall()]

    def update_coding_run(
        self,
        coding_run_id: int,
        *,
        audit_action: Optional[str] = None,
        audit_params: Optional[dict[str, Any]] = None,
        audit_result: Optional[str] = None,
        audit_actor: Optional[AuditActor] = None,
        audit_event_id: Optional[str] = None,
        **fields: Any,
    ) -> None:
        """Update one CodingRun and optionally append its durable result event.

        The optional audit envelope is deliberately separate from the
        allowlisted ``coding_runs`` columns.  It is used by the legacy,
        unbound result collector: the canonical row update and its durable
        evidence must commit (or roll back) as one unit.  Bound Engineering
        Task runs keep their existing parent-task result event below.
        """
        if not fields:
            return
        invalid = set(fields) - self._CODING_RUN_UPDATE_FIELDS
        if invalid:
            raise ValueError(f"invalid coding_run field(s): {sorted(invalid)}")
        existing = self.get_coding_run(coding_run_id)
        if "base_commit" in fields:
            if (
                existing is not None
                and existing.base_binding == "project_version_pinned"
            ):
                if fields["base_commit"] != existing.base_commit:
                    raise ValueError("pinned coding_run base_commit is immutable")
                fields.pop("base_commit")
                if not fields:
                    return
        cols = ", ".join(f"{k} = ?" for k in fields)
        values = list(fields.values()) + [coding_run_id]
        result_event: Optional[dict[str, Any]] = None
        with self._immediate_cursor() as cur:
            cur.execute(f"UPDATE coding_runs SET {cols} WHERE id = ?", values)
            if audit_action is not None and cur.rowcount != 1:
                raise ValueError("coding_run not found")
            if audit_action is not None:
                actor_kwargs = (
                    {
                        "actor_id": audit_actor.id,
                        "actor_kind": audit_actor.kind,
                        "authentication": audit_actor.authentication,
                    }
                    if audit_actor is not None
                    else {}
                )
                self.append_durable_audit_event_in_transaction(
                    cur,
                    action=audit_action,
                    params=audit_params or {},
                    result=audit_result or "updated",
                    resource_type="coding_run",
                    resource_id=str(coding_run_id),
                    approval_id=(
                        int(existing.approval_id)
                        if existing is not None and existing.approval_id is not None
                        else None
                    ),
                    event_id=audit_event_id,
                    **actor_kwargs,
                )
            result_status = fields.get("status")
            if (
                existing is not None
                and existing.engineering_task_id is not None
                and result_status is not None
            ):
                cur.execute(
                    "SELECT status, approval_id FROM engineering_tasks WHERE id = ?",
                    (existing.engineering_task_id,),
                )
                task_row = cur.fetchone()
                previous_task_status = (
                    task_row["status"] if task_row is not None else None
                )
                timestamp = fields.get("finished_at") or now_iso()
                cur.execute(
                    """
                    UPDATE engineering_tasks
                    SET status = ?, updated_at = ?
                    WHERE id = ?
                    """,
                    (result_status, timestamp, existing.engineering_task_id),
                )
                if cur.rowcount == 1:
                    self.append_durable_audit_event_in_transaction(
                        cur,
                        action="engineering_task_result_recorded",
                        params={
                            "coding_run_id": int(coding_run_id),
                            "attempt_number": existing.attempt_number,
                            "result_status": result_status,
                            "previous_status": previous_task_status,
                            "new_status": result_status,
                        },
                        result=str(result_status),
                        resource_type="engineering_task",
                        resource_id=existing.engineering_task_id,
                        approval_id=(
                            int(task_row["approval_id"])
                            if task_row is not None and task_row["approval_id"] is not None
                            else None
                        ),
                        event_id=(
                            f"engineering-task:{existing.engineering_task_id}:"
                            f"coding-run:{coding_run_id}:result:{result_status}"
                        ),
                    )
                summary = {
                    "done": "結果已驗證並完成收集",
                    "no_changes": "結果已驗證；沒有產生程式變更",
                    "failed": "結果收集完成，執行結果為失敗",
                    "secret_violation": "結果因安全檢查違規而拒絕",
                    "path_policy_violation": "結果因路徑政策違規而拒絕",
                }.get(result_status, "Coding Runner 結果已完成收集")
                result_event = {
                    "task_id": existing.engineering_task_id,
                    "attempt_number": existing.attempt_number,
                    "event_key": (
                        f"coding-run:{coding_run_id}:result:{result_status}:"
                        f"{timestamp}"
                    ),
                    "event_type": "result_collected",
                    "phase": "complete",
                    "state": result_status,
                    "summary": summary,
                    "details": {
                        "coding_run_id": coding_run_id,
                        "job_id": existing.job_id,
                        "result_status": result_status,
                    },
                    "source_kind": "coding_run",
                    "source_id": str(coding_run_id),
                    "occurred_at": fields.get("finished_at"),
                }

        # Visibility is explicitly presentation-only.  Commit canonical
        # CodingRun + parent state first, then best-effort the idempotent event
        # in its own transaction.  A corrupt/conflicting journal row must never
        # roll the terminal result back and trigger repeated result pulls.
        if result_event is not None:
            try:
                self.append_engineering_task_event(**result_event)
            except Exception:  # noqa: BLE001 - canonical state already committed
                pass

    # ---- coding-run cleanup remote boundary ---------------------------

    @staticmethod
    def _coding_cleanup_audit_actor_kwargs(
        audit_actor: AuditActor | None,
    ) -> dict[str, str]:
        if audit_actor is None:
            return {}
        return {
            "actor_id": audit_actor.id,
            "actor_kind": audit_actor.kind,
            "authentication": audit_actor.authentication,
        }

    @staticmethod
    def _coding_cleanup_event_params(
        *,
        coding_run_id: int,
        approval_id: int,
        runner_server: str,
        cleanup_contract_sha256: str,
        prune_instance: bool,
    ) -> dict[str, Any]:
        """Return the path-free identity envelope for one cleanup operation."""

        return {
            "coding_run_id": coding_run_id,
            "approval_id": approval_id,
            "runner_server": runner_server,
            "cleanup_contract_sha256": cleanup_contract_sha256,
            "prune_instance": prune_instance,
        }

    def _get_coding_cleanup_intent_cur(
        self,
        cur: sqlite3.Cursor,
        *,
        coding_run_id: int,
        approval_id: int,
        runner_server: str,
        cleanup_contract_sha256: str,
        prune_instance: bool,
    ) -> sqlite3.Row:
        row = cur.execute(
            "SELECT id, approval_id, runner_server, status FROM coding_runs"
            " WHERE id = ?",
            (coding_run_id,),
        ).fetchone()
        if row is None:
            raise ValueError("coding_run not found")
        if (
            row["approval_id"] != approval_id
            or row["runner_server"] != runner_server
        ):
            raise ValueError("coding cleanup contract drifted")
        if row["status"] not in CODING_RUN_CLEANUP_TERMINAL_STATUSES:
            raise ValueError("coding run is not terminal")
        intent = cur.execute(
            "SELECT action, params_json FROM audit_events WHERE event_id = ?",
            (f"engineering-cleanup:{coding_run_id}:intent",),
        ).fetchone()
        expected_params = self._coding_cleanup_event_params(
            coding_run_id=coding_run_id,
            approval_id=approval_id,
            runner_server=runner_server,
            cleanup_contract_sha256=cleanup_contract_sha256,
            prune_instance=prune_instance,
        )
        if intent is not None:
            if (
                intent["action"] != "engineering_task_cleanup_intent"
                or json.loads(intent["params_json"] or "{}") != expected_params
            ):
                raise ValueError("coding cleanup intent contract drifted")
        else:
            raise ValueError("coding cleanup intent is missing")
        return row

    def begin_coding_cleanup_intent(
        self,
        *,
        coding_run_id: int,
        approval_id: int,
        runner_server: str,
        cleanup_contract_sha256: str,
        prune_instance: bool,
        audit_actor: AuditActor | None = None,
    ) -> dict[str, Any]:
        """Claim one remote coding-run cleanup before its first SSH write.

        Cleanup is a compensating remote mutation rather than an approval
        decision.  A deterministic intent/outcome pair makes a response-loss
        window fail closed: an existing intent without an outcome is converted
        to ``unknown`` and never replayed automatically.
        """

        if (
            isinstance(coding_run_id, bool)
            or not isinstance(coding_run_id, int)
            or coding_run_id <= 0
            or isinstance(approval_id, bool)
            or not isinstance(approval_id, int)
            or approval_id <= 0
        ):
            raise ValueError("coding cleanup identifiers are invalid")
        if not isinstance(runner_server, str) or not runner_server:
            raise ValueError("coding cleanup runner is required")
        if not _is_full_hex_digest(cleanup_contract_sha256):
            raise ValueError("coding cleanup contract digest is invalid")
        if not isinstance(prune_instance, bool):
            raise ValueError("coding cleanup prune flag is invalid")
        with self._immediate_cursor() as cur:
            intent_event_id = f"engineering-cleanup:{coding_run_id}:intent"
            outcome_event_id = f"engineering-cleanup:{coding_run_id}:outcome"
            expected_params = self._coding_cleanup_event_params(
                coding_run_id=coding_run_id,
                approval_id=approval_id,
                runner_server=runner_server,
                cleanup_contract_sha256=cleanup_contract_sha256,
                prune_instance=prune_instance,
            )
            run = cur.execute(
                "SELECT id, approval_id, runner_server, status FROM coding_runs"
                " WHERE id = ?",
                (coding_run_id,),
            ).fetchone()
            if run is None:
                raise ValueError("coding_run not found")
            if (
                run["approval_id"] != approval_id
                or run["runner_server"] != runner_server
            ):
                raise ValueError("coding cleanup contract drifted")
            if run["status"] not in CODING_RUN_CLEANUP_TERMINAL_STATUSES:
                raise ValueError("coding run is not terminal")

            intent = cur.execute(
                "SELECT action, params_json FROM audit_events WHERE event_id = ?",
                (intent_event_id,),
            ).fetchone()
            outcome = cur.execute(
                "SELECT action, result, params_json FROM audit_events"
                " WHERE event_id = ?",
                (outcome_event_id,),
            ).fetchone()
            if intent is not None and (
                intent["action"] != "engineering_task_cleanup_intent"
                or json.loads(intent["params_json"] or "{}") != expected_params
            ):
                raise ValueError("coding cleanup intent contract drifted")
            if outcome is not None:
                if outcome["action"] != "engineering_task_cleanup_outcome":
                    raise ValueError("coding cleanup outcome contract drifted")
                if outcome["result"] == "applied":
                    return {"state": "applied"}
                return {"state": "unknown"}
            if intent is not None:
                self.append_durable_audit_event_in_transaction(
                    cur,
                    action="engineering_task_cleanup_outcome",
                    params={**expected_params, "outcome_reason": "intent_recovery_required"},
                    result="unknown",
                    resource_type="coding_run",
                    resource_id=str(coding_run_id),
                    approval_id=approval_id,
                    event_id=outcome_event_id,
                    **self._coding_cleanup_audit_actor_kwargs(audit_actor),
                )
                return {"state": "unknown"}
            self.append_durable_audit_event_in_transaction(
                cur,
                action="engineering_task_cleanup_intent",
                params=expected_params,
                result="intent",
                resource_type="coding_run",
                resource_id=str(coding_run_id),
                approval_id=approval_id,
                event_id=intent_event_id,
                **self._coding_cleanup_audit_actor_kwargs(audit_actor),
            )
            return {"state": "started"}

    def record_coding_cleanup_unknown(
        self,
        *,
        coding_run_id: int,
        approval_id: int,
        runner_server: str,
        cleanup_contract_sha256: str,
        prune_instance: bool,
        outcome_reason: str = "remote_response_unknown",
        audit_actor: AuditActor | None = None,
    ) -> None:
        """Record an ambiguous remote cleanup without changing local state."""

        if not isinstance(outcome_reason, str) or not outcome_reason or any(
            character
            not in "abcdefghijklmnopqrstuvwxyz0123456789._-"
            for character in outcome_reason
        ):
            raise ValueError("invalid coding cleanup outcome reason")
        with self._immediate_cursor() as cur:
            self._get_coding_cleanup_intent_cur(
                cur,
                coding_run_id=coding_run_id,
                approval_id=approval_id,
                runner_server=runner_server,
                cleanup_contract_sha256=cleanup_contract_sha256,
                prune_instance=prune_instance,
            )
            event_id = f"engineering-cleanup:{coding_run_id}:outcome"
            existing = cur.execute(
                "SELECT action, result FROM audit_events WHERE event_id = ?",
                (event_id,),
            ).fetchone()
            if existing is not None:
                if existing["action"] != "engineering_task_cleanup_outcome":
                    raise ValueError("coding cleanup outcome contract drifted")
                return
            params = self._coding_cleanup_event_params(
                coding_run_id=coding_run_id,
                approval_id=approval_id,
                runner_server=runner_server,
                cleanup_contract_sha256=cleanup_contract_sha256,
                prune_instance=prune_instance,
            )
            params["outcome_reason"] = outcome_reason
            self.append_durable_audit_event_in_transaction(
                cur,
                action="engineering_task_cleanup_outcome",
                params=params,
                result="unknown",
                resource_type="coding_run",
                resource_id=str(coding_run_id),
                approval_id=approval_id,
                event_id=event_id,
                **self._coding_cleanup_audit_actor_kwargs(audit_actor),
            )

    def finalize_coding_cleanup_outcome(
        self,
        *,
        coding_run_id: int,
        approval_id: int,
        runner_server: str,
        cleanup_contract_sha256: str,
        prune_instance: bool,
        audit_actor: AuditActor | None = None,
    ) -> CodingRun:
        """Commit the local cleanup projection and applied outcome together."""

        with self._immediate_cursor() as cur:
            _run = self._get_coding_cleanup_intent_cur(
                cur,
                coding_run_id=coding_run_id,
                approval_id=approval_id,
                runner_server=runner_server,
                cleanup_contract_sha256=cleanup_contract_sha256,
                prune_instance=prune_instance,
            )
            outcome_event_id = f"engineering-cleanup:{coding_run_id}:outcome"
            outcome = cur.execute(
                "SELECT action, result FROM audit_events WHERE event_id = ?",
                (outcome_event_id,),
            ).fetchone()
            if outcome is not None:
                if outcome["action"] != "engineering_task_cleanup_outcome":
                    raise ValueError("coding cleanup outcome contract drifted")
                if outcome["result"] != "applied":
                    raise ValueError("coding cleanup outcome is unknown")
                row = cur.execute(
                    "SELECT * FROM coding_runs WHERE id = ?", (coding_run_id,)
                ).fetchone()
                if row is None:  # pragma: no cover - guarded by intent lookup
                    raise ValueError("coding_run disappeared")
                return CodingRun.from_row(row)
            cur.execute(
                "UPDATE coding_runs SET worktree_path = NULL WHERE id = ?",
                (coding_run_id,),
            )
            if cur.rowcount != 1:
                raise ValueError("coding cleanup projection update lost")
            params = self._coding_cleanup_event_params(
                coding_run_id=coding_run_id,
                approval_id=approval_id,
                runner_server=runner_server,
                cleanup_contract_sha256=cleanup_contract_sha256,
                prune_instance=prune_instance,
            )
            params["worktree_cleared"] = True
            self.append_durable_audit_event_in_transaction(
                cur,
                action="engineering_task_cleanup_outcome",
                params=params,
                result="applied",
                resource_type="coding_run",
                resource_id=str(coding_run_id),
                approval_id=approval_id,
                event_id=outcome_event_id,
                **self._coding_cleanup_audit_actor_kwargs(audit_actor),
            )
            row = cur.execute(
                "SELECT * FROM coding_runs WHERE id = ?", (coding_run_id,)
            ).fetchone()
            if row is None:  # pragma: no cover - guarded by update above
                raise ValueError("coding_run disappeared")
            return CodingRun.from_row(row)

    # ---- experiment_records CRUD（專案詳情頁：實驗紀錄時間軸）--------------

    #: `update_experiment_record()` 允許更新的欄位白名單，比照
    #: `_CODING_RUN_UPDATE_FIELDS` 的既有慣例——刻意排除 `project`/`author`/
    #: `job_id`/`coding_run_id`/`created_at`：這些是建立時就定案的欄位，
    #: `author` 尤其不該事後被改成別的身分（見 `POST/PATCH
    #: /projects/{name}/records` 的稽核設計）。
    _EXPERIMENT_RECORD_UPDATE_FIELDS = {"title", "content", "kind"}

    @staticmethod
    def _experiment_record_audit_actor_kwargs(
        audit_actor: AuditActor | None,
    ) -> dict[str, str]:
        """Project a record writer onto the narrow durable actor envelope."""

        if audit_actor is None:
            return {}
        return {
            "actor_id": audit_actor.id,
            "actor_kind": audit_actor.kind,
            "authentication": audit_actor.authentication,
        }

    def _append_experiment_record_audit_event(
        self,
        cursor: sqlite3.Cursor,
        *,
        action: str,
        result: str,
        record_id: int,
        params: dict[str, Any],
        event_id: str,
        audit_actor: AuditActor | None,
    ) -> None:
        """Append a bounded experiment-record event in its write UoW.

        Record content and titles are intentionally excluded: the immutable
        ledger carries identity, lifecycle, and field names only.  The row is
        the source of truth for the user-authored text.
        """

        self.append_durable_audit_event_in_transaction(
            cursor,
            action=action,
            params=params,
            result=result,
            resource_type="experiment_record",
            resource_id=str(record_id),
            event_id=event_id,
            **self._experiment_record_audit_actor_kwargs(audit_actor),
        )

    def insert_experiment_record(
        self,
        project: str,
        content: str,
        kind: str = "note",
        title: Optional[str] = None,
        author: str = "user",
        job_id: Optional[int] = None,
        coding_run_id: Optional[int] = None,
        extra: Optional[dict] = None,
        audit_actor: AuditActor | None = None,
    ) -> int:
        if kind not in VALID_RECORD_KINDS:
            raise ValueError(f"invalid experiment record kind: {kind}")
        _validate_record_author(author)
        now = now_iso()
        with self._immediate_cursor() as cur:
            cur.execute(
                """
                INSERT INTO experiment_records
                    (project, kind, title, content, author, job_id, coding_run_id,
                     extra, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    project,
                    kind,
                    title,
                    content,
                    author,
                    job_id,
                    coding_run_id,
                    json.dumps(extra or {}),
                    now,
                    now,
                ),
            )
            record_id = int(cur.lastrowid)
            self._append_experiment_record_audit_event(
                cur,
                action="experiment_record_created",
                result="created",
                record_id=record_id,
                params={
                    "project": project,
                    "record_id": record_id,
                    "kind": kind,
                    "author": author,
                    "job_linked": job_id is not None,
                    "coding_run_linked": coding_run_id is not None,
                },
                event_id=f"experiment-record:{record_id}:created",
                audit_actor=audit_actor,
            )
            return record_id

    def get_experiment_record(self, record_id: int) -> Optional[ExperimentRecord]:
        with self.cursor() as cur:
            cur.execute("SELECT * FROM experiment_records WHERE id = ?", (record_id,))
            row = cur.fetchone()
            return ExperimentRecord.from_row(row) if row else None

    def list_experiment_records(
        self,
        project: str,
        q: Optional[str] = None,
        kind: Optional[str] = None,
        limit: int = 20,
        before_ts: Optional[str] = None,
    ) -> list[ExperimentRecord]:
        """新到舊（`created_at DESC`，同一微秒內以 `id DESC` 當 tie-break）。
        `q` 對 `title`/`content` 做簡單 LIKE 搜尋；`before_ts` 是游標，
        `created_at < before_ts`——`app/records.py` 的 `build_timeline()`
        對這個游標選字串比較（而不是額外開一個 id 游標）的取捨有完整說明：
        `now_iso()` 含微秒，字典序比較足夠安全，碰撞機率可忽略。"""
        query = "SELECT * FROM experiment_records WHERE project = ?"
        params: list[Any] = [project]
        if kind:
            query += " AND kind = ?"
            params.append(kind)
        if q:
            query += " AND (title LIKE ? OR content LIKE ?)"
            like = f"%{q}%"
            params.extend([like, like])
        if before_ts:
            query += " AND created_at < ?"
            params.append(before_ts)
        query += " ORDER BY created_at DESC, id DESC LIMIT ?"
        params.append(limit)
        with self.cursor() as cur:
            cur.execute(query, params)
            return [ExperimentRecord.from_row(r) for r in cur.fetchall()]

    def update_experiment_record(
        self,
        record_id: int,
        *,
        audit_actor: AuditActor | None = None,
        **fields: Any,
    ) -> None:
        """白名單 `title`/`content`/`kind`（比照 `update_coding_run()`），
        自動更新 `updated_at`（比照 `update_dataset_card()` 一帶「補登/更新
        要更新時間戳」的既有慣例）。`kind` 有帶時一樣要通過
        `VALID_RECORD_KINDS` 驗證。"""
        if not fields:
            return
        invalid = set(fields) - self._EXPERIMENT_RECORD_UPDATE_FIELDS
        if invalid:
            raise ValueError(f"invalid experiment record field(s): {sorted(invalid)}")
        if "kind" in fields and fields["kind"] not in VALID_RECORD_KINDS:
            raise ValueError(f"invalid experiment record kind: {fields['kind']}")
        fields = dict(fields)
        changed_fields = sorted(fields)
        fields["updated_at"] = now_iso()
        cols = ", ".join(f"{k} = ?" for k in fields)
        values = list(fields.values()) + [record_id]
        with self._immediate_cursor() as cur:
            row = cur.execute(
                "SELECT project FROM experiment_records WHERE id = ?", (record_id,)
            ).fetchone()
            if row is None:
                return
            cur.execute(f"UPDATE experiment_records SET {cols} WHERE id = ?", values)
            self._append_experiment_record_audit_event(
                cur,
                action="experiment_record_updated",
                result="updated",
                record_id=record_id,
                params={
                    "project": str(row["project"]),
                    "record_id": record_id,
                    "fields": changed_fields,
                },
                event_id=f"experiment-record:{record_id}:updated:{uuid.uuid4()}",
                audit_actor=audit_actor,
            )

    def delete_experiment_record(
        self, record_id: int, *, audit_actor: AuditActor | None = None
    ) -> None:
        with self._immediate_cursor() as cur:
            row = cur.execute(
                "SELECT project FROM experiment_records WHERE id = ?", (record_id,)
            ).fetchone()
            if row is None:
                return
            cur.execute("DELETE FROM experiment_records WHERE id = ?", (record_id,))
            self._append_experiment_record_audit_event(
                cur,
                action="experiment_record_deleted",
                result="deleted",
                record_id=record_id,
                params={"project": str(row["project"]), "record_id": record_id},
                event_id=f"experiment-record:{record_id}:deleted",
                audit_actor=audit_actor,
            )
